_ab_allow_norm() {
	tr 'A-Z' 'a-z' | sed 's/#.*//; s/^[[:space:]]*//; s/[[:space:]].*$//; s#^[a-z]*://##; s#[/:?].*$##; s/^\*\.//; s/^\.//; s/\.$//' |
		grep -E '^[a-z0-9_]([a-z0-9_-]*[a-z0-9_])?(\.[a-z0-9_]([a-z0-9_-]*[a-z0-9_])?)+$' | awk '!s[$0]++' | head -n 500
}

_ab_allow_text() { if [ -f "$AB_ALLOW" ]; then cat "$AB_ALLOW"; else printf '%s\n' "$AB_ALLOW_DEFAULT"; fi; }

_ab_block_text() { cat "$AB_BLOCK" 2>/dev/null; return 0; }

_ab_dl() {
	local id="$1" f tmp="$JOBS_DIR/adblock.$1.dl" dom="$JOBS_DIR/adblock.$1.dom" url host n min ver ok=0 urls
	f="$(_ab_file "$id")" || return 1
	min="$(_ab_min "$id")"
	mkdir -p "$AB_DIR/src"
	case "$id" in
		t_*) urls="$ST_TCH_RAW/release/domains/$f $ST_TCH_CDN/release/domains/$f" ;;
		*) urls="$AB_URL_GH/$f $AB_URL_CDN/$f" ;;
	esac
	for url in $urls; do
		host="$(printf '%s' "$url" | sed 's#^https://\([^/]*\).*#\1#')"
		echo "   → Скачиваем $(_ab_title "$id") ($host)"
		rm -f "$tmp"
		if _zm_fetch "$url" "$tmp" 240; then
			case "$id" in
				t_*) tr -d '\r' < "$tmp" | awk '{ d = tolower($1); sub(/^\*\./, "", d); sub(/^\./, "", d); if (d ~ /^[a-z0-9_]([a-z0-9_-]*[a-z0-9_])?(\.[a-z0-9_]([a-z0-9_-]*[a-z0-9_])?)+$/ && d !~ /^[0-9.]+$/) print d }' > "$dom" ;;
				*) awk -F/ '/^(local|address|server)=\/[^\/]+\// { d = tolower($2); if (d ~ /^[a-z0-9_.-]+$/ && index(d, ".")) print d }' "$tmp" > "$dom" ;;
			esac
			n="$(wc -l < "$dom" | tr -d ' ')"
			if [ "${n:-0}" -ge "$min" ]; then ok=1; break; fi
			echo "   ! Получен неполный файл ($(_ab_dom "${n:-0}")) — пробуем другой адрес"
		else
			echo "   ! Не скачалось: $ZM_FETCH_ERR"
		fi
	done
	if [ "$ok" != 1 ]; then rm -f "$tmp" "$dom"; return 1; fi
	ver="$(sed -n 's/^# Version: *//p' "$tmp" | head -n1 | tr -cd '0-9.')"
	rm -f "$tmp"
	if _ab_gz; then
		gzip -c "$dom" > "$AB_DIR/src/$id.gz.zm-new" && mv -f "$AB_DIR/src/$id.gz.zm-new" "$AB_DIR/src/$id.gz" && rm -f "$AB_DIR/src/$id.txt"
	else
		mv -f "$dom" "$AB_DIR/src/$id.txt" && rm -f "$AB_DIR/src/$id.gz"
	fi
	rm -f "$dom" "$AB_DIR/src/$id."*.zm-new
	_ab_put "n_$id" "$n" "v_$id" "$ver" "t_$id" "$(date +%s)"
	echo "   ✓ $(_ab_title "$id"): $(_ab_dom "$n")${ver:+, версия $ver}"
	return 0
}

_ab_build() {
	local out="$1" ids id allow="$JOBS_DIR/adblock.allow" blk="$JOBS_DIR/adblock.block" dedup=0 n need=0 avail rc
	ids="$(_ab_ids)"
	rm -f "$out.note"
	for id in $ids; do _ab_src "$id" >/dev/null || case "$id" in t_*) ;; *) echo "нет скачанного списка $(_ab_title "$id")" >&2; return 1 ;; esac; done
	ids="$(for id in $ids; do case "$id" in t_*) _ab_src "$id" >/dev/null && echo "$id" ;; *) echo "$id" ;; esac; done | tr '\n' ' ')"
	set -- $ids; [ $# -gt 1 ] && dedup=1
	if [ "$dedup" = 1 ]; then
		for id in $ids; do n="$(_ab_get "n_$id" 0)"; case "$n" in ''|*[!0-9]*) n=0 ;; esac; need=$((need + n)); done
		need=$((need / 12 + 24576))
		avail="$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null)"
		if [ -n "$avail" ] && [ "$avail" -lt "$need" ]; then
			dedup=0
			echo "   · Памяти впритык — повторы между списками не убираем: так сборке нужно в 20 раз меньше памяти, а dnsmasq повторы просто пропускает" > "$out.note"
		fi
	fi
	{ _ab_allow_text | _ab_allow_norm; _ab_own_hosts | _ab_allow_norm; } | awk '!s[$0]++' > "$allow"
	_ab_block_text | _ab_allow_norm > "$blk"
	_ab_dns_now > "$AB_DNS_STAMP" 2>/dev/null
	while :; do
		_ab_build_run "$ids" "$allow" "$blk" "$dedup" "$out"; rc=$?
		[ "$rc" = 0 ] && break
		rm -f "$out" "$out.count"
		if [ "$rc" -ge 128 ] && [ "$dedup" = 1 ]; then
			dedup=0
			echo "   · Сборку закрыла система — не хватило памяти. Собираем ещё раз в экономном режиме, без удаления повторов между списками" > "$out.note"
			continue
		fi
		rm -f "$allow" "$blk"
		if [ "$rc" -ge 128 ]; then echo "роутеру не хватило оперативной памяти, чтобы собрать список, — выберите список поменьше или выключите защиту от фишинга" >&2
		else echo "не удалось собрать список (код $rc)" >&2; fi
		return 1
	done
	rm -f "$allow" "$blk"
	n="$(cat "$out.count" 2>/dev/null)"; rm -f "$out.count"
	[ "${n:-0}" -gt 0 ] || { echo "список получился пустым" >&2; return 1; }
	echo "$n"
}

_ab_build_run() {
	local ids="$1" allow="$2" blk="$3" dedup="$4" out="$5" id
	( { for id in $ids; do _ab_cat "$id"; done; } | awk -v af="$allow" -v bf="$blk" -v dedup="$dedup" -v cf="$out.count" '
		BEGIN {
			while ((getline l < af) > 0) if (l != "") A[l] = 1; close(af)
			while ((getline l < bf) > 0) if (l != "" && !(l in K)) { K[l] = 1; print "local=/" l "/"; n++ }
			close(bf)
		}
		{
			d = $0
			if (d == "" || (d in K)) next
			if (dedup) { if (d in S) next; S[d] = 1 }
			x = d
			while (1) {
				if (x in A) next
				i = index(x, "."); if (!i) break
				x = substr(x, i + 1)
			}
			print "local=/" d "/"; n++
		}
		END { for (a in A) if (!(a in K)) print "server=/" a "/#"; print n + 0 > cf }' > "$out" ) 2>/dev/null
}

_ab_install() {
	local new="$1" d dirs bak="$JOBS_DIR/adblock.old" t=0 had=0 rc
	dirs="$(_ab_dirs)"
	_ab_stats_on && _ab_lf_take
	( dnsmasq --test --conf-file="$new" ) >/dev/null 2>&1; rc=$?
	if [ "$rc" -ge 128 ]; then
		echo "   · Заранее проверить список не хватило памяти — проверим запуском: если dnsmasq не поднимется, вернём прежнее состояние"
	elif [ "$rc" != 0 ]; then
		echo "ОШИБКА: dnsmasq не принял собранный список — ничего не меняем"
		return 1
	fi
	rm -f "$bak"
	for d in $dirs; do [ -s "$d/$AB_NAME" ] && { cp -f "$d/$AB_NAME" "$bak" 2>/dev/null && had=1; break; }; done
	for d in $dirs; do
		mkdir -p "$d" && cp -f "$new" "$d/$AB_NAME.zm-tmp" && mv -f "$d/$AB_NAME.zm-tmp" "$d/$AB_NAME" || {
			echo "ОШИБКА: не хватило места в памяти роутера для списка — возвращаем прежнее состояние"
			rm -f "$d/$AB_NAME.zm-tmp"
			for d in $dirs; do
				if [ "$had" = 1 ] && [ -s "$bak" ]; then cp -f "$bak" "$d/$AB_NAME" 2>/dev/null || rm -f "$d/$AB_NAME"
				else rm -f "$d/$AB_NAME"; fi
			done
			rm -f "$bak"
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			return 1
		}
		_ab_stats_on && _ab_stats_text "$d" > "$d/$AB_STATS_CONF"
	done
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	while [ "$t" -lt 30 ]; do
		sleep 2; t=$((t + 2))
		_ab_dns_alive && { rm -f "$bak"; return 0; }
	done
	echo "!! dnsmasq не отвечает с новым списком — возвращаем прежнее состояние"
	for d in $dirs; do
		if [ "$had" = 1 ]; then cp -f "$bak" "$d/$AB_NAME"; else rm -f "$d/$AB_NAME"; fi
	done
	rm -f "$bak"
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	_ab_stats_guard >/dev/null 2>&1 || echo "!! dnsmasq не запускался и со статистикой — статистика выключена"
	return 1
}

_ab_alldirs() { { _ab_dirs; echo /tmp/dnsmasq.d; ls -d /tmp/dnsmasq.*.d 2>/dev/null; uci -q show dhcp 2>/dev/null | sed -n "s/^dhcp\.[^.]*\.confdir='\(.*\)'\$/\1/p"; } | sort -u; }

_ab_unplug() {
	local d
	for d in $(_ab_alldirs); do
		[ -d "$d" ] || continue
		rm -f "$d/$AB_NAME" "$d/$AB_NAME.zm-tmp"
	done
}

_ab_stats_on() { [ "$(_ab_get stats 0)" = 1 ]; }

_ab_steer_dns() {
	stl_running 2>/dev/null || return 1
	command -v netstat >/dev/null 2>&1 || return 0
	netstat -lnu 2>/dev/null | grep -qE '[:.]5300[[:space:]]'
}

_ab_kw_in() {
	local kw="$1" f
	shift
	for f in "$@"; do
		[ -f "$f" ] || continue
		case "$f" in */"$AB_STATS_CONF") continue ;; esac
		grep -qs "^[[:space:]]*$kw\([[:space:]]*=\|[[:space:]]*\$\)" "$f" && return 0
	done
	return 1
}

_ab_kw_used() {
	local kw="$1" d="$2" f
	_ab_kw_in "$kw" /etc/dnsmasq.conf "$d"/* && return 0
	[ "$3" = gen ] || return 1
	for f in /var/etc/dnsmasq.conf.*; do
		grep -qs "^conf-dir=$d\(,\|\$\)" "$f" && _ab_kw_in "$kw" "$f" && return 0
	done
	return 1
}

_ab_stats_text() {
	echo "# Zapret Manager: статистика блокировки рекламы"
	echo "log-queries=extra"
	_ab_kw_used log-async "$1" gen || echo "log-async=25"
	_ab_kw_used log-facility "$1" || echo "log-facility=$AB_STATS_LOG"
}

_ab_lf_take() {
	local sec v ch=0
	for sec in $(_dn_secs); do
		v="$(uci -q get "dhcp.$sec.logfacility")"
		[ -n "$v" ] || continue
		mkdir -p "$AB_DIR"
		grep -q "^$sec|" "$AB_LF" 2>/dev/null || printf '%s|%s\n' "$sec" "$v" >> "$AB_LF"
		uci -q delete "dhcp.$sec.logfacility" && ch=1
	done
	[ "$ch" = 1 ] && { uci -q commit dhcp; logger -t zapret-manager "Блокировка рекламы: журнал dnsmasq на время статистики ведёт панель, прежняя настройка вернётся при её выключении"; }
	return 0
}

_ab_lf_restore() {
	local sec v ch=0
	[ -s "$AB_LF" ] || { rm -f "$AB_LF"; return 0; }
	while IFS='|' read -r sec v; do
		[ -n "$sec" ] && [ -n "$v" ] || continue
		uci -q get "dhcp.$sec" >/dev/null || continue
		[ -n "$(uci -q get "dhcp.$sec.logfacility")" ] && continue
		uci -q set "dhcp.$sec.logfacility=$v" && ch=1
	done < "$AB_LF"
	[ "$ch" = 1 ] && uci -q commit dhcp
	rm -f "$AB_LF"
	return 0
}

_ab_stats_plug() {
	local d
	_ab_lf_take
	for d in $(_ab_dirs); do mkdir -p "$d" && _ab_stats_text "$d" > "${d:?}/$AB_STATS_CONF"; done
}

_ab_stats_unplug() {
	local d
	for d in $(_ab_alldirs); do [ -d "$d" ] && rm -f "${d:?}/$AB_STATS_CONF"; done
	_ab_lf_restore
}

_ab_stats_guard() {
	local t=0
	_ab_stats_on || return 0
	while [ "$t" -lt 12 ]; do _ab_dns_alive && return 0; sleep 2; t=$((t + 2)); done
	_ab_put stats 0
	_ab_stats_unplug
	_ab_stats_cron off
	/etc/init.d/dnsmasq restart >/dev/null 2>&1
	logger -t zapret-manager "Блокировка рекламы: dnsmasq не запустился со статистикой — статистика выключена, DNS работает как раньше"
	return 1
}

_ab_stats_reset() {
	local lk="$AB_STATS_DIR/.lock" t=0
	mkdir -p "$AB_STATS_DIR"
	while ! mkdir "$lk" 2>/dev/null; do
		[ -n "$(find "$lk" -maxdepth 0 -mmin +2 2>/dev/null)" ] && { rmdir "$lk" 2>/dev/null; continue; }
		t=$((t + 1)); [ "$t" -gt 10 ] && return 1
		sleep 1
	done
	[ -f "$AB_STATS_LOG" ] && : > "$AB_STATS_LOG"
	rm -f "$AB_STATS_DIR"/h.* "$AB_STATS_DIR/folded" "$AB_STATS_DIR/jb" "$AB_STATS_DIR/ja" "$AB_STATS_DIR"/chunk.* "$AB_STATS_DIR"/devmap.*
	rm -f "$AB_STATS_ALL" "$AB_STATS_ALL.zm" "$AB_STATS_ALL.c" "$AB_STATS_ALL.new"
	_ab_put stats_since "$(date +%s)"
	if nft list table inet "$AB_IP_NFT" >/dev/null 2>&1; then echo "$(_ab_ip_tbl) $(_ab_ip_hits)" > "$JOBS_DIR/adblock.ip.hits0"; else rm -f "$JOBS_DIR/adblock.ip.hits0"; fi
	rmdir "$lk" 2>/dev/null
	return 0
}

_ab_stats_wipe() {
	rm -rf "$AB_STATS_DIR"
	rm -f "$AB_STATS_LOG" "$AB_STATS_ALL" "$AB_STATS_ALL.zm" "$AB_STATS_ALL.c" "$AB_STATS_ALL.new"
	return 0
}

_ab_stats_cron() {
	local line="*/2 * * * * /opt/zapret-manager-luci/backend.sh adblock_stats_tick >/dev/null 2>&1 $AB_STATS_CRON"
	if [ "$1" = on ]; then
		grep -qxF "$line" "$CRON_FILE" 2>/dev/null && return 0
		mkdir -p "$(dirname "$CRON_FILE")"; touch "$CRON_FILE"
		grep -vF "$AB_STATS_CRON" "$CRON_FILE" > "$CRON_FILE.zm" 2>/dev/null; cat "$CRON_FILE.zm" > "$CRON_FILE"; rm -f "$CRON_FILE.zm"
		echo "$line" >> "$CRON_FILE"
	else
		grep -qF "$AB_STATS_CRON" "$CRON_FILE" 2>/dev/null || return 0
		grep -vF "$AB_STATS_CRON" "$CRON_FILE" > "$CRON_FILE.zm" 2>/dev/null; cat "$CRON_FILE.zm" > "$CRON_FILE"; rm -f "$CRON_FILE.zm"
	fi
	/etc/init.d/cron restart >/dev/null 2>&1
	return 0
}

_ab_jcap() {
	local v
	v="$(_ab_get jsize 2500)"
	case "$v" in 0|800|2500|8000) echo "$v" ;; *) echo 2500 ;; esac
}

_ab_jtrim() {
	local n
	[ -f "$1" ] || return 0
	n="$(wc -l 2>/dev/null < "$1")"
	[ "${n:-0}" -gt "$2" ] 2>/dev/null || return 0
	tail -n "$2" "$1" > "$1.t" 2>/dev/null && mv -f "$1.t" "$1"
	rm -f "$1.t"
}

adblock_stats_tick() {
	local lk="$AB_STATS_DIR/.lock" tmp hf hour lan t=0 jc now sod
	_ab_stats_on || return 0
	mkdir -p "$AB_STATS_DIR"
	while ! mkdir "$lk" 2>/dev/null; do
		[ -n "$(find "$lk" -maxdepth 0 -mmin +2 2>/dev/null)" ] && { rmdir "$lk" 2>/dev/null; continue; }
		t=$((t + 1)); [ "$t" -gt 10 ] && return 0
		sleep 1
	done
	tmp="$AB_STATS_DIR/chunk.$$"
	if [ -s "$AB_STATS_LOG" ]; then
		cat "$AB_STATS_LOG" > "$tmp" 2>/dev/null && : > "$AB_STATS_LOG"
		hour=$(( $(date +%s) / 3600 )); hf="$AB_STATS_DIR/h.$hour"
		lan="$(sed -n 's#^local=/\([^/]*\)/$#\1#p' /var/etc/dnsmasq.conf.* 2>/dev/null | sort -u | tr '\n' ' ')"
		jc="$(_ab_jcap)"; now="$(date +%s)"; sod="$(date +%H:%M:%S | awk -F: '{ print $1 * 3600 + $2 * 60 + $3 }')"
		awk -v lan="$lan" -v hf="$hf" -v other="$tmp.other" -v jn="$([ "$jc" -gt 0 ] && echo 1 || echo 0)" -v jf="$tmp.j" -v now="$now" -v mid="$((now - ${sod:-0}))" -v st="$(_ab_steer_dns && echo 1)" '
			function lts(p,   h, mi, s, t) {
				if (!match(p, /[0-9][0-9]:[0-9][0-9]:[0-9][0-9]/)) return now
				h = substr(p, RSTART, 2) + 0; mi = substr(p, RSTART + 3, 2) + 0; s = substr(p, RSTART + 6, 2) + 0
				t = mid + h * 3600 + mi * 60 + s
				if (t > now + 300) t -= 86400
				return t
			}
			BEGIN {
				nl = split(lan, L, " ")
				while ((getline l < hf) > 0) {
					split(l, a, " ")
					if (a[1] == "T") T += a[2]; else if (a[1] == "B") B += a[2]
					else if (a[1] == "C") C[a[2]] += a[3]; else if (a[1] == "X") X[a[2]] += a[3]; else if (a[1] == "D") D[a[2]] += a[3]
				}
				close(hf)
			}
			function local_name(n,   i) {
				if (index(n, ".") == 0) return 1
				for (i = 1; i <= nl; i++) if (n == L[i] || substr(n, length(n) - length(L[i])) == "." L[i]) return 1
				return 0
			}
			match($0, /dnsmasq\[[0-9]+\]: [0-9]+ /) {
				sid = substr($0, RSTART, RLENGTH); sub(/^.*: /, "", sid); sub(/ +$/, "", sid)
				pre = substr($0, 1, RSTART - 1)
				m = split(substr($0, RSTART + RLENGTH), f, " ")
				i = 1; cl = ""
				if (f[1] ~ /\/[0-9]+$/) { cl = f[1]; sub(/\/[0-9]+$/, "", cl); i = 2 }
				jcl = st && (cl == "127.0.0.1" || cl == "::1") ? "s" : cl
				if (f[i] ~ /^query\[/) {
					T++; if (cl != "") C[cl]++
					if (jn && cl != "") { n = tolower(f[i + 1]); if (n != "" && !local_name(n) && n !~ /\.arpa$/) { Q[sid] = n; QC[sid] = jcl; QT[sid] = lts(pre) } }
					next
				}
				if (f[i] == "config" && f[i + 2] == "is" && f[i + 3] ~ /^(NXDOMAIN|NODATA)/) {
					n = tolower(f[i + 1])
					if (local_name(n)) next
					B++; D[n]++; if (cl != "") X[cl]++
					if (jn && cl != "") { BL[sid] = 1; k = jcl "\t" n; JB[k]++; t = lts(pre); if (t > JBT[k]) JBT[k] = t }
				}
				next
			}
			NF { print > other }
			END {
				print "T " T + 0; print "B " B + 0
				for (k in C) print "C " k " " C[k]
				for (k in X) print "X " k " " X[k]
				for (k in D) print "D " k " " D[k]
				if (jn) {
					for (s in Q) if (!(s in BL)) { k = QC[s] "\t" Q[s]; JA[k]++; if (QT[s] > JAT[k]) JAT[k] = QT[s] }
					for (k in JB) printf "B\t%d\t%s\t%d\n", JBT[k], k, JB[k] > jf
					for (k in JA) printf "A\t%d\t%s\t%d\n", JAT[k], k, JA[k] > jf
					close(jf)
				}
			}' "$tmp" > "$hf.new" 2>/dev/null
		if [ -s "$tmp.j" ] && [ "$jc" -gt 0 ]; then
			awk -F'\t' -v b="$AB_STATS_DIR/jb" -v a="$AB_STATS_DIR/ja" 'BEGIN { OFS = "\t" } { o = $1 == "B" ? b : a; print $2, $3, $4, $5 >> o }' "$tmp.j" 2>/dev/null
			_ab_jtrim "$AB_STATS_DIR/jb" "$jc"
			_ab_jtrim "$AB_STATS_DIR/ja" "$jc"
		fi
		rm -f "$tmp.j"
		if [ -s "$hf.new" ]; then
			{ grep -v '^D ' "$hf.new"; grep '^D ' "$hf.new" | sort -k3,3nr | head -n 500; } > "$hf.tmp" && mv -f "$hf.tmp" "$hf"
		fi
		rm -f "$hf.new" "$hf.tmp"
		if [ -s "$tmp.other" ]; then
			head -n 300 "$tmp.other" | sed 's/^[A-Z][a-z][a-z] [ 0-9]*[0-9] [0-9:]* //' | while IFS= read -r t; do
				case "$t" in *"]: "*) logger -t "${t%%\[*}" -- "${t#*]: }" ;; *) logger -t dnsmasq -- "$t" ;; esac
			done
			for t in $(_ab_lf_files); do head -n 300 "$tmp.other" >> "$t" 2>/dev/null; done
		fi
		rm -f "$tmp" "$tmp.other"
	fi
	_ab_stats_fold
	hour=$(( $(date +%s) / 3600 - 25 ))
	for hf in "$AB_STATS_DIR"/h.*; do
		[ -f "$hf" ] || continue
		t="${hf##*.}"
		case "$t" in ''|*[!0-9]*) rm -f "$hf"; continue ;; esac
		[ "$t" -lt "$hour" ] && rm -f "$hf"
	done
	if [ -s "$AB_STATS_DIR/folded" ]; then
		while read -r t; do [ -f "$AB_STATS_DIR/h.$t" ] && echo "$t"; done < "$AB_STATS_DIR/folded" > "$AB_STATS_DIR/folded.zm"
		mv -f "$AB_STATS_DIR/folded.zm" "$AB_STATS_DIR/folded"
	fi
	rmdir "$lk" 2>/dev/null
	return 0
}

_ab_stats_fold() {
	local cur f h todo=""
	cur=$(( $(date +%s) / 3600 ))
	for f in "$AB_STATS_DIR"/h.*; do
		[ -f "$f" ] || continue
		h="${f##*.}"; case "$h" in ''|*[!0-9]*) continue ;; esac
		[ "$h" = "$cur" ] && continue
		grep -qx "$h" "$AB_STATS_DIR/folded" 2>/dev/null && continue
		todo="$todo $h"
	done
	[ -n "$todo" ] || return 0
	mkdir -p "$(dirname "$AB_STATS_ALL")"
	_ab_devmap > "$AB_STATS_DIR/devmap.fold"
	( cd "$AB_STATS_DIR" && awk -v s0="$(( $(for h in $todo; do echo "$h"; done | sort -n | head -n1) * 3600 ))" -v mf="$AB_STATS_DIR/devmap.fold" "$AB_KEY_AWK"'
		BEGIN { abmap(mf) }
		$1 == "S" { S = $2 }
		$1 == "T" { T += $2 } $1 == "B" { B += $2 } $1 == "D" { D[$2] += $3 }
		$1 == "W" { WA[$2] = ($3 == "-" ? "" : $3); WN[$2] = ($4 == "-" ? "" : $4) }
		$1 == "C" || $1 == "X" {
			k = abkey($2)
			if ($1 == "C") C[k] += $3; else X[k] += $3
			if ($2 != "r" && $2 !~ /^[mn]:/ && (!(k in IP) || (IP[k] ~ /:/ && $2 ~ /\./))) IP[k] = $2
		}
		END {
			print "S " (S ? S : s0); print "T " T + 0; print "B " B + 0
			for (k in C) print "C " k " " C[k]
			for (k in X) print "X " k " " X[k]
			for (k in D) print "D " k " " D[k]
			for (k in C) {
				if (k !~ /^[mn]:/) continue
				m = k ~ /^m:/ ? substr(k, 3) : ""
				nm = m != "" ? N[m] : substr(k, 3); if (nm == "") nm = WN[k]
				ad = m != "" && (m in F4) ? F4[m] : (k in IP) ? IP[k] : WA[k]
				gsub(/[ \t]/, "_", nm)
				if (nm != "" || ad != "") print "W " k " " (ad == "" ? "-" : ad) " " (nm == "" ? "-" : nm)
			}
		}' $([ -s "$AB_STATS_ALL" ] && echo "$AB_STATS_ALL") $(for h in $todo; do echo "h.$h"; done) ) > "$AB_STATS_ALL.zm" 2>/dev/null || { rm -f "$AB_STATS_ALL.zm"; return 0; }
	{ grep -E '^(S|T|B) ' "$AB_STATS_ALL.zm"; grep '^C ' "$AB_STATS_ALL.zm" | sort -k3,3nr | head -n 256 > "$AB_STATS_ALL.c"; cat "$AB_STATS_ALL.c"
	  awk 'NR == FNR { k[$2] = 1; next } ($1 == "X" || $1 == "W") && ($2 in k)' "$AB_STATS_ALL.c" "$AB_STATS_ALL.zm"
	  grep '^D ' "$AB_STATS_ALL.zm" | sort -k3,3nr | head -n 1000; } > "$AB_STATS_ALL.new"
	rm -f "$AB_STATS_ALL.zm" "$AB_STATS_ALL.c" "$AB_STATS_DIR/devmap.fold"
	if [ -s "$AB_STATS_ALL.new" ]; then mv -f "$AB_STATS_ALL.new" "$AB_STATS_ALL"; else rm -f "$AB_STATS_ALL.new"; return 0; fi
	for h in $todo; do echo "$h"; done >> "$AB_STATS_DIR/folded"
}

_ab_stats_json() {
	local per="${1:-24}" from f h list="" since s1 via
	case "$per" in 1|24|all) ;; *) per=24 ;; esac
	since="$(_ab_get stats_since 0)"
	if [ "$per" = all ]; then
		[ -s "$AB_STATS_ALL" ] && list="$AB_STATS_ALL"
		s1="$(sed -n 's/^S \([0-9]*\)$/\1/p' "$AB_STATS_ALL" 2>/dev/null | head -n1)"
		for f in "$AB_STATS_DIR"/h.*; do
			[ -f "$f" ] || continue
			h="${f##*.}"; case "$h" in ''|*[!0-9]*) continue ;; esac
			grep -qx "$h" "$AB_STATS_DIR/folded" 2>/dev/null && continue
			list="$list $f"
			[ -n "$s1" ] || s1=$((h * 3600))
		done
		[ -n "$s1" ] && [ "$s1" -gt "${since:-0}" ] 2>/dev/null && since="$s1"
		from=0
	else
		from=$(( $(date +%s) / 3600 - per + 1 ))
		for f in "$AB_STATS_DIR"/h.*; do
			[ -f "$f" ] || continue
			h="${f##*.}"; case "$h" in ''|*[!0-9]*) continue ;; esac
			[ "$h" -ge "$from" ] && list="$list $f"
		done
	fi
	mkdir -p "$AB_STATS_DIR"
	_ab_devmap > "$AB_STATS_DIR/devmap.$$"
	via=""
	_ab_steer_dns && via="Steer"
	awk -v per="$([ "$per" = all ] && echo 0 || echo "$per")" -v since="${since:-0}" -v mf="$AB_STATS_DIR/devmap.$$" -v via="$via" -v jc="$(_ab_jcap)" "$AB_KEY_AWK"'
		function js(v) { gsub(/[\\"]/, "", v); gsub(/[\001-\037]/, "", v); return v }
		BEGIN { abmap(mf) }
		$1 == "T" { T += $2 } $1 == "B" { B += $2 } $1 == "D" { D[$2] += $3 }
		$1 == "W" { WA[$2] = ($3 == "-" ? "" : $3); WN[$2] = ($4 == "-" ? "" : $4) }
		$1 == "C" || $1 == "X" {
			k = abkey($2)
			if ($1 == "C") C[k] += $3; else X[k] += $3
			if ($2 != "r" && $2 !~ /^[mn]:/ && (!(k in IP) || (IP[k] ~ /:/ && $2 ~ /\./))) IP[k] = $2
		}
		END {
			rq = C["r"] + 0; relay = rq > 0 && rq * 2 >= T
			if (!relay) { T -= rq; B -= X["r"]; if (T < 0) T = 0; if (B < 0) B = 0; delete C["r"]; delete X["r"] }
			for (k in C) {
				m = k ~ /^m:/ ? substr(k, 3) : ""
				NAME[k] = m != "" ? N[m] : k ~ /^n:/ ? substr(k, 3) : ""
				if (NAME[k] == "" && (k in WN)) NAME[k] = WN[k]
				ADDR[k] = m != "" && (m in F4) ? F4[m] : (k in IP) ? IP[k] : k ~ /^[mn]:/ ? "" : k
				if (ADDR[k] == "" && (k in WA)) ADDR[k] = WA[k]
			}
			for (k in C) if (k ~ /^m:/ && NAME[k] != "") NM[NAME[k]] = k
			nn = 0; for (k in C) if (k ~ /^n:/ && (NAME[k] in NM)) L[++nn] = k
			for (i = 1; i <= nn; i++) { k = L[i]; t = NM[NAME[k]]; C[t] += C[k]; X[t] += X[k]; if (ADDR[t] == "") ADDR[t] = ADDR[k]; delete C[k] }
			if (relay) { NAME["r"] = ""; ADDR["r"] = "" }
			nc = 0; for (k in C) if (k != "r") nc++
			printf "{\"on\":true,\"period\":%d,\"since\":%d,\"total\":%d,\"blocked\":%d,\"clients\":%d,\"relay\":%s,\"via\":\"%s\",\"journal\":%d,\"top\":[", per, since, T, B, nc, relay ? "true" : "false", js(via), jc
			for (j = 0; j < 10; j++) { best = ""; bn = 0; for (k in D) if (D[k] > bn) { bn = D[k]; best = k } if (best == "") break; printf "%s{\"d\":\"%s\",\"n\":%d}", (j ? "," : ""), js(best), bn; delete D[best] }
			printf "],\"devs\":["
			for (j = 0; j < 6; j++) { best = ""; bn = 0; for (k in C) if (C[k] > bn) { bn = C[k]; best = k } if (best == "") break; printf "%s{\"k\":\"%s\",\"ip\":\"%s\",\"name\":\"%s\",\"q\":%d,\"b\":%d%s}", (j ? "," : ""), js(best), js(ADDR[best]), js(NAME[best]), bn, X[best] + 0, best == "r" ? ",\"relay\":true" : ""; delete C[best] }
			printf "]}\n"
		}' $list /dev/null
	rm -f "$AB_STATS_DIR/devmap.$$"
}

_ab_journal() {
	local mode="${1%% *}" arg="" flt=all q="" d="$AB_STATS_DIR" jc kb T
	case "$1" in *" "*) arg="${1#* }" ;; esac
	_ab_stats_on || { printf '{"on":false}\n'; return 0; }
	jc="$(_ab_jcap)"
	case "$mode" in
		log)
			flt="${arg%% *}"; case "$arg" in *" "*) q="${arg#* }" ;; esac
			case "$flt" in all|b|a) ;; *) flt=all ;; esac
			q="$(printf '%s' "$q" | tr -d '\\"\t\r\n' | tr 'A-Z' 'a-z' | cut -c1-64)" ;;
		dom)
			arg="$(printf '%s\n' "$arg" | _ab_allow_norm | head -n1)"
			[ -n "$arg" ] || { echo '{"error":"некорректный домен"}'; return 1; } ;;
		dev)
			case "$arg" in ''|*[!A-Za-z0-9:._-]*) echo '{"error":"некорректное устройство"}'; return 1 ;; esac ;;
		*) echo '{"error":"неизвестный режим журнала"}'; return 1 ;;
	esac
	adblock_stats_tick
	mkdir -p "$d"
	for T in jb ja; do [ -f "$d/$T" ] || : > "$d/$T"; done
	kb=$(( ($(cat "$d/jb" "$d/ja" 2>/dev/null | wc -c) + 1023) / 1024 ))
	_ab_devmap > "$d/devmap.j$$"
	T="$(printf '\t')"
	awk -F'\t' -v OFS='\t' '{ print $1, (FILENAME ~ /jb$/ ? "b" : "a"), $2, $3, $4 }' "$d/jb" "$d/ja" 2>/dev/null | sort -nr |
	awk -F'\t' -v mode="$mode" -v arg="$arg" -v flt="$flt" -v q="$q" -v mf="$d/devmap.j$$" -v jc="$jc" -v kb="$kb" -v now="$(date +%s)" "$AB_KEY_AWK"'
		function js(v) { gsub(/[\\"]/, "", v); gsub(/[\001-\037]/, "", v); return v }
		function dkey(ip,   k) {
			if (ip in DK) return DK[ip]
			k = abkey(ip)
			if (k ~ /^n:/ && (substr(k, 3) in NM)) k = NM[substr(k, 3)]
			DK[ip] = k; return k
		}
		function dname(k,   m) {
			if (k == "r") return "Роутер"
			if (k == "s") return "Через Steer"
			m = k ~ /^m:/ ? substr(k, 3) : ""
			if (m != "") return N[m]
			if (k ~ /^n:/) return substr(k, 3)
			return ""
		}
		function daddr(k, ip,   m) { if (k == "s") return ""; m = k ~ /^m:/ ? substr(k, 3) : ""; if (m != "" && (m in F4)) return F4[m]; return ip }
		function pick(arr, cnt, lim,   i, j, best, bn, out, n) {
			n = 0
			for (j = 0; j < lim; j++) {
				best = ""; bn = 0
				for (i in arr) if (cnt[i] > bn) { bn = cnt[i]; best = i }
				if (best == "") break
				ORD[++n] = best; delete arr[best]
			}
			return n
		}
		BEGIN { abmap(mf); for (ip in M) if (N[M[ip]] != "") NM[N[M[ip]]] = "m:" M[ip] }
		{
			ts = $1 + 0; kind = $2; ip = $3; dm = $4; c = $5 + 0
			if (ip == "" || dm == "") next
			if (!oldest || ts < oldest) oldest = ts
			if (kind == "b") nb++; else na++
			k = dkey(ip)
			if (mode == "log") {
				if (flt != "all" && kind != flt) next
				if (q != "" && index(dm, q) == 0 && index(tolower(dname(k)), q) == 0 && index(ip, q) == 0) next
				if (nr >= 300) { more = 1; next }
				R[++nr] = sprintf("{\"t\":%d,\"b\":%d,\"k\":\"%s\",\"ip\":\"%s\",\"n\":\"%s\",\"d\":\"%s\",\"c\":%d}", ts, kind == "b", js(k), js(daddr(k, ip)), js(dname(k)), js(dm), c)
			} else if (mode == "dom") {
				if (dm != arg) next
				if (!(k in DT)) { DT[k] = ts; DI[k] = ip; DL[k] = 1 }
				if (kind == "b") DB[k] += c; else DA[k] += c
				DS[k] += c; if (kind == "b") tb += c; else ta += c
			} else {
				if (k != arg && ip != arg) next
				if (wip == "") wip = daddr(k, ip)
				x = kind "\t" dm
				if (!(x in XT)) { XT[x] = ts; XL[x] = 1 }
				XC[x] += c; if (kind == "b") tb += c; else ta += c
			}
		}
		END {
			printf "{\"on\":true,\"mode\":\"%s\",\"journal\":%d,\"kb\":%d,\"now\":%d,\"oldest\":%d,\"nb\":%d,\"na\":%d", mode, jc, kb, now, oldest, nb, na
			if (mode == "log") {
				printf ",\"more\":%s,\"rows\":[", more ? "true" : "false"
				for (i = 1; i <= nr; i++) printf "%s%s", (i > 1 ? "," : ""), R[i]
				printf "]}\n"
			} else if (mode == "dom") {
				printf ",\"d\":\"%s\",\"tb\":%d,\"ta\":%d,\"devs\":[", js(arg), tb, ta
				n = pick(DL, DS, 100)
				for (i = 1; i <= n; i++) { k = ORD[i]; printf "%s{\"k\":\"%s\",\"ip\":\"%s\",\"n\":\"%s\",\"b\":%d,\"a\":%d,\"t\":%d}", (i > 1 ? "," : ""), js(k), js(daddr(k, DI[k])), js(dname(k)), DB[k], DA[k], DT[k] }
				printf "]}\n"
			} else {
				printf ",\"k\":\"%s\",\"n\":\"%s\",\"ip\":\"%s\",\"tb\":%d,\"ta\":%d", js(arg), js(dname(arg)), js(wip == "" && arg !~ /^[mnrs]/ ? arg : wip), tb, ta
				for (x in XL) { split(x, p, "\t"); if (p[1] == "b") { BLx[x] = 1; BC[x] = XC[x] } else { ALx[x] = 1; AC[x] = XC[x] } }
				printf ",\"blocked\":["
				n = pick(BLx, BC, 150)
				for (i = 1; i <= n; i++) { x = ORD[i]; split(x, p, "\t"); printf "%s{\"d\":\"%s\",\"c\":%d,\"t\":%d}", (i > 1 ? "," : ""), js(p[2]), XC[x], XT[x] }
				printf "],\"allowed\":["
				n = pick(ALx, AC, 150)
				for (i = 1; i <= n; i++) { x = ORD[i]; split(x, p, "\t"); printf "%s{\"d\":\"%s\",\"c\":%d,\"t\":%d}", (i > 1 ? "," : ""), js(p[2]), XC[x], XT[x] }
				printf "]}\n"
			}
		}'
	rm -f "$d/devmap.j$$"
}

_ab_leftover() {
	local d
	for d in $(_ab_alldirs); do [ -e "$d/$AB_NAME" ] || [ -e "$d/$AB_STATS_CONF" ] && return 0; done
	return 1
}

_ab_free_macs() { [ -s "$AB_FREE" ] && sed -n 's/^\([0-9A-Fa-f:]\{17\}\).*/\1/p' "$AB_FREE" | tr 'A-F' 'a-f' | sort -u; }

_ab_free_alive() { local p; p="$(cat "$AB_FREE_PID" 2>/dev/null)"; [ -n "$p" ] && kill -0 "$p" 2>/dev/null; }

_ab_free_conf() {
	local f
	f="$(grep -l '^conf-dir=' /var/etc/dnsmasq.conf.* 2>/dev/null | head -n1)"
	[ -n "$f" ] || f="$(ls /var/etc/dnsmasq.conf.* 2>/dev/null | head -n1)"
	[ -s "$f" ] || return 1
	echo "# Zapret Manager: DNS без блокировки рекламы для выбранных устройств (копия пересылки основного dnsmasq)"
	echo "port=$AB_FREE_PORT"
	echo "bind-dynamic"
	echo "pid-file=$AB_FREE_PID"
	grep -E '^(server=|no-resolv$|resolv-file=|strict-order$|all-servers$|cache-size=|domain-needed$|bogus-priv$|stop-dns-rebind$|rebind-localhost-ok$|rebind-domain-ok=)' "$f"
	grep -qE '^(no-resolv$|resolv-file=)' "$f" || { [ -s /tmp/resolv.conf.d/resolv.conf.auto ] && echo "resolv-file=/tmp/resolv.conf.d/resolv.conf.auto"; }
	grep -q '^cache-size=' "$f" || echo "cache-size=1000"
	sed -n 's#^local=/\([^/]*\)/$#server=/\1/127.0.0.1#p' "$f"
}

_ab_free_nft() {
	local els
	els="$(printf '%s\n' "$1" | grep . | tr '\n' ',' | sed 's/,$//')"
	[ -n "$els" ] || return 1
	nft -f - << ZM_AB_NFT_EOF
table inet $AB_FREE_NFT
delete table inet $AB_FREE_NFT
table inet $AB_FREE_NFT {
	set macs { type ether_addr; elements = { $els } }
	chain pre {
		type nat hook prerouting priority dstnat - 10; policy accept;
		ether saddr @macs meta l4proto { tcp, udp } th dport 53 redirect to :$AB_FREE_PORT
	}
}
ZM_AB_NFT_EOF
}

_ab_free_stop() {
	local p
	nft delete table inet "$AB_FREE_NFT" >/dev/null 2>&1
	p="$(cat "$AB_FREE_PID" 2>/dev/null)"
	[ -n "$p" ] && kill "$p" 2>/dev/null
	_kill_match "-C $AB_FREE_CONF"
	rm -f "$AB_FREE_PID" "$AB_FREE_CONF" "$AB_FREE_CONF.zm-new" "$AB_FREE_CONF.macs"
	return 0
}

_ab_free_sync() {
	local macs new="$AB_FREE_CONF.zm-new" t=0
	macs="$(_ab_free_macs)"
	if ! _ab_on || [ -z "$macs" ]; then _ab_free_stop; return 0; fi
	mkdir -p "${AB_FREE_CONF%/*}"
	_ab_free_conf > "$new" 2>/dev/null || { rm -f "$new"; _ab_free_stop; return 1; }
	if _ab_free_alive && cmp -s "$new" "$AB_FREE_CONF"; then
		rm -f "$new"; touch "$AB_FREE_CONF"
	else
		_ab_free_alive && kill "$(cat "$AB_FREE_PID" 2>/dev/null)" 2>/dev/null
		while _ab_free_alive && [ "$t" -lt 5 ]; do sleep 1; t=$((t + 1)); done
		mv -f "$new" "$AB_FREE_CONF"
		rm -f "$AB_FREE_PID"
		dnsmasq -C "$AB_FREE_CONF" >/dev/null 2>&1
		t=0
		while ! _ab_free_alive && [ "$t" -lt 5 ]; do sleep 1; t=$((t + 1)); done
		if ! _ab_free_alive; then
			nft delete table inet "$AB_FREE_NFT" >/dev/null 2>&1
			rm -f "$AB_FREE_CONF.macs"
			logger -t zapret-manager "Блокировка рекламы: DNS для устройств без блокировки не запустился — они пока получают обычный DNS"
			return 1
		fi
	fi
	if ! nft list table inet "$AB_FREE_NFT" >/dev/null 2>&1 || [ "$(cat "$AB_FREE_CONF.macs" 2>/dev/null)" != "$macs" ]; then
		_ab_free_nft "$macs" || return 1
		printf '%s\n' "$macs" > "$AB_FREE_CONF.macs"
	fi
	return 0
}

_ab_free_json() {
	local run=false
	_ab_free_alive && nft list table inet "$AB_FREE_NFT" >/dev/null 2>&1 && run=true
	printf '{"running":%s,"free":[' "$run"
	[ -s "$AB_FREE" ] && awk -F'|' -v nf="$OW_NAMES" 'BEGIN { s = ""; while ((getline l < nf) > 0) { split(l, a, "\t"); if (a[2] != "") lb[tolower(a[1])] = a[2] } } $1 ~ /^[0-9a-fA-F:]{17}$/ { m = tolower($1); n = (m in lb) ? lb[m] : $2; gsub(/["\\]/, " ", n); printf "%s{\"mac\":\"%s\",\"name\":\"%s\"}", s, m, n; s = "," }' "$AB_FREE"
	printf '],"devices":['
	[ -s /tmp/dhcp.leases ] && awk -v nf="$OW_NAMES" 'BEGIN { s = ""; while ((getline l < nf) > 0) { split(l, a, "\t"); if (a[2] != "") lb[tolower(a[1])] = a[2] } } $2 ~ /^[0-9a-fA-F:]{17}$/ { m = tolower($2); n = $4; if (n == "*") n = ""; if (m in lb) n = lb[m]; gsub(/["\\]/, " ", n); printf "%s{\"mac\":\"%s\",\"ip\":\"%s\",\"name\":\"%s\"}", s, m, $3, n; s = "," }' /tmp/dhcp.leases
	printf ']}\n'
}

_ab_ip_clean() {
	awk -F'[./]' '
		function ip(a, b, c, d) { return ((a * 256 + b) * 256 + c) * 256 + d }
		function blk(n, l) { return int(n / 2 ^ (32 - l)) }
		BEGIN {
			nr = split("0.0.0.0/8 10.0.0.0/8 100.64.0.0/10 127.0.0.0/8 169.254.0.0/16 172.16.0.0/12 192.0.0.0/24 192.0.2.0/24 192.168.0.0/16 198.18.0.0/15 198.51.100.0/24 203.0.113.0/24 224.0.0.0/4 240.0.0.0/4", R, " ")
			for (i = 1; i <= nr; i++) { split(R[i], q, "[./]"); RN[i] = ip(q[1], q[2], q[3], q[4]); RL[i] = q[5] }
		}
		{ sub(/\r$/, ""); sub(/[ \t].*$/, "") }
		{
			if ($0 !~ /^[0-9][0-9.]*[0-9](\/[0-9]+)?$/) next
			z = $0; if (gsub(/\./, ".", z) != 3 || gsub(/\//, "/", z) > 1) next
			for (i = 1; i <= 4; i++) if ($i == "" || length($i) > 3 || $i + 0 > 255) next
			if (NF == 5 && ($5 == "" || length($5) > 2)) next
			l = (NF >= 5 ? $5 + 0 : 32); if (l < 8 || l > 32) next
			n = ip($1, $2, $3, $4); n = blk(n, l) * 2 ^ (32 - l)
			for (i = 1; i <= nr; i++) { m = (l < RL[i] ? l : RL[i]); if (blk(n, m) == blk(RN[i], m)) next }
			k = n "/" l; if (k in S) next; S[k] = 1
			printf "%d.%d.%d.%d/%d\n", int(n / 16777216), int(n / 65536) % 256, int(n / 256) % 256, n % 256, l
		}'
}

_ab_ip_dl() {
	local id="$1" tmp="$JOBS_DIR/adblock.ip.$1.dl" out="$AB_IP_DIR/$1.txt" url n min
	min="$(_ab_min "$id")"
	mkdir -p "$AB_IP_DIR"
	for url in "$ST_TCH_RAW/release/subnets/ipv4/$id.lst" "$ST_TCH_CDN/release/subnets/ipv4/$id.lst"; do
		echo "   → Скачиваем $(_ab_title "$id") ($(printf '%s' "$url" | sed 's#^https://\([^/]*\).*#\1#'))"
		rm -f "$tmp"
		if _zm_fetch "$url" "$tmp" 240; then
			_ab_ip_clean < "$tmp" > "$out.zm-new"
			n="$(wc -l < "$out.zm-new" | tr -d ' ')"
			if [ "${n:-0}" -ge "$min" ]; then
				mv -f "$out.zm-new" "$out"; rm -f "$tmp"
				_ab_put "n_ip_$id" "$n" "t_ip_$id" "$(date +%s)"
				echo "   ✓ $(_ab_title "$id"): $(_ab_num "$n") адресов и сетей"
				return 0
			fi
			echo "   ! Получен неполный файл ($(_ab_num "${n:-0}") записей) — пробуем другой адрес"
		else
			echo "   ! Не скачалось: $ZM_FETCH_ERR"
		fi
	done
	rm -f "$tmp" "$out.zm-new"
	return 1
}

_ab_ip_keep() {
	{ ip -4 route show default 2>/dev/null | awk '{ for (i = 1; i < NF; i++) if ($i == "via") print $(i + 1) }'
	  cat /tmp/resolv.conf.d/resolv.conf.auto /tmp/resolv.conf.auto 2>/dev/null | awk '$1 == "nameserver" { print $2 }'
	  uci -q get network.wan.dns 2>/dev/null | tr ' ' '\n'; } | grep -E '^[0-9]{1,3}(\.[0-9]{1,3}){3}$' | awk '!s[$0]++'
}

_ab_ip_stop() {
	nft delete table inet "$AB_IP_NFT" >/dev/null 2>&1
	rm -f "$JOBS_DIR/adblock.ip.sig"
	return 0
}

_ab_ip_load() {
	local f="$JOBS_DIR/adblock.ip.nft" id src="" keep av
	for id in $1; do [ -s "$AB_IP_DIR/$id.txt" ] && src="$src $AB_IP_DIR/$id.txt"; done
	[ -n "$src" ] || { _ab_ip_stop; return 1; }
	av="$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null)"
	if [ -n "$av" ] && [ "$av" -lt 24576 ]; then echo "   ! Свободной памяти $((av / 1024)) МБ — опасные IP в файрвол не загружаем"; return 1; fi
	keep="$(_ab_ip_keep | tr '\n' ',' | sed 's/,$//')"
	mkdir -p "$JOBS_DIR"
	{
		echo "table inet $AB_IP_NFT"
		echo "delete table inet $AB_IP_NFT"
		echo "table inet $AB_IP_NFT {"
		echo "	set bad4 { type ipv4_addr; flags interval; auto-merge; }"
		echo "	set keep4 { type ipv4_addr; flags interval; auto-merge;${keep:+ elements = { $keep }} }"
		echo "	chain forward_bad { type filter hook forward priority filter - 5; policy accept; ip daddr @keep4 return; ip saddr @keep4 return; ip daddr @bad4 counter drop; ip saddr @bad4 counter drop; }"
		echo "	chain input_bad { type filter hook input priority filter - 5; policy accept; ip saddr @keep4 return; ip saddr @bad4 counter drop; }"
		echo "	chain output_bad { type filter hook output priority filter - 5; policy accept; ip daddr @keep4 return; ip daddr @bad4 counter drop; }"
		echo "}"
		cat $src | awk '!s[$0]++' | awk -v t="$AB_IP_NFT" '{ b = b (n++ ? ", " : "") $0 } n == 2000 { print "add element inet " t " bad4 { " b " }"; b = ""; n = 0 } END { if (n) print "add element inet " t " bad4 { " b " }" }'
	} > "$f"
	if nft -f "$f" >/dev/null 2>"$f.err"; then
		rm -f "$f" "$f.err"
		echo "$1 $(cat $src | wc -l | tr -d ' ')" > "$JOBS_DIR/adblock.ip.sig"
		return 0
	fi
	echo "   ! nft не принял список: $(head -n 2 "$f.err" | tr '\n' ' ')"
	rm -f "$f" "$f.err"
	nft delete table inet "$AB_IP_NFT" >/dev/null 2>&1
	return 1
}

_ab_ip_sync() {
	local ids sig n=0 id
	ids="$(_ab_tch_ip | tr '\n' ' ' | sed 's/ $//')"
	if ! _ab_on || [ -z "$ids" ]; then nft list table inet "$AB_IP_NFT" >/dev/null 2>&1 && _ab_ip_stop; return 0; fi
	for id in $ids; do [ -s "$AB_IP_DIR/$id.txt" ] && n=$((n + $(wc -l < "$AB_IP_DIR/$id.txt"))); done
	sig="$ids $n"
	[ "$1" != force ] && [ "$(cat "$JOBS_DIR/adblock.ip.sig" 2>/dev/null)" = "$sig" ] && nft list table inet "$AB_IP_NFT" >/dev/null 2>&1 && return 0
	_ab_ip_load "$ids"
}

_ab_ip_tbl() { nft -a list table inet "$AB_IP_NFT" 2>/dev/null | sed -n '1s/.*# handle \([0-9]*\).*/\1/p'; }
_ab_ip_hits() { for c in forward_bad input_bad output_bad; do nft list chain inet "$AB_IP_NFT" "$c" 2>/dev/null; done | awk '/drop/ { for (i = 1; i < NF; i++) if ($i == "packets") s += $(i + 1) } END { print s + 0 }'; }

_ab_ip_json() {
	local live=false n=0 hits=0 h0
	if nft list table inet "$AB_IP_NFT" >/dev/null 2>&1; then
		live=true
		n="$(awk '{ print $NF + 0 }' "$JOBS_DIR/adblock.ip.sig" 2>/dev/null)"
		hits="$(_ab_ip_hits)"
		h0="$(cat "$JOBS_DIR/adblock.ip.hits0" 2>/dev/null)"
		case "$h0" in
			*" "*) if [ "${h0%% *}" = "$(_ab_ip_tbl)" ] && [ "${hits:-0}" -ge "${h0#* }" ] 2>/dev/null; then hits=$((hits - ${h0#* })); else rm -f "$JOBS_DIR/adblock.ip.hits0"; fi ;;
		esac
	fi
	printf '{"live":%s,"n":%s,"hits":%s}' "$live" "${n:-0}" "${hits:-0}"
}

_ab_cron_sync() {
	local m line
	if _ab_on && [ "$(_ab_get auto 1)" = 1 ]; then
		m="$(_ab_get minute "")"
		case "$m" in ''|*[!0-9]*) m="$(awk 'BEGIN { srand(); print int(rand() * 60) }')"; _ab_put minute "$m" ;; esac
		line="$m 4 * * * /opt/zapret-manager-luci/backend.sh adblock_cron >/dev/null 2>&1 $AB_CRON_TAG"
		grep -qxF "$line" "$CRON_FILE" 2>/dev/null && return 0
		mkdir -p "$(dirname "$CRON_FILE")"; touch "$CRON_FILE"
		grep -vF "$AB_CRON_TAG" "$CRON_FILE" > "$CRON_FILE.zm" 2>/dev/null; cat "$CRON_FILE.zm" > "$CRON_FILE"; rm -f "$CRON_FILE.zm"
		echo "$line" >> "$CRON_FILE"
		/etc/init.d/cron restart >/dev/null 2>&1
	else
		grep -qF "$AB_CRON_TAG" "$CRON_FILE" 2>/dev/null || return 0
		grep -vF "$AB_CRON_TAG" "$CRON_FILE" > "$CRON_FILE.zm" 2>/dev/null; cat "$CRON_FILE.zm" > "$CRON_FILE"; rm -f "$CRON_FILE.zm"
		/etc/init.d/cron restart >/dev/null 2>&1
	fi
	return 0
}

_ab_rebuild() {
	local tmp="$JOBS_DIR/adblock.conf.new" n
	mkdir -p "$JOBS_DIR"
	n="$(_ab_build "$tmp" 2>&1)" || { rm -f "$tmp" "$tmp.note"; echo "${n:-не удалось собрать список}"; return 1; }
	rm -f "$tmp.note"
	if ! _ab_install "$tmp" >/dev/null 2>&1; then rm -f "$tmp"; echo "dnsmasq не запустился с этим списком"; return 1; fi
	rm -f "$tmp"
	_ab_free_sync >/dev/null 2>&1
	_ab_put count "$n" err ""
	echo "$n"
}

_ab_ip_apply() {
	local ids id f age now n=0
	ids="$(_ab_tch_ip | tr '\n' ' ')"
	for f in "$AB_IP_DIR"/*.txt; do
		[ -f "$f" ] || continue
		id="${f##*/}"; id="${id%.txt}"
		case " $ids " in *" $id "*) ;; *) rm -f "$f" ;; esac
	done
	if [ -z "$(echo $ids)" ]; then _ab_ip_stop; return 0; fi
	_ab_say "Опасные IP (Tachyon Lists)"
	now="$(date +%s)"
	for id in $ids; do
		age=$(( now - $(_ab_get "t_ip_$id" 0) ))
		if [ "$1" != force ] && [ -s "$AB_IP_DIR/$id.txt" ] && [ "$age" -ge 0 ] && [ "$age" -lt 43200 ]; then
			echo "   ✓ $(_ab_title "$id"): свежий, скачан $((age / 60)) мин назад"
		elif ! _ab_ip_dl "$id"; then
			if [ -s "$AB_IP_DIR/$id.txt" ]; then echo "   ! $(_ab_title "$id"): обновить не удалось — оставляем прежнюю копию"
			else echo "   ! $(_ab_title "$id"): не скачался — пока без него"; fi
		fi
	done
	if _ab_ip_sync force; then
		n="$(awk '{ print $NF + 0 }' "$JOBS_DIR/adblock.ip.sig" 2>/dev/null)"
		echo "   ✓ В файрволе $(_ab_num "${n:-0}") опасных адресов и сетей — соединения с ними отбрасываются"
	else
		echo "!! Опасные IP в файрвол не загрузились — блокировка рекламы работает и без них"
	fi
	return 0
}

do_ab_apply() {
	local mode="$1" ids id f tmp="$JOBS_DIR/adblock.conf.new" n avail age now fails=0 got=0 keep
	ids="$(_ab_ids)"
	_ab_say "Блокировка рекламы: $(_ab_title "$(_ab_get list pro)")$([ "$(_ab_get tif 0)" = 1 ] && echo ' + защита от фишинга')$([ "$(_ab_get doh 0)" = 1 ] && echo ' + запрет чужих DoH')$([ -n "$(_ab_tch)" ] && echo " + Tachyon Lists: $(_ab_tch | wc -l | tr -d ' ')")"
	avail="$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null)"
	if [ -n "$avail" ] && [ "$avail" -lt 60000 ]; then
		echo "!! Свободной памяти $((avail / 1024)) МБ, продолжаем на свой риск"
	fi
	_ab_say "Скачиваем списки"
	_ab_tg_fetch >/dev/null 2>&1
	now="$(date +%s)"
	for id in $ids; do
		age=$(( now - $(_ab_get "t_$id" 0) ))
		if [ "$mode" != force ] && _ab_src "$id" >/dev/null && [ "$age" -ge 0 ] && [ "$age" -lt 43200 ]; then
			echo "   ✓ $(_ab_title "$id"): свежий, скачан $((age / 60)) мин назад"
			continue
		fi
		if _ab_dl "$id"; then got=1
		elif _ab_src "$id" >/dev/null; then echo "   ! $(_ab_title "$id"): обновить не удалось — оставляем прежнюю копию"; fails=1
		elif [ "${id#t_}" != "$id" ]; then echo "   ! $(_ab_title "$id"): не скачался — собираем без него, попробуем при следующем обновлении"; fails=1
		else
			echo "ОШИБКА: $(_ab_title "$id") не скачался ни с GitHub, ни с jsDelivr — проверьте интернет на роутере"
			_ab_put err "список не скачался" errat "$(date +%s)"
			return 1
		fi
	done
	for f in "$AB_DIR"/src/*; do
		[ -f "$f" ] || continue
		keep=0; id="$(basename "$f")"; id="${id%.*}"
		for n in $ids; do [ "$n" = "$id" ] && keep=1; done
		[ "$keep" = 1 ] || rm -f "$f"
	done
	_ab_say "Собираем список для dnsmasq"
	n="$(_ab_build "$tmp" 2>"$tmp.err")" || {
		[ -s "$tmp.note" ] && cat "$tmp.note"
		echo "ОШИБКА: $(head -n1 "$tmp.err" 2>/dev/null | grep . || echo "не удалось собрать список")"
		rm -f "$tmp" "$tmp.err" "$tmp.note"
		_ab_put err "не удалось собрать список" errat "$(date +%s)"
		return 1
	}
	[ -s "$tmp.note" ] && cat "$tmp.note"
	rm -f "$tmp.err" "$tmp.note"
	echo "   ✓ К блокировке: $(_ab_dom "$n") (белый список учтён)"
	_ab_say "Подключаем к dnsmasq"
	if ! _ab_install "$tmp"; then
		rm -f "$tmp"
		_ab_put err "dnsmasq не запустился со списком" errat "$(date +%s)"
		return 1
	fi
	rm -f "$tmp"
	echo "   ✓ dnsmasq перезапущен и отвечает (занимает $(( $(_ab_dns_rss) / 1024 )) МБ памяти)"
	if [ -n "$(_ab_free_macs)" ]; then
		if _ab_free_sync; then echo "   ✓ Устройства без блокировки ($(_ab_free_macs | wc -l | tr -d ' ')) получают DNS без списка"
		else echo "   ! DNS без блокировки для выбранных устройств не запустился — они пока получают общий"; fi
	fi
	_ab_ip_apply "$mode"
	_ab_put count "$n" updated "$(date +%s)" err ""
	_ab_cron_sync
	_zm_inet_ok || echo "!! Сайты сейчас не открываются с роутера — проверьте интернет; список тут ни при чём, его можно выключить кнопкой «Выключить»"
	[ "$fails" = 1 ] && echo "!! Часть списков осталась прежней версии — попробуйте «Обновить сейчас» позже"
	_ab_say "Готово: реклама блокируется для всех устройств в сети"
}

adblock_status() {
	local on=false applied=false auto=false tif=false doh=false job=false ram avail have="" sep="" id err errat
	_ab_on && on=true
	_ab_applied && applied=true
	[ "$(_ab_get auto 1)" = 1 ] && auto=true
	[ "$(_ab_get tif 0)" = 1 ] && tif=true
	[ "$(_ab_get doh 0)" = 1 ] && doh=true
	_job_alive adblock && job=true
	ram="$(awk '/^MemTotal:/ { print $2 }' /proc/meminfo 2>/dev/null)"
	avail="$(awk '/^MemAvailable:/ { print $2 }' /proc/meminfo 2>/dev/null)"
	for id in light multi pro proplus ultimate tif doh $(for x in $AB_TCH_DOM; do echo "t_$x"; done); do
		_ab_src "$id" >/dev/null || continue
		have="$have$sep\"$id\":{\"n\":$(_ab_get "n_$id" 0),\"v\":\"$(esc "$(_ab_get "v_$id" "")")\",\"t\":$(_ab_get "t_$id" 0)}"; sep=","
	done
	for id in $AB_TCH_IP; do
		[ -s "$AB_IP_DIR/$id.txt" ] || continue
		have="$have$sep\"$id\":{\"n\":$(_ab_get "n_ip_$id" 0),\"v\":\"\",\"t\":$(_ab_get "t_ip_$id" 0)}"; sep=","
	done
	err="$(_ab_get err "")"; errat="$(_ab_get errat 0)"
	printf '{"tch":"%s","ip":%s,"on":%s,"applied":%s,"list":"%s","tif":%s,"doh":%s,"auto":%s,"minute":"%s","count":%s,"updated":%s,"now":%s,"err":"%s","errat":%s,"job":%s,"dns_kb":%s,"ram_kb":%s,"avail_kb":%s,"doh_proxy":%s,"stats":%s,"src":{%s},"allow":"%s","allow_default":"%s","block":"%s"}\n' \
		"$(_ab_tch | tr '\n' ',' | sed 's/,$//')" "$(_ab_ip_json)" \
		"$on" "$applied" "$(esc "$(_ab_get list pro)")" "$tif" "$doh" "$auto" "$(esc "$(_ab_get minute "")")" \
		"$(_ab_get count 0)" "$(_ab_get updated 0)" "$(date +%s)" "$(esc "$err")" "${errat:-0}" "$job" \
		"$(_ab_dns_rss)" "${ram:-0}" "${avail:-0}" "$(pidof https-dns-proxy >/dev/null 2>&1 && echo true || echo false)" "$(_ab_stats_on && echo true || echo false)" \
		"$have" "$(esc_ml "$(_ab_allow_text)")" "$(esc_ml "$AB_ALLOW_DEFAULT")" "$(esc_ml "$(_ab_block_text)")"
}

_ab_check() {
	local q id hit allow
	q="$(printf '%s\n' "$1" | _ab_allow_norm | head -n1)"
	[ -n "$q" ] || { echo '{"error":"введите домен, например doubleclick.net"}'; return 1; }
	if ! _ab_on; then printf '{"domain":"%s","state":"off"}\n' "$(esc "$q")"; return 0; fi
	hit="$(_ab_block_text | _ab_allow_norm | awk -v q="$q" '{ B[$0] = 1 } END { x = q; while (1) { if (x in B) { print x; exit } i = index(x, "."); if (!i) break; x = substr(x, i + 1) } }')"
	if [ -n "$hit" ]; then printf '{"domain":"%s","state":"blocked","mine":true,"source":"чёрный список","by":"%s"}\n' "$(esc "$q")" "$(esc "$hit")"; return 0; fi
	allow="$( { _ab_allow_text | _ab_allow_norm; _ab_own_hosts | _ab_allow_norm; } | awk -v q="$q" '
		{ A[$0] = 1 } END { x = q; while (1) { if (x in A) { print x; exit } i = index(x, "."); if (!i) break; x = substr(x, i + 1) } }')"
	for id in $(_ab_ids); do
		hit="$(_ab_cat "$id" 2>/dev/null | awk -v q="$q" '
			BEGIN { x = q; while (1) { C[x] = 1; i = index(x, "."); if (!i) break; x = substr(x, i + 1) } }
			($0 in C) { print; exit }')"
		[ -n "$hit" ] && break
	done
	if [ -n "$hit" ] && [ -n "$allow" ]; then
		printf '{"domain":"%s","state":"allowed","source":"%s","by":"%s","allow":"%s"}\n' "$(esc "$q")" "$(esc "$(_ab_title "$id")")" "$(esc "$hit")" "$(esc "$allow")"
	elif [ -n "$hit" ]; then
		printf '{"domain":"%s","state":"blocked","source":"%s","by":"%s"}\n' "$(esc "$q")" "$(esc "$(_ab_title "$id")")" "$(esc "$hit")"
	else
		printf '{"domain":"%s","state":"clean"}\n' "$(esc "$q")"
	fi
}

adblock_action() {
	local a="$1" m="$2" j k v kv list tif doh auto n tch x
	case "$a" in
		apply|update)
			_job_alive adblock && { echo '{"error":"список уже обновляется — дождитесь окончания"}'; return 1; }
			if j="$(_zm_busy_job)"; then printf '{"error":"%s"}\n' "$(esc "Сейчас идёт операция: $j — дождитесь её окончания")"; return 1; fi
			if [ "$a" = apply ]; then
				list="$(_ab_get list pro)"; tif="$(_ab_get tif 0)"; doh="$(_ab_get doh 0)"; auto="$(_ab_get auto 1)"; tch="$(_ab_get tch "")"
				for kv in $m; do
					k="${kv%%=*}"; v="${kv#*=}"
					case "$k" in
						list) _ab_file "$v" >/dev/null && case "$v" in tif|doh|t_*) ;; *) list="$v" ;; esac ;;
						tch) tch=""; for x in $AB_TCH_DOM $AB_TCH_IP; do case ",$v," in *",$x,"*) tch="$tch${tch:+,}$x" ;; esac; done ;;
						tif) [ "$v" = 1 ] && tif=1 || tif=0 ;;
						doh) [ "$v" = 1 ] && doh=1 || doh=0 ;;
						auto) [ "$v" = 1 ] && auto=1 || auto=0 ;;
					esac
				done
				_ab_put on 1 list "$list" tif "$tif" doh "$doh" auto "$auto" tch "$tch"
				job_start adblock do_ab_apply
			else
				_ab_on || { echo '{"error":"блокировка выключена"}'; return 1; }
				job_start adblock do_ab_apply force
			fi ;;
		off)
			_job_alive adblock && { echo '{"error":"дождитесь окончания операции"}'; return 1; }
			_ab_put on 0 err "" stats 0
			_ab_free_stop
			_ab_ip_stop
			_ab_unplug
			_ab_stats_unplug
			_ab_stats_cron off
			_ab_stats_wipe
			rm -rf "$AB_DIR/src" "$AB_IP_DIR"
			rm -f "$AB_TG_LIST" "$AB_DNS_STAMP" "$JOBS_DIR"/adblock.watch "$JOBS_DIR"/adblock.old "$JOBS_DIR"/adblock.allow "$JOBS_DIR"/adblock.conf.new* \
				"$JOBS_DIR"/adblock.*.dl "$JOBS_DIR"/adblock.*.dl.dec "$JOBS_DIR"/adblock.*.dom "$JOBS_DIR"/ab.exempt.*
			[ -f "$AB_SET" ] && sed -i -e '/^[nvt]_[a-z_]*=/d' -e '/^count=/d' -e '/^updated=/d' -e '/^errat=/d' "$AB_SET"
			_ab_cron_sync
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			sleep 2
			if _ab_leftover; then _ab_unplug; /etc/init.d/dnsmasq restart >/dev/null 2>&1; fi
			printf '{"ok":true}\n' ;;
		free_get) _ab_free_json ;;
		stats)
			if ! _ab_stats_on; then printf '{"on":false}\n'; return 0; fi
			adblock_stats_tick
			_ab_stats_json "$m" ;;
		journal) _ab_journal "$m" ;;
		stats_reset)
			_ab_stats_on || { echo '{"error":"статистика выключена — сбрасывать нечего"}'; return 1; }
			_ab_stats_reset || { echo '{"error":"статистика сейчас считается — попробуйте через пару секунд"}'; return 1; }
			_ab_stats_json "$m" ;;
		journal_set)
			_ab_stats_on || { echo '{"error":"сначала включите статистику"}'; return 1; }
			case "$m" in
				clear) rm -f "$AB_STATS_DIR/jb" "$AB_STATS_DIR/ja" ;;
				0|800|2500|8000)
					_ab_put jsize "$m"
					if [ "$m" = 0 ]; then rm -f "$AB_STATS_DIR/jb" "$AB_STATS_DIR/ja"
					else _ab_jtrim "$AB_STATS_DIR/jb" "$m"; _ab_jtrim "$AB_STATS_DIR/ja" "$m"; fi ;;
				*) echo '{"error":"неизвестный размер журнала"}'; return 1 ;;
			esac
			_ab_journal "log all" ;;
		stats_set)
			_job_alive adblock && { echo '{"error":"список сейчас обновляется — включите чуть позже"}'; return 1; }
			if [ "$m" = on ]; then
				_ab_on && _ab_applied || { echo '{"error":"сначала включите блокировку рекламы"}'; return 1; }
				v="$(_ab_stats_block)" && { printf '{"error":"%s"}\n' "$(esc "Журнал dnsmasq уже направлен в другое место строкой log-facility в $v — статистика не сможет его читать. Уберите эту строку и включите статистику снова")"; return 1; }
				_ab_put stats 1 stats_since "$(date +%s)"
				mkdir -p "$AB_STATS_DIR"
				_ab_stats_plug
				_ab_stats_cron on
			else
				_ab_put stats 0
				_ab_stats_unplug
				_ab_stats_cron off
			fi
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			if [ "$m" = on ] && ! _ab_stats_guard; then
				echo '{"error":"dnsmasq не запустился со статистикой — она выключена, DNS работает как раньше. Подробности — в системном журнале"}'
				return 1
			fi
			[ "$m" = on ] || _ab_stats_wipe
			_ab_free_sync >/dev/null 2>&1
			if _ab_stats_on; then _ab_stats_json 24; else printf '{"on":false}\n'; fi ;;
		free_set)
			_job_alive adblock && { echo '{"error":"список сейчас обновляется — сохраните чуть позже"}'; return 1; }
			mkdir -p "$AB_DIR"
			printf '%s\n' "$m" | tr -d '\r' | awk -F'|' '{ mac = tolower($1); gsub(/-/, ":", mac); if (mac !~ /^[0-9a-f]{2}(:[0-9a-f]{2}){5}$/ || s[mac]++) next; n = $2; gsub(/[|"\\\t]/, " ", n); print mac "|" substr(n, 1, 48) }' | head -n 64 > "$AB_FREE.zm-new"
			if [ -s "$AB_FREE.zm-new" ]; then mv -f "$AB_FREE.zm-new" "$AB_FREE"; else rm -f "$AB_FREE.zm-new" "$AB_FREE"; fi
			if _ab_free_sync; then _ab_free_json
			else printf '{"error":"%s"}\n' "$(esc "выбор сохранён, но DNS без блокировки не запустился — устройства пока получают общий DNS")"; return 1; fi ;;
		auto)
			[ "$m" = 1 ] && v=1 || v=0
			_ab_put auto "$v"
			_ab_cron_sync
			printf '{"ok":true,"auto":%s,"minute":"%s"}\n' "$([ "$v" = 1 ] && echo true || echo false)" "$(_ab_get minute "")" ;;
		exempt) _ab_exempt_json ;;
		allow_set)
			_job_alive adblock && { echo '{"error":"список сейчас обновляется — сохраните чуть позже"}'; return 1; }
			mkdir -p "$AB_DIR"
			if [ "$m" = default ]; then rm -f "$AB_ALLOW"
			else printf '%s\n' "$m" | tr -d '\r' | head -c 65536 > "$AB_ALLOW.zm-new" && mv -f "$AB_ALLOW.zm-new" "$AB_ALLOW"; fi
			n=""
			if _ab_on && _ab_applied; then
				n="$(_ab_rebuild)" || { printf '{"error":"%s"}\n' "$(esc "белый список сохранён, но применить не удалось: $n")"; return 1; }
			fi
			printf '{"ok":true,"count":%s,"entries":%s}\n' "${n:-0}" "$(_ab_allow_text | _ab_allow_norm | wc -l | tr -d ' ')" ;;
		block_set)
			_job_alive adblock && { echo '{"error":"список сейчас обновляется — сохраните чуть позже"}'; return 1; }
			mkdir -p "$AB_DIR"
			printf '%s\n' "$m" | tr -d '\r' | head -c 65536 > "$AB_BLOCK.zm-new"
			if grep -q '[^[:space:]]' "$AB_BLOCK.zm-new"; then mv -f "$AB_BLOCK.zm-new" "$AB_BLOCK"; else rm -f "$AB_BLOCK.zm-new" "$AB_BLOCK"; fi
			n=""
			if _ab_on && _ab_applied; then
				n="$(_ab_rebuild)" || { printf '{"error":"%s"}\n' "$(esc "чёрный список сохранён, но применить не удалось: $n")"; return 1; }
			fi
			printf '{"ok":true,"count":%s,"entries":%s}\n' "${n:-0}" "$(_ab_block_text | _ab_allow_norm | wc -l | tr -d ' ')" ;;
		check) _ab_check "$m" ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
}

adblock_cron() {
	_ab_on && [ "$(_ab_get auto 1)" = 1 ] || { _ab_cron_sync; rm -f "$JOBS_DIR/adblock.auto"; return 0; }
	_job_alive adblock && return 0
	if _zm_busy_job >/dev/null; then mkdir -p "$JOBS_DIR"; : > "$JOBS_DIR/adblock.auto"; return 0; fi
	rm -f "$JOBS_DIR/adblock.auto"
	job_start adblock do_ab_apply force >/dev/null
}

_ab_auto_due() {
	local u
	[ "$(_ab_get auto 1)" = 1 ] || { rm -f "$JOBS_DIR/adblock.auto"; return 1; }
	[ -n "$(find "$JOBS_DIR/adblock.auto.try" -mmin -180 2>/dev/null)" ] && return 1
	[ -f "$JOBS_DIR/adblock.auto" ] && return 0
	u="$(_ab_get updated 0)"
	case "$u" in ''|*[!0-9]*) return 1 ;; esac
	[ "$u" -gt 0 ] && [ $(( $(date +%s) - u )) -gt 93600 ]
}

_ab_watch() {
	local stamp="$JOBS_DIR/adblock.watch" r
	if ! _ab_on; then
		{ _ab_free_alive || nft list table inet "$AB_FREE_NFT" >/dev/null 2>&1; } && _ab_free_stop
		nft list table inet "$AB_IP_NFT" >/dev/null 2>&1 && _ab_ip_stop
		return 0
	fi
	_job_alive adblock || _ab_free_sync >/dev/null 2>&1
	if ! _job_alive adblock; then
		if _ab_ip_sync >/dev/null 2>&1; then rm -f "$JOBS_DIR/adblock.ip.warn"
		elif [ ! -f "$JOBS_DIR/adblock.ip.warn" ]; then
			: > "$JOBS_DIR/adblock.ip.warn"
			logger -t zapret-manager "Блокировка рекламы: опасные IP не загрузились в файрвол — пробуем снова при каждой проверке"
		fi
	fi
	if _ab_stats_on && _ab_applied && ! _ab_stats_applied; then
		if _ab_stats_block >/dev/null; then
			_ab_put stats 0; _ab_stats_cron off
			logger -t zapret-manager "Блокировка рекламы: статистика выключена — журнал dnsmasq направлен в другое место строкой log-facility"
		else
			_ab_stats_plug; _ab_stats_cron on
			/etc/init.d/dnsmasq restart >/dev/null 2>&1
			_ab_stats_guard >/dev/null 2>&1
		fi
	fi
	if _ab_applied && ! _job_alive adblock && _ab_auto_due && ! _zm_busy_job >/dev/null; then
		mkdir -p "$JOBS_DIR"; : > "$JOBS_DIR/adblock.auto.try"
		if [ -f "$JOBS_DIR/adblock.auto" ]; then logger -t zapret-manager "Блокировка рекламы: ночное обновление ждало другую операцию — обновляем списки сейчас"
		else logger -t zapret-manager "Блокировка рекламы: списки не обновлялись больше суток — обновляем сейчас"; fi
		rm -f "$JOBS_DIR/adblock.auto"
		job_start adblock do_ab_apply force >/dev/null
		return 0
	fi
	_ab_applied && return 0
	_job_alive adblock && return 0
	[ -n "$(find "$stamp" -mmin -10 2>/dev/null)" ] && return 0
	touch "$stamp"
	if r="$(_ab_rebuild)"; then
		logger -t zapret-manager "Блокировка рекламы: список снова подключён к dnsmasq ($(_ab_dom "$r"))"
		return 0
	fi
	_zm_busy_job >/dev/null && return 0
	logger -t zapret-manager "Блокировка рекламы: нет готового списка ($r) — скачиваем заново"
	job_start adblock do_ab_apply >/dev/null
}
ZM_INSTALLER_EOF
mkdir -p /etc/init.d
cat > /etc/init.d/manager-watch-events << 'ZM_INSTALLER_EOF'
#!/bin/sh /etc/rc.common
START=99
USE_PROCD=1

start_service() {
    procd_open_instance
    procd_set_param command /usr/bin/ucode /usr/libexec/manager-watch.uc listen
    procd_set_param respawn 3600 5 0
    procd_set_param stderr 1
    procd_close_instance
}
ZM_INSTALLER_EOF
chmod 0755 /etc/init.d/manager-watch-events

mkdir -p /opt/zapret-manager-luci
cat > /opt/zapret-manager-luci/compat-policy.sh << 'ZM_INSTALLER_EOF'
# Narrow integration boundaries. Independent original AWG/Hosts/Adblock/TG/Tailscale stay intact.
_zm_net_heal() { echo 'Manager does not change router DNS for downloads' >&2; return 1; }
_zm_net_restore() { return 0; }
_zm_net_recover() { return 1; }
_zm_refs_heal() { return 1; }
_ft_zapret_sync() { return 0; }
_ft_zapret_gone() { return 0; }
_ft_steer_sync() { return 0; }
_zo_doh_follow() { return 0; }
_tsc_fk() { return 0; }
_tsc_zapret() { return 0; }
_au_on() { [ -f "$ZM_STATE_DIR/au.$1" ]; }
_au_items() {
 sed 's/},{/}\n{/g' "$VERSIONS_CACHE" 2>/dev/null | sed -n 's/.*"name":"\([^"]*\)","installed":"\([^"]*\)","latest":"\([^"]*\)".*/\1\t\2\t\3/p' |
 awk -F '\t' '$3 != "" && $2 != $3 && ($1=="Zapret Manager" || $1=="forkop" || $1=="sing-box-forkop" || $1=="nfqws2-keenetic" || $1=="nfqws2-ui" || $1 ~ /^TG WS Proxy/ || $1=="sTGWS" || $1=="AmneziaWG")'
}
_compat_update_sync() {
 local component="$1" reply phase message pid count=0
 reply="$(/usr/libexec/manager-compat status)" || return 1
 message="$(printf '%s' "$reply" | jsonfilter -e '@.forkop.busy')"
 case "$message" in ''|null|false) ;; *) echo 'ОШИБКА: Forkop занят; обновление отложено'; return 1 ;; esac
 reply="$(/usr/libexec/manager-compat action "$component" update_auto)" || return 1
 printf '%s' "$reply" | jsonfilter -e '@.ok' | grep -qx true || { echo "ОШИБКА: $reply"; return 1; }
 pid="$(cat /tmp/manager-components/pid)"
 while [ "$count" -lt 480 ]; do
  [ "$(cat /tmp/manager-components/pid 2>/dev/null)" = "$pid" ] || { echo 'ОШИБКА: задание изменилось'; return 1; }
  phase="$(jsonfilter -i /tmp/manager-components/state.json -e '@.phase')"
  case "$phase" in
   succeeded) return 0 ;;
   failed|interrupted) message="$(jsonfilter -i /tmp/manager-components/state.json -e '@.message')"; echo "ОШИБКА: ${message:-обновление не удалось}"; return 1 ;;
  esac
  kill -0 "$pid" 2>/dev/null || { echo 'ОШИБКА: обновление прервано'; return 1; }
  sleep 5; count=$((count + 1))
 done
 echo 'ОШИБКА: обновление ещё не завершилось'; return 1
}
_au_comp() {
 local component marker
 case "$1" in
  forkop|sing-box-forkop) component=forkop ;;
  nfqws2-keenetic|nfqws2-ui) component=nfqws2 ;;
  'TG WS Proxy (Go, MTProto)'|'TG WS Proxy (SOCKS5)'|'TG WS Proxy (Rust)'|sTGWS|AmneziaWG) _au_comp_upstream "$@"; return $? ;;
  *) return 0 ;;
 esac
 marker="$AU_LOCK/$component"
 if [ ! -f "$marker" ]; then
  : > "$marker"
  _au_one "$1" "$2" "$3" au_compat job_start au_compat _compat_update_sync "$component"
 else
  _au_check "$1" "$2" "$3"
 fi
}
_au_vnorm() { printf '%s' "$1" | sed 's/^v//;s/-r/./'; }
_compat_versions_add() {
 local package repo cur latest tag response newer
 for package in forkop sing-box-forkop nfqws2-keenetic nfqws2-ui; do
  cur="$(_awg_pkg_ver "$package")"
  [ -n "$cur" ] || continue
  latest=''
  if [ -n "$ZM_VER_LOCAL" ]; then
   latest="$(_ver_old "$package")"
  else
   case "$package" in
    forkop) repo=ushan0v/forkop ;;
    sing-box-forkop) repo=ushan0v/sing-box-forkop ;;
    nfqws2-keenetic) repo=nfqws/nfqws2-keenetic ;;
    nfqws2-ui) repo=zemidala/nfqws2-ui ;;
   esac
   response="$(curl -fsSL --connect-timeout 5 --max-time 15 "https://api.github.com/repos/$repo/releases/latest" 2>/dev/null)" || response=''
   tag="$(printf '%s' "$response" | jsonfilter -e '@.tag_name' 2>/dev/null)"
   tag="${tag#v}"
   if printf '%s' "$tag" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+(-r[0-9]+)?$'; then
    latest="$tag"
    if [ "$package" = nfqws2-ui ]; then
     tag="$(printf '%s' "$response" | jsonfilter -e '@.assets[*].name' 2>/dev/null | sed -n 's/^nfqws2-ui_\([0-9][0-9.]*\)-\([0-9][0-9]*\)_all\.apk$/\1-r\2/p' | head -n1)"
     [ -z "$tag" ] || latest="$tag"
    fi
   fi
  fi
  if [ -n "$latest" ]; then
   newer="$(awk -v a="$cur" -v b="$latest" 'BEGIN {split(a,x,/[.-]/);split(b,y,/[.-]/);sub(/^r/,"",x[4]);sub(/^r/,"",y[4]);for(i=1;i<=4;i++){if(y[i]+0>x[i]+0){print 1;exit}if(y[i]+0<x[i]+0){print 0;exit}}print 0}')"
   [ "$newer" = 1 ] || latest="$cur"
  fi
  add "$(printf '{"name":"%s","installed":"%s","latest":"%s","check_error":%s}' "$(esc "$package")" "$(esc "$cur")" "$(esc "$latest")" "$([ -n "$latest" ] && echo false || echo true)")"
 done
}
_compat_forkop_uses() {
 _zm_re "$1" '^[A-Za-z0-9_][A-Za-z0-9_.-]{0,14}$' || return 1
 uci -q show forkop | grep -F "='$1'" | grep -qE '\.(name|interface|network_interface|output_network_interface)='
}
_awg_fk_secs() { _compat_forkop_uses "$1" && echo forkop; }
_awg_fk_live() { pidof sing-box >/dev/null 2>&1 && _compat_forkop_uses "$1"; }
_awg_iface_json() {
 local original info
 _zmE awg || return $?
 original="$(_awg_iface_json_upstream "$1")" || return 1
 info="$(ucode /usr/libexec/manager-awg-info.uc "$1" 2>/dev/null)" || info='{"automatic":"unknown","usage":[],"forkop_error":true}'
 printf '%s,"routing":%s}\n' "${original%?}" "$info"
}
_zmL() {
 case "$1" in
  zapret|zapret2|test|steer1|steer2|forkozz|mixomo|bytetube|doh)
   case " $_ZM_ML " in *" shared "*) ;; *) _zmL_upstream shared || return $? ;; esac
   case " $_ZM_ML " in *" $1 "*) return 127 ;; esac
   _ZM_ML="$_ZM_ML $1"
   ;;
  *) _zmL_upstream "$@" || return $? ;;
 esac
 . /opt/zapret-manager-luci/compat-policy.sh
}
_fk_name() { echo Forkop; }
watch_status() {
 _zmE monitor || return $?
 local original recovery forkop=false nfqws2=false
 original="$(watch_status_upstream)" || return 1
 recovery="$(/usr/bin/ucode /usr/libexec/manager-watch.uc status)" || recovery='{}'
 [ -n "$(_awg_pkg_ver forkop)" ] && /etc/init.d/forkop enabled >/dev/null 2>&1 && [ "$(printf '%s' "$recovery" | jsonfilter -e '@.forkop')" = true ] && forkop=true
 [ -n "$(_awg_pkg_ver nfqws2-keenetic)" ] && /etc/init.d/nfqws2-keenetic enabled >/dev/null 2>&1 && [ "$(printf '%s' "$recovery" | jsonfilter -e '@.nfqws2')" = true ] && nfqws2=true
 printf '%s' "$original" | sed 's/"items":\[/"items":[{"id":"forkop","title":"Forkop","what":"Восстанавливает Forkop после сбоя sing-box-forkop, если штатный перезапуск не помог.","active":'"$forkop"'},{"id":"nfqws2","title":"NFQWS2","what":"Запускает NFQWS2 снова, если он аварийно завершился.","active":'"$nfqws2"'},/'
}
_compat_health() {
 local tg=0 ts=0 term=0 service awg_json awg_state components forkop=3 nfqws2=3 version running item state
 components="$(/usr/libexec/manager-compat status 2>/dev/null)"
 for service in forkop nfqws2; do
  version="$(printf '%s' "$components" | jsonfilter -e "@.$service.version" 2>/dev/null)"
  running="$(printf '%s' "$components" | jsonfilter -e "@.$service.running" 2>/dev/null)"
  item="$(printf '%s' "$components" | jsonfilter -e "@.$service" 2>/dev/null)"
  state=3
  if [ -n "$item" ]; then
   if [ -z "$version" ]; then state=0
   elif [ "$running" = true ]; then state=1
   elif [ "$running" = false ]; then state=2
   fi
  fi
  case "$service" in forkop) forkop="$state" ;; nfqws2) nfqws2="$state" ;; esac
 done
 for service in tg-ws-proxy tg-ws-proxy-go tg-ws-proxy-rs tgws; do
  [ -x "/etc/init.d/$service" ] || continue
  [ "$tg" != 0 ] || tg=1
  ubus call service list "{\"name\":\"$service\"}" 2>/dev/null | jsonfilter -e '@.*.instances.*.running' | grep -qx true || tg=2
 done
 if command -v tailscale >/dev/null 2>&1; then ts=5; pidof tailscaled >/dev/null 2>&1 && ts=1; fi
 if _term_installed; then term=4; _term_running && term=1; fi
 awg_json="$(_awg_health)"; awg_state="${awg_json%%,*}"
 printf '{"dots":{"forkop":%s,"nfqws2":%s,"term":%s,"awg":%s,"tg":%s,"ts":%s},"awg":%s,"tg":%s,"tg_info":"%s","tsc":%s,"term":%s,"htop":%s}\n' "$forkop" "$nfqws2" "$term" "$awg_state" "$tg" "$ts" "$awg_json" "$tg" "$(esc "$(_tg_dash_info)")" "$ts" "$term" "$([ -x /usr/bin/htop ] && echo true || echo false)"
}
_compat_preflight() {
 if [ -d /tmp/manager-maintenance.lock ] && [ "${COMPAT_MAINTENANCE:-}" != 1 ] && [ "${COMPAT_BACKUP:-}" != 1 ] && [ "$1" != job_status ] && [ "$1" != log_tail ] && [ "$1" != awg_status ]; then
  echo '{"error":"Дождитесь завершения текущей операции"}'
  return 1
 fi
 case "$1" in
  zapret_*|zapret2_*|str_refresh|strategy_*|test_*|ts_check|nfqws_opt_*|youtube_quic_set|discord_*|game_*|exclusions_*|zsec2_*|steer_*|forkop_*|mixomo_*|bytetube_*|doh_*|dns_net_set|system_toggle_quic|system_toggle_ipv6|system_toggle_flow_offloading_fix|system_toggle_steer_offload_fix)
   echo '{"error":"Этот компонент недоступен в этой версии панели"}'; return 1 ;;
  awg_action) [ "${2:-}" != mihomo ] || { echo '{"error":"Mixomo недоступен в этой версии панели"}'; return 1; } ;;
 esac
 return 0
}
_zm_run_cmd() {
 _compat_preflight "$cmd" "$@" || return $?
 case "$cmd" in
  compat_backup_before)
   case "${1:-}" in forkop|nfqws2) _bk_auto "do_compat_$1" ;; *) return 1 ;; esac ;;
  health) _compat_health ;;
  tgws_action)
   case "${1:-}" in install|update|reinstall|remove|restart|reconfigure)
    if pidof sing-box >/dev/null 2>&1; then echo '{"error":"Остановите Forkop перед изменением sTGWS: компоненты используют общую conntrack-метку"}'; return 1; fi ;;
   esac
   _zm_run_cmd_upstream "$@" ;;
  *) _zm_run_cmd_upstream "$@" ;;
 esac
}

# Component configuration roots used by the original backup engine.
BK_ORDER="forkop_native nfqws2 nfqws2_ui awg tgproxy stgws tailscale terminal htop adblock hosts"

_bk_auto() {
 [ "${1:-}" != do_awg_proton_generate ] || return 0
 _zmE system || return $?
 [ "${COMPAT_BACKUP:-}" != 1 ] || return 0
 _bk_auto_upstream "$@"
}
_bk_auto_why() {
 _zmE system || return $?
 case "$1" in
  do_compat_forkop) echo 'перед изменением Forkop' ;;
  do_compat_nfqws2) echo 'перед изменением NFQWS2' ;;
  *) _bk_auto_why_upstream "$@" ;;
 esac
}

_pg_inst() {
 _zmE system || return $?
 if [ "${COMPAT_PURGE:-}" = 1 ]; then
  case "$1" in forkop_native|nfqws2)
   for package in $(_compat_component_packages "$1"); do _pg_pkg "$package" && return 0; done
   return 1 ;;
  esac
 fi
 case "$1" in
  forkop_native) [ -n "$(_awg_pkg_ver forkop)" ] ;;
  nfqws2) [ -n "$(_awg_pkg_ver nfqws2-keenetic)" ] ;;
  nfqws2_ui) [ -n "$(_awg_pkg_ver nfqws2-ui)" ] ;;
  *) _pg_inst_upstream "$@" ;;
 esac
}
_pg_trace() {
 _zmE system || return $?
 if [ "${COMPAT_PURGE:-}" = 1 ]; then _compat_purge_trace "$@"; return $?; fi
 case "$1" in
  awg) _pg_trace_upstream awg; echo '/opt/zapret-manager-luci/state/proton' ;;
  forkop_native) echo 'pkg:forkop pkg:sing-box-forkop /etc/config/forkop /etc/config/sing-box /etc/init.d/forkop' ;;
  nfqws2) echo 'pkg:nfqws2-keenetic /etc/nfqws2 /etc/init.d/nfqws2-keenetic' ;;
  nfqws2_ui) echo 'pkg:nfqws2-ui /etc/nfqws-ui /etc/nfqws_web.conf /etc/init.d/lighttpd' ;;
  *) _pg_trace_upstream "$@" ;;
 esac
}
_bk_name() {
 _zmE system || return $?
 case "$1" in
  forkop_native) echo Forkop ;;
  nfqws2) echo NFQWS2 ;;
  nfqws2_ui) echo nfqws2-ui ;;
  *) _bk_name_upstream "$@" ;;
 esac
}
_bk_comps() {
 local component
 for component in $BK_ORDER; do
  case "$component" in
   forkop_native|nfqws2|nfqws2_ui)
    if [ -n "${COMPAT_BK_SCOPE:-}" ]; then
     case " $COMPAT_BK_SCOPE " in *" $component "*) ;; *) continue ;; esac
    fi ;;
  esac
  _pg_inst "$component" >/dev/null 2>&1 && printf '%s ' "$component"
 done
 return 0
}
_bk_skip() {
 _zmE system || return $?
 case "$1" in
  /opt/zapret-manager-luci/mod|/opt/zapret-manager-luci/mod/*|/opt/zapret-manager-luci/compat-policy.sh|/opt/zapret-manager-luci/pages.b64|/opt/zapret-manager-luci/files.list) return 0 ;;
  /etc/nfqws2/.snapshots|/etc/nfqws2/.snapshots/*|/etc/nfqws2/.history|/etc/nfqws2/.history/*) return 0 ;;
  /etc/nfqws-ui/remote_key|/etc/nfqws-ui/remote_key.pub|/etc/nfqws-ui/known_hosts) return 0 ;;
  /etc/nfqws-ui/nfq-update.json|/etc/nfqws-ui/update.log) return 0 ;;
 esac
 _bk_skip_upstream "$@"
}
_bk_install() {
 _zmE system || return $?
 local component operation=update reply phase attempts=0
 case "$1" in
  forkop_native) component=forkop ;;
  nfqws2|nfqws2_ui) component=nfqws2 ;;
  *) _bk_install_upstream "$@"; return $? ;;
 esac
 _pg_inst "$1" && return 0
 if [ "$component" = nfqws2 ] && [ -x /etc/init.d/nfqws2-keenetic ]; then
  /etc/init.d/nfqws2-keenetic stop || return 1
  /etc/init.d/nfqws2-keenetic disable || return 1
 fi
 reply="$(COMPAT_BACKUP=1 /usr/libexec/manager-compat action "$component" "$operation")" || return 1
 [ "$(printf '%s' "$reply" | jsonfilter -e '@.ok')" = true ] || return 1
 while [ "$attempts" -lt 600 ]; do
  phase="$(jsonfilter -i /tmp/manager-components/state.json -e '@.phase')"
  case "$phase" in
   succeeded) return 0 ;;
   failed|interrupted) return 1 ;;
  esac
  sleep 2
  attempts=$((attempts + 1))
 done
 return 1
}
_compat_backup_scope() {
 local component
 COMPAT_BK_SCOPE=" $(_bk_m comps) "
 for component in $(_bk_m comps); do
  case " $BK_ORDER " in *" $component "*) ;; *)
   echo '{"error":"В копии есть компоненты другой редакции панели"}'
   return 1 ;;
  esac
 done
}
backup_diff() (
 _zmE system || exit $?
 _bk_open "$1" || { printf '{"error":"%s"}\n' "$(esc "$BK_ERR")"; exit 1; }
 _compat_backup_scope || { _bk_close; exit 1; }
 _bk_close
 backup_diff_upstream "$@"
)
do_backup_restore() (
 _zmE system || exit $?
 _bk_open "$1" || { echo "Не удалось открыть копию"; exit 1; }
 _compat_backup_scope || { _bk_close; exit 1; }
 _bk_close
 ZM_CLEAN_SELF=backup
 _compat_maintenance_acquire || exit 1
 trap '_compat_maintenance_release' EXIT
 do_backup_restore_upstream "$@"
)

ZPG_IDS="forkop nfqws2 tgproxy awg tailscale hosts adblock terminal monitor openwrt"
ZPG_LIST='forkop|Forkop|Обход блокировок|Маршруты и подключения
nfqws2|NFQWS2|Обход блокировок|Обход блокировок без VPN
tgproxy|TG WS Proxy|VPN и прокси|Прокси для Telegram
hosts|Hosts|DNS и сеть|Домены и списки hosts
adblock|Блокировка рекламы|DNS и сеть|Реклама, трекеры и фишинг
awg|AmneziaWG|VPN и прокси|Туннели AmneziaWG и WARP
tailscale|Удалённый доступ|VPN и прокси|Роутер и домашняя сеть из любой сети
terminal|Терминал|Инструменты|Командная строка роутера в браузере
monitor|Монитор ресурсов|Инструменты|Нагрузка и память роутера
openwrt|Настройка OpenWrt|Инструменты|Сеть и настройки роутера'

_zpg_used() {
 _zmE system || return $?
 case "$1" in
  forkop) [ -n "$(_awg_pkg_ver forkop)" ] ;;
  nfqws2) [ -n "$(_awg_pkg_ver nfqws2-keenetic)" ] || [ -n "$(_awg_pkg_ver nfqws2-ui)" ] ;;
  *) _zpg_used_upstream "$@" ;;
 esac
}
_zpg_core_bytes() {
 local file size total=0
 while IFS= read -r file; do
  [ -f "$file" ] || continue
  size="$(wc -c < "$file")"
  total=$((total + size))
 done < /opt/zapret-manager-luci/files.list
 echo "$total"
}
do_zpg_restore() (
 local id file needed="" staging
 for id in $ZPG_IDS; do
  _zpg_is_off "$id" || _zpg_have "$id" || needed="$needed $id"
 done
 [ -n "$needed" ] || { echo 'Все выбранные страницы уже на месте'; exit 0; }
 umask 077
 staging="$(mktemp -d /tmp/manager-pages.XXXXXX)" || exit 1
 trap 'rm -rf "$staging"' EXIT
 ucode /opt/zapret-manager-luci/b64.uc dec /opt/zapret-manager-luci/pages.b64 "$staging/pages.tgz" || exit 1
 tar -xzf "$staging/pages.tgz" -C "$staging" || exit 1
 for id in $needed; do
  file="$ZPG_V/$id.js"
  cp "$staging$file" "$file.next" || exit 1
  chmod 644 "$file.next"
  mv -f "$file.next" "$file" || exit 1
 done
 cp "$staging$ZPG_MENU" "$ZPG_MENU" || exit 1
 chmod 644 "$ZPG_MENU"
 _zmE system || exit $?
 _zpg_menu_filter
 _zpg_rebuild
 echo 'Выбранные страницы возвращены'
)

# Native package metadata and service controllers remain the source of truth.
PG_ORDER="forkop_native nfqws2 awg tgproxy stgws tailscale terminal htop adblock hosts panel"

_compat_maintenance_release() {
 local lock=/tmp/manager-maintenance.lock
 [ "$(cat "$lock/pid" 2>/dev/null)" = "$$" ] || return 0
 rm -f "$lock/pid"
 rmdir "$lock" 2>/dev/null || true
}
_compat_components_idle() {
 local result
 /usr/libexec/manager-watch.uc components-busy
 result=$?
 [ "$result" = 1 ]
}
_compat_maintenance_acquire() {
 local lock=/tmp/manager-maintenance.lock owner age
 if [ -L "$lock" ] || { [ -e "$lock" ] && [ "$(stat -c %u "$lock")" != 0 ]; }; then
  echo '{"error":"Не удалось подготовить операцию"}'
  return 1
 fi
 if [ -d "$lock" ]; then
  age=$(( $(date +%s) - $(stat -c %Y "$lock") ))
  if mkdir "$lock/reap" 2>/dev/null; then
   owner="$(cat "$lock/pid" 2>/dev/null)"
   case "$owner" in ''|*[!0-9]*) owner=0 ;; esac
   if { [ "$owner" -gt 0 ] && kill -0 "$owner" 2>/dev/null; } || [ "$age" -lt 5 ]; then
    rmdir "$lock/reap" 2>/dev/null
   else
    rm -f "$lock/pid"
    rmdir "$lock/reap" "$lock" 2>/dev/null || true
   fi
  fi
 fi
 if ! mkdir -m 700 "$lock" 2>/dev/null; then
  echo '{"error":"Дождитесь завершения текущей операции"}'
  return 1
 fi
 if ! echo "$$" > "$lock/pid"; then
  rmdir "$lock" 2>/dev/null
  return 1
 fi
 if _zm_busy_job >/dev/null 2>&1 || _au_live ||
    [ -d /tmp/manager-components/lock ] ||
    ! _compat_components_idle; then
  _compat_maintenance_release
  echo '{"error":"Дождитесь завершения текущей операции"}'
  return 1
 fi
 export COMPAT_MAINTENANCE=1
}

_pg_title() {
 case "$1" in
  forkop_native) echo Forkop ;; nfqws2) echo NFQWS2 ;;
  awg) echo AmneziaWG ;; tgproxy) echo 'TG WS Proxy' ;; stgws) echo sTGWS ;;
  tailscale) echo 'Удалённый доступ (Tailscale)' ;;
  terminal) echo Терминал ;; htop) echo htop ;;
  adblock) echo 'Блокировка рекламы' ;; hosts) echo Hosts ;;
  panel) echo 'Zapret Manager' ;;
 esac
}
_pg_group() {
 case "$1" in
  forkop_native|nfqws2) echo block ;;
  awg|tgproxy|stgws|tailscale) echo vpn ;;
  adblock|hosts) echo dns ;; terminal|htop) echo tools ;; panel) echo panel ;;
 esac
}
_compat_purge_trace() {
 case "$1" in
  awg) _pg_trace_upstream awg; echo '/opt/zapret-manager-luci/state/proton /tmp/manager-proton' ;;
  forkop_native)
   echo 'pkg:forkop pkg:luci-app-forkop pkg:luci-i18n-forkop-ru pkg:sing-box-forkop /etc/config/forkop /etc/forkop'
   ;;
  nfqws2)
   echo 'pkg:nfqws2-keenetic pkg:nfqws2-ui /etc/nfqws2 /etc/nfqws-ui /etc/nfqws_web.conf'
   ;;
  tailscale)
   _pg_trace_upstream "$1"
   echo 'pkg:luci-app-tailscale-ru-layout'
   ;;
  panel)
   _pg_trace_upstream "$1"
   echo '/usr/libexec/manager-compat /usr/libexec/manager-watch.uc /usr/libexec/manager-uninstall /usr/libexec/manager-forkop-remove.uc /etc/init.d/manager-watch-events /usr/libexec/rpcd/manager-compat /usr/share/rpcd/acl.d/manager-compat.json'
   ;;
  *) _pg_trace_upstream "$@" ;;
 esac
}
purge_scan() (
 COMPAT_PURGE=1
 _zmE system || exit $?
 purge_scan_upstream
)

_compat_purge_ids() {
 local input="$1" id result=""
 case "$input" in ''|*[!a-z0-9_,]*) return 1 ;; esac
 for id in $(printf '%s' "$input" | tr ',' ' '); do
  case " $PG_ORDER " in *" $id "*) ;; *) return 1 ;; esac
  case ",$result," in *",$id,"*) ;; *) result="$result${result:+,}$id" ;; esac
 done
 [ -n "$result" ] || return 1
 printf '%s\n' "$result"
}
_compat_awg_required() {
 local iface
 for iface in $(_awg_ifaces); do _awg_fk_live "$iface" && return 0; done
 return 1
}
_compat_purge_preflight() {
 local ids="$1"
 case ",$ids," in
  *,awg,*)
   case ",$ids," in *,forkop_native,*) ;; *)
    if _compat_awg_required; then
     echo '{"error":"В Forkop есть подключения через AmneziaWG. Уберите их или выберите Forkop вместе с AmneziaWG."}'
     return 1
    fi ;;
   esac ;;
 esac
}
purge_run() {
 local ids
 ids="$(_compat_purge_ids "$1")" || { echo '{"error":"Выберите программы для удаления"}'; return 1; }
 _compat_purge_preflight "$ids" || return 1
 if _zm_busy_job >/dev/null 2>&1 || [ -d /tmp/manager-maintenance.lock ]; then
  echo '{"error":"Дождитесь завершения текущей операции"}'
  return 1
 fi
 job_start purge do_purge "$ids"
}

_compat_component_packages() {
 case "$1" in
  forkop_native) echo 'luci-i18n-forkop-ru luci-app-forkop forkop sing-box-forkop' ;;
  nfqws2) echo 'nfqws2-ui nfqws2-keenetic' ;;
 esac
}
_compat_installed_packages() {
 local package
 for package in $(_compat_component_packages "$1"); do
  _pkg_is_installed "$package" && printf '%s ' "$package"
 done
 return 0
}
_compat_package_plan() {
 local packages="$1" package plan removed
 [ -n "$packages" ] || return 0
 if [ "$PKG" = apk ]; then
  plan="$(apk del --simulate --purge $packages 2>&1)" || { printf '%s\n' "$plan"; return 1; }
  removed="$(printf '%s\n' "$plan" | awk '{for (i=1;i<NF;i++) if ($i=="Purging") print $(i+1)}')"
  for package in $packages; do
   printf '%s\n' "$removed" | grep -qxF "$package" || {
    echo 'Компонент нужен другой программе. Удаление отменено.'
    return 1
   }
  done
 else
  opkg --noaction remove $packages || return 1
 fi
}
_compat_package_remove() {
 local packages="$1" package
 [ -n "$packages" ] || return 0
 if [ "$PKG" = apk ]; then apk del --purge $packages || return 1
 else opkg remove $packages || return 1; fi
 for package in $packages; do _pkg_is_installed "$package" && return 1; done
 return 0
}
_compat_component_remove() {
 local id="$1" packages core=""
 packages="$(_compat_installed_packages "$id")"
 _compat_package_plan "$packages" || return 1
 case "$id" in
  forkop_native)
   _pkg_is_installed sing-box-forkop && core=1
   if [ -x /usr/bin/forkop ]; then
    /usr/libexec/manager-forkop-remove.uc || return 1
   elif [ -x /etc/init.d/forkop ]; then
    /etc/init.d/forkop stop && /etc/init.d/forkop disable || return 1
   fi
   if [ -n "$core" ] && [ -x /etc/init.d/sing-box ]; then
    /etc/init.d/sing-box stop && /etc/init.d/sing-box disable || return 1
   fi
   # The native uninstaller may already have removed some of these packages.
   packages="$(_compat_installed_packages "$id")"
   _compat_package_remove "$packages" || return 1
   rm -rf /etc/forkop /var/run/forkop
   rm -f /etc/config/forkop /etc/config/forkop.apk-new /etc/config/forkop-opkg
   if [ -n "$core" ]; then
    rm -f /etc/config/sing-box /etc/config/sing-box.apk-new /etc/config/sing-box-opkg /etc/sing-box/config.json
    rmdir /etc/sing-box 2>/dev/null || true
   fi
   ;;
  nfqws2)
   if [ -x /etc/init.d/nfqws2-keenetic ]; then
    /etc/init.d/nfqws2-keenetic stop && /etc/init.d/nfqws2-keenetic disable || return 1
   elif pidof nfqws2 >/dev/null 2>&1; then
    echo 'NFQWS2 работает без штатной службы. Остановите его перед удалением.'
    return 1
   fi
   if [ -x /usr/sbin/nfqws-ui-setup ]; then /usr/sbin/nfqws-ui-setup remove || return 1; fi
   _compat_package_remove "$packages" || return 1
   rm -rf /etc/nfqws2 /etc/nfqws-ui /tmp/nfqws-ui-cache /tmp/nfqws-ui-test /tmp/nfqws-ui-sess
   rm -f /etc/nfqws_web.conf /tmp/nfqws-ui-pending.json /tmp/nfqws-ui-login.json
   ;;
 esac
}
do_purge() (
 local ids id rc=0 left
 COMPAT_PURGE=1
 ZM_CLEAN_SELF=purge
 _zmE system || exit $?
 ids="$(_compat_purge_ids "$1")" || exit 1
 _compat_purge_preflight "$ids" || exit 1
 _compat_maintenance_acquire || exit 1
 trap '_compat_maintenance_release' EXIT
 PG_CRON=""
 for id in $PG_ORDER; do
  case ",$ids," in *",$id,"*) ;; *) continue ;; esac
  [ "$id" != panel ] || continue
  echo "==> Удаляем $(_pg_title "$id")"
  if [ "$id" = awg ] && _compat_awg_required; then
   echo 'Не удалось удалить AmneziaWG. В Forkop остались подключения через его туннели.'
   rc=1
   continue
  fi
  case "$id" in
   forkop_native|nfqws2)
    if ! _compat_component_remove "$id"; then rc=1; continue; fi ;;
   *)
    if ! ( _pg_remove_upstream "$id" ); then rc=1; continue; fi
    _pg_sweep "$id"
    ;;
  esac
  left="$(_pg_found "$id")"
  if [ -n "$left" ]; then
   echo "Не всё удалось удалить. Проверьте $(_pg_title "$id") и повторите попытку."
   rc=1
  else echo "Удалено — $(_pg_title "$id")"; fi
 done
 [ -z "$PG_CRON" ] || /etc/init.d/cron restart >/dev/null 2>&1
 rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
 case ",$ids," in *,panel,*)
  if [ "$rc" != 0 ]; then
   echo 'Панель сохранена. Сначала завершите удаление выбранных программ.'
   exit 1
  fi
  ZM_PG_SELF=1 system_uninstall_panel wipe || exit 1
  echo 'Выбранные программы удалены, панель удаляется'
  exit 0 ;;
 esac
 [ "$rc" = 0 ] && echo 'Выбранные программы удалены' || echo 'Удаление завершилось с ошибками. Проверьте результат и повторите попытку.'
 exit "$rc"
)

_zm_junk() { _zm_junk_raw "$@"; }
_zm_junk_raw() {
 local file job
 for file in /tmp/zm-run.* /tmp/zm-wait.* /tmp/zm-quiet.* /tmp/zm-pkg.* /tmp/zm-rpc.* \
  /tmp/tg-ws-proxy.ipk /tmp/tg-ws-proxy.apk \
  "$JOBS_DIR"/tgws_install.* "$JOBS_DIR"/tg-ws-proxy-rs.tar.gz "$JOBS_DIR"/geohide_hosts.tmp \
  "$JOBS_DIR"/sysinfo.json "$JOBS_DIR"/sysinfo.res "$JOBS_DIR"/sysinfo.urls "$JOBS_DIR"/tzdet.* \
  "$JOBS_DIR"/cleanup.* "$JOBS_DIR"/bk.upload* "$BK_DIR"/.*.part "$BK_DIR"/.mk.* \
  /tmp/manager-components/*.log /tmp/manager-components/*.apk /tmp/manager-components/*.ipk \
  /opt/zapret-manager-luci/*.zm-new "$ZM_STATE_DIR"/latest.* "$ZM_STATE_DIR"/versions.json \
  "$ZM_STATE_DIR"/*.tmp "$HOSTS_FILE.zmtmp" "$HOSTS_FILE.zmdrop"; do
  case "$file" in "$JOBS_DIR/cleanup.$$"|"$JOBS_DIR/cleanup.refs.$$"|"$JOBS_DIR/cleanup.usage.$$") continue ;; esac
  case "$file" in "$JOBS_DIR"/bk.upload*|"$BK_DIR"/.*.part|"$BK_DIR"/.mk.*) _zm_aged "$file" 60 || continue ;; esac
  _zm_tmp_live "$file" && continue
  { [ -e "$file" ] || [ -L "$file" ]; } && echo "$file"
 done
 for file in "$JOBS_DIR"/*.log "$JOBS_DIR"/*.pid; do
  [ -f "$file" ] || continue
  job="${file##*/}"; job="${job%.*}"
  _job_running "$job" || echo "$file"
 done
 return 0
}
_zm_usage_json() {
 local page bytes total junk count=0 size=0 list="$JOBS_DIR/cleanup.usage.$$"
 total="$(_zpg_core_bytes)"
 for page in $ZPG_IDS; do
  _zpg_have "$page" || continue
  bytes="$(_zpg_bytes "$page")"
  total=$((total + bytes))
 done
 _zm_junk_raw "$1" > "$list"
 while IFS= read -r junk; do
  count=$((count + 1))
  size=$((size + $(_zm_kb "$junk")))
 done < "$list"
 rm -f "$list"
 printf '"flash_kb":%s,"lists_kb":%s,"tmp_kb":%s,"junk_kb":%s,"junk_n":%s,"flash_free_kb":%s,"tmp_free_kb":%s,"mem_free_kb":%s' \
  "$((total / 1024 + $(_zm_kb "$ZM_STATE_DIR" "$BK_DIR")))" "$(_zm_kb "$AB_DIR")" \
  "$(_zm_kb "$JOBS_DIR" /tmp/manager-components)" "$size" "$count" \
  "$(_zm_df_kb /opt/zapret-manager-luci)" "$(_zm_df_kb /tmp)" "$(_zm_mem_kb)"
}
_compat_clean_files() {
 local mode="$1" file kb count=0 flash=0 temporary=0 before after memory=0 list="$JOBS_DIR/cleanup.$$"
 mkdir -p "$JOBS_DIR"
 before="$(_zm_mem_kb)"
 _zm_junk_raw "$mode" > "$list"
 while IFS= read -r file; do
  case "$file" in */../*|*/..) continue ;; esac
  case "$file" in
   /tmp/zm[-_]*|/tmp/tg-ws-proxy.ipk|/tmp/tg-ws-proxy.apk|/tmp/manager-components/?*|/tmp/zapret-manager-luci/?*|/opt/zapret-manager-luci/?*|/etc/hosts.zmtmp|/etc/hosts.zmdrop) ;;
   *) continue ;;
  esac
  { [ -e "$file" ] || [ -L "$file" ]; } || continue
  kb="$(_zm_kb "$file")"
  rm -rf "$file" 2>/dev/null
  { [ -e "$file" ] || [ -L "$file" ]; } && continue
  count=$((count + 1))
  case "$file" in /tmp/*) temporary=$((temporary + kb)) ;; *) flash=$((flash + kb)) ;; esac
 done < "$list"
 rm -f "$list" /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
 if [ "$mode" != install ]; then
  sync
  ( echo 3 > /proc/sys/vm/drop_caches ) 2>/dev/null || true
 fi
 after="$(_zm_mem_kb)"
 memory=$((after - before))
 [ "$memory" -gt 0 ] || memory=0
 if [ "$mode" = auto ]; then
  mkdir -p "$ZM_STATE_DIR"
  echo "$(date +%s) $count $((flash + temporary)) $memory" > "$ZM_AC_LAST"
 fi
 printf '{"ok":true,"removed":%s,"freed_flash_kb":%s,"freed_tmp_kb":%s,"freed_mem_kb":%s,"refs_missing":0,%s}\n' \
  "$count" "$flash" "$temporary" "$memory" "$(_zm_usage_json "$mode")"
}
zm_cleanup() (
 local mode="$1" waited=0
 _zmE system || exit $?
 case "$mode" in ''|auto|job|after|postupd|install) ;; *) echo '{"error":"Неизвестный режим очистки"}'; exit 1 ;; esac
 case "$mode" in
  after|postupd)
   while { _zm_busy_job >/dev/null 2>&1 || _au_live || [ -d /tmp/manager-components/lock ]; } && [ "$waited" -lt 600 ]; do
    sleep 5; waited=$((waited + 5))
   done
   [ "$mode" != postupd ] && mode="" || mode=auto ;;
 esac
 if ! _compat_maintenance_acquire; then exit 1; fi
 trap '_compat_maintenance_release' EXIT
 _compat_clean_files "$mode"
)

system_uninstall_panel() {
 local mode="${1:-keep}" delay=1 script
 case "$mode" in keep|wipe) ;; *) echo '{"error":"Не удалось определить, нужно ли сохранить настройки"}'; return 1 ;; esac
 [ -z "${ZM_PG_SELF:-}" ] || delay=8
 if [ -z "${ZM_PG_SELF:-}" ]; then _compat_maintenance_acquire || return 1; fi
 script="$(mktemp /tmp/manager-uninstall.XXXXXX)" || { _compat_maintenance_release; return 1; }
 if ! cp /usr/libexec/manager-uninstall "$script"; then _compat_maintenance_release; return 1; fi
 chmod 700 "$script"
 if ! (
  sh "$script" "$mode" "$delay" > "$JOBS_DIR/uninstall-panel.log" 2>&1 &
  child=$!
  echo "$child" > /tmp/manager-maintenance.lock/pid || { kill "$child" 2>/dev/null; exit 1; }
 ); then _compat_maintenance_release; return 1; fi
 printf '{"ok":true,"queued":true,"kept":%s}\n' "$([ "$mode" = wipe ] && echo false || echo true)"
}

_manager_proton_call() {
 /usr/bin/ucode /usr/libexec/manager-proton "$@"
}

_manager_proton_release() {
 local owner="$1" lock=/tmp/manager-maintenance.lock
 [ "$(cat "$lock/pid" 2>/dev/null)" = "$owner" ] || return 0
 rm -f "$lock/pid"
 rmdir "$lock" 2>/dev/null || true
}

do_awg_remove() {
 do_awg_remove_upstream "$@" || return $?
 rm -f "$ZM_STATE_DIR/proton/Proton.conf"
 rmdir "$ZM_STATE_DIR/proton" 2>/dev/null || true
}

do_awg_proton_generate() (
 local owner reply message expected="$2" lock=/tmp/manager-maintenance.lock
 mkdir "$lock/proton-handoff" 2>/dev/null || exit 1
 if [ "$(cat "$lock/pid" 2>/dev/null)" != "$expected" ]; then
  rmdir "$lock/proton-handoff" 2>/dev/null
  exit 1
 fi
 read -r owner _ < /proc/self/stat
 if ! printf '%s\n' "$owner" > "$lock/pid"; then
  rmdir "$lock/proton-handoff" 2>/dev/null
  exit 1
 fi
 rmdir "$lock/proton-handoff" 2>/dev/null
 trap '_manager_proton_release "$owner"' EXIT
 trap 'exit 1' HUP INT TERM
 echo gen_proton > "$AWG_RUN/phase"
 if ! command -v openssl >/dev/null 2>&1; then
  echo '==> Подготавливаем создание профиля Proton VPN'
  $UPDATE 2>&1 | _zm_pkg_fmt
  $INSTALL openssl-util 2>&1 | _zm_pkg_fmt
  command -v openssl >/dev/null 2>&1 || {
   echo 'ОШИБКА: не удалось подготовить создание профиля. Проверьте подключение к интернету и свободное место.'
   exit 1
  }
 fi
 echo '==> Создаём профиль Proton VPN'
 reply="$(_manager_proton_call generate "$1" "$MIXOMO_AWG_I1")"
 if [ "$(printf '%s' "$reply" | jsonfilter -e '@.ok')" != true ]; then
  message="$(printf '%s' "$reply" | jsonfilter -e '@.error')"
  printf 'ОШИБКА: %s\n' "${message:-Не удалось создать профиль. Попробуйте ещё раз или загрузите свой файл.}"
  exit 1
 fi
 echo '==> Профиль Proton VPN создан'
 echo 'Используйте его ниже, чтобы создать интерфейс.'
)

awg_action() {
 _zmE awg || return $?
 case "$1" in
  proton_status) _manager_proton_call status ;;
  proton_servers)
   case "${2:-}" in ''|refresh) _manager_proton_call servers "${2:-}" ;; *) echo '{"error":"Не удалось обновить серверы."}'; return 1 ;; esac
   ;;
  proton_config) _manager_proton_call config ;;
  proton_generate)
   _awg_installed || { echo '{"error":"Сначала установите AmneziaWG."}'; return 1; }
   [ -n "$2" ] && [ "${#2}" -le 256 ] || { echo '{"error":"Выберите сервер Proton VPN."}'; return 1; }
   _compat_maintenance_acquire || return 1
   mkdir -p "$AWG_RUN" || { _compat_maintenance_release; return 1; }
   job_start awg do_awg_proton_generate "$2" "$$"
   ;;
  *) awg_action_upstream "$@" ;;
 esac
}
ZM_INSTALLER_EOF
chmod 0644 /opt/zapret-manager-luci/compat-policy.sh

mkdir -p /opt/zapret-manager-luci
