	local out="$1"
	: > "$out"
	printf '%s\n' \
		"gosuslugi.ru|https://www.gosuslugi.ru" \
		"esia.gosuslugi.ru|https://esia.gosuslugi.ru" \
		"nalog.ru|https://nalog.ru" \
		"lkfl2.nalog.ru|https://lkfl2.nalog.ru" \
		"rutube.ru|https://rutube.ru" \
		"ntc.party|https://ntc.party/" \
		"instagram.com|https://instagram.com" \
		"facebook.com|https://facebook.com" \
		"rutracker.org|https://rutracker.org" \
		"nnmclub.to|https://nnmclub.to" \
		"rutor.info|https://rutor.info" \
		"openwrt.org|https://openwrt.org" \
		"discord.com|https://discord.com" \
		"x.com|https://x.com" \
		"forum.ru-board.com|https://forum.ru-board.com" \
		"play.google.com|https://play.google.com" \
		"downloads.openwrt.org|https://downloads.openwrt.org" \
		"githubusercontent.com|https://raw.githubusercontent.com/StressOzz/Zapret-Manager/refs/heads/main/Zapret-Manager.sh" \
		>> "$out"
	curl -fsSL --connect-timeout 8 --max-time 15 "$TEST_DOMAINS_JSON" 2>/dev/null \
		| sed -n 's/.*"id":[[:space:]]*"\([^"]*\)".*"host":[[:space:]]*"\([^"]*\)".*/\1|\2/p' >> "$out"
}

_v_ok() { _zm_re "$1" '^v[0-9]+$' && _str_has StrV "$1"; }

_zm_excl_hits() {
	[ -s "$1" ] || [ -s "${2:-/nonexistent}" ] || { cat >/dev/null; return 0; }
	ZM_EXCL="$(head -n1 "$1" 2>/dev/null)" ZM_HIDE="${2:-}" awk -F'\t' "$ZM_FOLD_AWK"'
		BEGIN {
			c = split(ENVIRON["ZM_EXCL"], a, /[|,]/); n = 0
			for (i = 1; i <= c; i++) { t = a[i]; gsub(/^[ \t]+|[ \t]+$/, "", t); if (t != "") m[++n] = fold(t) }
			f = ENVIRON["ZM_HIDE"]
			if (f != "") while ((getline l < f) > 0) if (l != "") h[l] = 1
		}
		{
			if ($2 in h) { print $1; next }
			nm = fold($2); for (i = 1; i <= n; i++) if (index(nm, m[i])) { print $1; break }
		}'
}

do_mixomo_warp_integrate() {
	[ -s "$MIXOMO_WARP_CONF" ] || { echo "ОШИБКА: сначала сгенерируйте WARP.conf"; return 1; }
	[ -x /etc/init.d/mihomo ] || { echo "ОШИБКА: Mixomo не установлен"; return 1; }
	echo "==> Интегрируем WARP.conf в Mihomo"
	grep -qiE '^[[:space:]]*(I2|RandomTrailers|DisableCookies)[[:space:]]*=' "$MIXOMO_WARP_CONF" &&
		echo "   · I2, RandomTrailers и DisableCookies в Mihomo не переносим — с ними WARP в Mihomo не запускается. WARP.conf не меняется"
	local tmp; tmp=$(mktemp)
	awk -v OUT="$tmp" '
	function trim(s){ gsub(/^[ \t\r\n]+|[ \t\r\n]+$/, "", s); return s }
	function lc(s){ return tolower(s) }
	function yaml_quote(s,    o, i, c){ o=""; for(i=1;i<=length(s);i++){ c=substr(s,i,1); if(c=="\\") o=o "\\\\"; else if(c=="\"") o=o "\\\""; else if(c!="\r") o=o c } return "\"" o "\"" }
	function split_endpoint(s,    a,n){ s=trim(s); n=split(s,a,":"); if(n<2){ host=s; port="" } else { port=a[n]; host=a[1]; for(i=2;i<n;i++) host=host ":" a[i] } sub(/^\[/, "", host); sub(/\]$/, "", host) }
	BEGIN{ sec=""; addr4=""; addr6=""; priv=""; pub=""; psk=""; allowed=""; endpoint=""; keep=""; s1=""; s2=""; jc=""; jmin=""; jmax=""; h1=""; h2=""; h3=""; h4=""; i1=""; mtu="" }
	{
		line=$0; sub(/[;#].*$/, "", line); line=trim(line)
		if(line=="") next
		if(line ~ /^\[.*\]$/){ sec=lc(trim(substr(line,2,length(line)-2))); next }
		if(index(line,"=")==0) next
		key=trim(substr(line,1,index(line,"=")-1)); val=trim(substr(line,index(line,"=")+1)); k=lc(key)
		if(sec=="interface"){
			if(k=="address"){ gsub(/,/, " ", val); n=split(val, a, /[ \t]+/); for(i=1;i<=n;i++){ if(a[i] ~ /:/) addr6=a[i]; else addr4=a[i] } }
			else if(k=="privatekey") priv=val
			else if(k=="mtu") mtu=val
			else if(k=="s1") s1=val
			else if(k=="s2") s2=val
			else if(k=="jc") jc=val
			else if(k=="jmin") jmin=val
			else if(k=="jmax") jmax=val
			else if(k=="h1") h1=val
			else if(k=="h2") h2=val
			else if(k=="h3") h3=val
			else if(k=="h4") h4=val
			else if(k=="i1") i1=val
			else if(k ~ /^(s3|s4|i3|i4|i5)$/){ ext[k]=val; hx=1 }
		} else if(sec=="peer"){
			if(k=="publickey") pub=val
			else if(k=="presharedkey") psk=val
			else if(k=="allowedips") { gsub(/[ \t]+/, "", val); allowed=val }
			else if(k=="endpoint") endpoint=val
			else if(k=="persistentkeepalive") keep=val
		}
	}
	END{
		if(priv=="" || pub=="" || endpoint==""){ print "нет обязательных полей" > "/dev/stderr"; exit 2 }
		split_endpoint(endpoint)
		ip=addr4; sub(/\/32$/, "", ip)
		ipv6=addr6; sub(/\/128$/, "", ipv6)
		if(allowed=="") allowed="0.0.0.0/0,::/0"
		n=split(allowed, aip, ",")
		allowed_block=""
		for(i=1;i<=n;i++){ if(aip[i]=="") continue; allowed_block = allowed_block "      - " yaml_quote(aip[i]) "\n" }

		print "mixed-port: 7890" > OUT
		print "allow-lan: false" >> OUT
		print "tcp-concurrent: true" >> OUT
		print "mode: rule" >> OUT
		print "log-level: error" >> OUT
		print "ipv6: false" >> OUT
		print "external-controller: 0.0.0.0:9090" >> OUT
		print "external-ui: ./ui" >> OUT
		print "unified-delay: true" >> OUT
		print "profile:" >> OUT
		print "  store-selected: true" >> OUT
		print "  store-fake-ip: true" >> OUT
		print "" >> OUT
		print "proxy-groups:" >> OUT
		print "  - name: GLOBAL" >> OUT
		print "    type: select" >> OUT
		print "    proxies:" >> OUT
		print "      - WARP" >> OUT
		print "      - DIRECT" >> OUT
		print "" >> OUT
		print "rules:" >> OUT
		print "  - \"MATCH,GLOBAL\"" >> OUT
		print "" >> OUT
		print "proxies:" >> OUT
		print "  - name: WARP" >> OUT
		print "    type: wireguard" >> OUT
		print "    server: " host >> OUT
		if(port!="") print "    port: " port >> OUT
		print "    private-key: " yaml_quote(priv) >> OUT
		print "    udp: true" >> OUT
		if(ip!="") print "    ip: " ip >> OUT
		if(ipv6!="") print "    ipv6: " ipv6 >> OUT
		print "    public-key: " yaml_quote(pub) >> OUT
		if(psk!="") print "    pre-shared-key: " yaml_quote(psk) >> OUT
		print "    allowed-ips:" >> OUT
		printf "%s", allowed_block >> OUT
		if(mtu!="") print "    mtu: " mtu >> OUT
		if(keep!="") print "    persistent-keepalive: " keep >> OUT
		if(s1!="" || s2!="" || jc!="" || jmin!="" || jmax!="" || h1!="" || h2!="" || h3!="" || h4!="" || i1!="" || hx){
			print "    amnezia-wg-option:" >> OUT
			if(s1!="") print "      s1: " s1 >> OUT
			if(s2!="") print "      s2: " s2 >> OUT
			if(jc!="") print "      jc: " jc >> OUT
			if(jmin!="") print "      jmin: " jmin >> OUT
			if(jmax!="") print "      jmax: " jmax >> OUT
			if(h1!="") print "      h1: " h1 >> OUT
			if(h2!="") print "      h2: " h2 >> OUT
			if(h3!="") print "      h3: " h3 >> OUT
			if(h4!="") print "      h4: " h4 >> OUT
			if(i1!="") print "      i1: " yaml_quote(i1) >> OUT
			if("i3" in ext) print "      i3: " yaml_quote(ext["i3"]) >> OUT
			if("i4" in ext) print "      i4: " yaml_quote(ext["i4"]) >> OUT
			if("i5" in ext) print "      i5: " yaml_quote(ext["i5"]) >> OUT
			if("s3" in ext) print "      s3: " ext["s3"] >> OUT
			if("s4" in ext) print "      s4: " ext["s4"] >> OUT
		}
	}' "$MIXOMO_WARP_CONF" 2>"$tmp.err"
	if [ -s "$tmp.err" ]; then
		echo "ОШИБКА: в WARP.conf отсутствуют обязательные поля"
		rm -f "$tmp" "$tmp.err"
		return 1
	fi
	rm -f "$tmp.err"
	cp "$MIHOMO_CONF" "$MIHOMO_CONF.bak" 2>/dev/null
	_mx_secret_ensure "$tmp"
	chmod 600 "$tmp"
	mv -f "$tmp" "$MIHOMO_CONF"
	rm -f "$MIXOMO_SUB_PREV"
	/etc/init.d/mihomo restart >/dev/null 2>&1
	echo "==> Готово, WARP интегрирован в Mihomo"
}

do_steer_warp_own() {
	_st_phase awg
	rm -f "$ST_STOP_FLAG"
	_st_installed || { echo "ОШИБКА: сначала установите Steer"; return 1; }
	[ -n "$(_st_blocker)" ] && { echo "ОШИБКА: ядро steer сейчас настраивает не Zapret Manager"; return 1; }
	if [ -s "$ST_DIR/warp.pending" ]; then mv -f "$ST_DIR/warp.pending" "$ST_WARP_OWN"; fi
	_st_own_restore
	[ -s "$ST_WARP_OWN" ] || { echo "ОШИБКА: вставьте конфиг WARP"; return 1; }
	chmod 600 "$ST_WARP_OWN"
	_st_own_keep
	_ensure_deps
	_st_install_awg || return 1
	_st_phase tunnel
	_rb_say "Свой WARP: один туннель по вашему конфигу"
	if ! _st_warp_own; then
		grep -qv "^$ST_OWN_IF " "$ST_WARP_UP" 2>/dev/null && grep -v "^$ST_OWN_IF " "$ST_WARP_UP" > "$ST_WARP_UP_AUTO"
		_st_owns "net zmwarp" && _rb_say "Автоматические туннели WARP выключаем — они сохранятся, вернуться к ним можно в один клик"
	fi
	_st_ext_leave
	_st_warp_park $(_st_wifs_auto)
	echo own > "$ST_WARP_MODE"
	_st_mode_vars
	_st_awg_loaded || modprobe amneziawg >/dev/null 2>&1
	_st_warp_own_iface "$ST_WARP_CONF" || return 1
	_st_warp_zone
	ubus call network reload >/dev/null 2>&1
	sleep 2
	_st_warp_own_up || return 1
	_st_cron_refresh
	[ "$(cat "$ST_EXIT" 2>/dev/null)" = vpn ] && [ -s "$ST_SUB" ] || echo warp > "$ST_EXIT"
	if [ ! -f "$ST_OFF" ] && _st_work; then
		_st_phase rules
		_st_apply tunnel_ready || return 1
		_st_phase check
		sleep 2
		_st_selfcheck
	fi
	_rb_say "Готово, свой WARP подключён"
}

hosts_auto() {
	local src
	case "$1" in
		on)
			src="$(_hosts_src)"
			case "$src" in eu|us|malw) ;; *) echo '{"error":"сначала замените hosts на один из готовых списков выше"}'; return 1 ;; esac
			mkdir -p "$JOBS_DIR"
			gunzip -c "$HOSTS_BASE" > "$JOBS_DIR/hosts.chk.$$" 2>/dev/null
			if [ "$(_hosts_src "$JOBS_DIR/hosts.chk.$$")" != "$src" ]; then
				{ for b in $HOSTS_BLOCKS; do _hosts_block "$b"; done; } | _hosts_norm > "$JOBS_DIR/hosts.blk.$$"
				awk -v B="$JOBS_DIR/hosts.blk.$$" 'BEGIN { while ((getline l < B) > 0) s[l] = 1; close(B) }
					{ k = $0; gsub(/\r/, "", k); gsub(/[ \t]+/, " ", k); sub(/^ /, "", k); sub(/ $/, "", k) } !(k in s)' "$HOSTS_FILE" > "$JOBS_DIR/hosts.b0.$$"
				_hosts_base_put "$JOBS_DIR/hosts.b0.$$"
				rm -f "$JOBS_DIR/hosts.blk.$$" "$JOBS_DIR/hosts.b0.$$"
			fi
			rm -f "$JOBS_DIR/hosts.chk.$$"
			_hosts_auto_put "$src" "" ""
			_hosts_auto_cron on
			logger -t zapret-manager "Hosts: список $(_hosts_src_name "$src") будет обновляться раз в сутки" ;;
		off)
			rm -f "$HOSTS_AUTO"
			_hosts_auto_cron off ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
	hosts_status
}

hosts_auto_tick() {
	local src cur tmp="$JOBS_DIR/hosts.auto.$$" ex="$JOBS_DIR/hosts.ex.$$" lk="$JOBS_DIR/hosts.auto.lock" r
	src="$(_hosts_auto_get src)"
	case "$src" in eu|us|malw) ;; *) rm -f "$HOSTS_AUTO"; _hosts_auto_cron off; return 0 ;; esac
	mkdir -p "$JOBS_DIR"
	mkdir "$lk" 2>/dev/null || { _zm_aged "$lk" 10 && rmdir "$lk" 2>/dev/null; return 0; }
	cur="$(_hosts_src)"
	if [ "$cur" != "$src" ]; then
		rm -f "$HOSTS_AUTO" "$HOSTS_BASE"; _hosts_auto_cron off; rmdir "$lk"
		logger -t zapret-manager "Hosts: список $(_hosts_src_name "$src") в /etc/hosts заменён вручную — ежедневное обновление выключено"
		return 0
	fi
	_hosts_on_init
	[ -s "$HOSTS_BASE" ] && _hosts_extras > "$ex"
	r="$(ZM_HOSTS_NOAPPLY="$tmp" hosts_replace_geohide "$src" 2>/dev/null)"
	case "$r" in
		*'"ok":true'*) ;;
		*)
			_hosts_auto_put "$src" "" "$(printf '%s' "$r" | sed -n 's/.*"error":"\([^"]*\)".*/\1/p' | head -c 200)"
			rm -f "$tmp" "$ex"; rmdir "$lk"
			logger -t zapret-manager "Hosts: свежий список $(_hosts_src_name "$src") не скачался — остался прежний"
			return 1 ;;
	esac
	_hosts_base_put "$tmp"
	_hosts_overlay "$tmp"
	if [ -s "$ex" ]; then
		[ -n "$(tail -c 1 "$tmp" 2>/dev/null)" ] && echo >> "$tmp"
		cat "$ex" >> "$tmp"
	fi
	if cmp -s "$tmp" "$HOSTS_FILE"; then
		rm -f "$tmp"
	elif cat "$tmp" > "$HOSTS_FILE" 2>/dev/null; then
		rm -f "$tmp"
		_hosts_dns_reload
		logger -t zapret-manager "Hosts: список $(_hosts_src_name "$src") обновлён$([ -s "$HOSTS_ON" ] && echo ", отмеченные сервисы ($(echo $(cat "$HOSTS_ON") | sed 's/ /, /g')) добавлены поверх")$([ -s "$ex" ] && echo ", ваши записи сохранены")"
	else
		rm -f "$tmp" "$ex"; rmdir "$lk"
		_hosts_auto_put "$src" "" "не удалось записать /etc/hosts — мало места на роутере"
		return 1
	fi
	rm -f "$ex"; rmdir "$lk"
	_hosts_auto_put "$src" "$(date +%s)" ""
	return 0
}

hosts_file_get() {
	local sz n
	[ -f "$HOSTS_FILE" ] || { echo '{"error":"файл hosts не найден"}'; return 1; }
	sz="$(wc -c < "$HOSTS_FILE" | tr -d ' ')"
	if [ "${sz:-0}" -gt "$HOSTS_EDIT_MAX" ]; then
		n="$(wc -l < "$HOSTS_FILE" | tr -d ' ')"
		printf '{"too_big":true,"size":%s,"lines":%s}\n' "$sz" "${n:-0}"
		return 0
	fi
	printf '{"content":"%s"}\n' "$(esc_ml "$(cat "$HOSTS_FILE")")"
}

hosts_file_set() {
	local content="$1"
	[ -n "$content" ] || { echo '{"error":"пустой файл — сохранение отменено"}'; return 1; }
	[ "$(printf '%s' "$content" | wc -c)" -gt "$HOSTS_EDIT_MAX" ] && { echo '{"error":"файл слишком большой для редактора"}'; return 1; }
	cp "$HOSTS_FILE" "$HOSTS_FILE.zm-bak" 2>/dev/null
	printf '%s\n' "$content" | tr -d '\r' > "$HOSTS_FILE.zmtmp" 2>/dev/null
	if ! [ -s "$HOSTS_FILE.zmtmp" ] || ! cat "$HOSTS_FILE.zmtmp" > "$HOSTS_FILE" 2>/dev/null || ! cmp -s "$HOSTS_FILE.zmtmp" "$HOSTS_FILE"; then
		rm -f "$HOSTS_FILE.zmtmp"
		[ -s "$HOSTS_FILE.zm-bak" ] && cat "$HOSTS_FILE.zm-bak" > "$HOSTS_FILE" 2>/dev/null
		echo '{"error":"не удалось записать /etc/hosts — проверьте свободное место на роутере"}'; return 1
	fi
	rm -f "$HOSTS_FILE.zmtmp"
	_hosts_on_sync
	_hosts_dns_reload
	printf '{"ok":true}\n'
}

hosts_replace_geohide() {
	local region="$1" url tmp kept
	case "$region" in
		eu) url="${GH_RAW}/Internet-Helper/GeoHideDNS/refs/heads/main/hosts/eu/hosts" ;;
		us) url="${GH_RAW}/Internet-Helper/GeoHideDNS/refs/heads/main/hosts/us/hosts" ;;
		malw) url="${GH_RAW}/ImMALWARE/dns.malw.link/refs/heads/master/hosts" ;;
		*) echo '{"error":"неизвестный регион"}'; return 1 ;;
	esac
	tmp="$JOBS_DIR/geohide_hosts.tmp"
	_zm_fetch "$url" "$tmp" 60
	if [ ! -s "$tmp" ]; then
		rm -f "$tmp"
		printf '{"error":"%s"}\n' "$([ "$region" = malw ] && echo "не удалось скачать hosts dns.malw.link" || echo "не удалось скачать GeoHide hosts")"
		return 1
	fi
	if [ "$(grep -cE '^[[:space:]]*[0-9a-fA-F.:]+[[:space:]]+[A-Za-z0-9]' "$tmp")" -lt 20 ]; then
		rm -f "$tmp"
		echo '{"error":"скачался не файл hosts — попробуйте ещё раз позже"}'
		return 1
	fi
	if [ -n "$ZM_HOSTS_NOAPPLY" ]; then
		mv -f "$tmp" "$ZM_HOSTS_NOAPPLY"
		printf '{"ok":true,"region":"%s"}\n' "$region"
		return 0
	fi
	_hosts_on_init
	_hosts_base_put "$tmp"
	_hosts_overlay "$tmp"
	if ! mv "$tmp" "$HOSTS_FILE" 2>/dev/null; then
		rm -f "$tmp"
		echo '{"error":"не удалось записать /etc/hosts — проверьте свободное место на роутере"}'
		return 1
	fi
	_hosts_dns_reload
	[ -s "$HOSTS_AUTO" ] && _hosts_auto_put "$region" "$(date +%s)" ""
	kept="$(grep -c . "$HOSTS_ON" 2>/dev/null)"
	printf '{"ok":true,"region":"%s","kept":%s}\n' "$region" "${kept:-0}"
}

hosts_reset() {
	[ -f "$HOSTS_AUTO" ] && { rm -f "$HOSTS_AUTO"; _hosts_auto_cron off; }
	rm -f "$HOSTS_BASE"; mkdir -p "$ZM_STATE_DIR"; : > "$HOSTS_ON"
	printf '%s\n' "127.0.0.1	localhost" "" "::1	localhost ip6-localhost ip6-loopback" "ff02::1 ip6-allnodes" "ff02::2 ip6-allrouters" > "$HOSTS_FILE"
	_hosts_dns_reload
	printf '{"ok":true}\n'
}

hosts_toggle() {
	local block="$1" content enabled src h="$JOBS_DIR/hosts.tgl.$$"
	content="$(_hosts_block "$block")" || { echo '{"error":"неизвестный блок"}'; return 1; }
	_hosts_on_init
	enabled="$(_hosts_block_status "$block")"
	src="$(_hosts_src)"
	mkdir -p "$JOBS_DIR"
	printf '%s\n' "$content" | _hosts_hostnames > "$h"
	if [ "$enabled" = "true" ]; then
		printf '%s\n' "$content" | _hosts_drop_lines
		_hosts_on_set "$block" off
		if [ -n "$src" ] && [ "$(_hosts_base_src)" = "$src" ]; then
			gunzip -c "$HOSTS_BASE" 2>/dev/null | awk -v H="$h" 'BEGIN { while ((getline l < H) > 0) if (l != "") hn[l] = 1; close(H) }
				{ c = $0; sub(/\r$/, "", c); if (c ~ /^[ \t]*#/) next; sub(/#.*/, "", c); sub(/^[ \t]+/, "", c)
				  m = split(c, a, /[ \t]+/); for (i = 2; i <= m; i++) if (tolower(a[i]) in hn) { print; next } }' > "$h.back"
			if [ -s "$h.back" ]; then
				cp -f "$h.back" "$h.part"
				_hosts_unclaim "$h.part" "$h"
				[ -s "$h.part" ] && _hosts_drop_lines < "$h.part"
				_hosts_add_lines < "$h.back"
			fi
			rm -f "$h.back" "$h.part"
		fi
	else
		_hosts_on_set "$block" on
		[ -n "$src" ] && _hosts_unclaim "$HOSTS_FILE" "$h"
		printf '%s\n' "$content" | _hosts_add_lines
	fi
	rm -f "$h"
	_hosts_dns_reload
	printf '{"ok":true,"block":"%s","enabled":%s}\n' "$(esc "$block")" "$([ "$enabled" = "true" ] && echo false || echo true)"
}

mixomo_warp_config_set() {
	local content="$1"
	[ -n "$content" ] || { echo '{"error":"пустая конфигурация — сохранение отменено"}'; return 1; }
	echo "$content" | grep -q '^\[Interface\]' || { echo '{"error":"файл должен начинаться с секции [Interface]"}'; return 1; }
	echo "$content" | grep -q '^\[Peer\]' || { echo '{"error":"в файле нет секции [Peer]"}'; return 1; }
	echo "$content" | grep -q '^PrivateKey' || { echo '{"error":"в секции [Interface] нет PrivateKey"}'; return 1; }
	echo "$content" | grep -q '^PublicKey' || { echo '{"error":"в секции [Peer] нет PublicKey"}'; return 1; }
	mkdir -p "$(dirname "$MIXOMO_WARP_CONF")"
	printf '%s' "$content" > "$MIXOMO_WARP_CONF"
	chmod 600 "$MIXOMO_WARP_CONF"
	printf '{"ok":true}\n'
}

mixomo_warp_integrate_action() {
	job_start mixomo_warp_integrate do_mixomo_warp_integrate
}

mixomo_warp_status() {
	local exists="false" content=""
	if [ -s "$MIXOMO_WARP_CONF" ]; then
		exists="true"
		content=$(cat "$MIXOMO_WARP_CONF")
	fi
	printf '{"exists":%s,"content":"%s"}\n' "$exists" "$(esc_ml "$content")"
}

stl_apply() {
	local new="$STL_SPEC.zm.$$" prev="$STL_TMP/spec.prev" err w=0 i=0 ck=0 fx="" again="" plg="" x
	local ZM_STL_NOV6T="" ZM_STL_NOCTTL="" ZM_STL_NODNS="" ZM_STL_NOFO="" ZM_STL_NOTQ=""
	STL_DUP_SAID=""
	mkdir -p "$STL_ETC" "$STL_TMP"
	rm -f "$ST_DIR/nofam"
	_stl_spec "$1" > "$new" || { rm -f "$new"; echo "ОШИБКА: в настройке нет ни одного списка"; return 1; }
	_stl_say "Проверяем правила: $(grep -o '"out":' "$new" | wc -l | tr -d ' ')"
	err="$(_stl_check "$new")" && ck=1
	while [ "$ck" = 0 ] && [ "$i" -lt 8 ]; do
		i=$((i + 1))
		x=""; [ -z "$plg" ] && stl_v2 && ! _st_ver_lt "$(stl_version)" 2.1.0 &&
			x="$(printf '%s\n' "$err" | sed -n 's/.*нужен плагин \([a-z0-9_-]*\).*/\1/p; s/.*требует пакет steer-\([a-z0-9_-]*\).*/\1/p' | grep -E '^(vless|hysteria2|proxy)$' | awk '!s[$0]++' | tr '\n' ' ')"
		if [ -n "$(echo $x)" ]; then
			plg=1
			_stl_say "Ядро steer не нашло плагины протоколов: $(echo $x | sed 's/ /, /g') — ставим"
			_stl_plug_add $x >&2
		elif [ -z "$ZM_STL_NOV6T" ] && grep -q '"kind":"tunnel"' "$new" && printf '%s' "$err" | grep -qi 'ipv6'; then ZM_STL_NOV6T=1
		elif [ -z "$ZM_STL_NOCTTL" ] && grep -q '"cache_ttl"' "$new" && printf '%s' "$err" | grep -q 'cache_ttl'; then ZM_STL_NOCTTL=1; fx="$fx ct"
		elif [ -z "$ZM_STL_NODNS" ] && grep -q '"zm_tun' "$new" && printf '%s' "$err" | grep -q 'zm_tun'; then ZM_STL_NODNS=1; fx="$fx dns"
		elif [ -z "$ZM_STL_NOTQ" ] && grep -qE '"(torrent|quic)":' "$new" && printf '%s' "$err" | grep -qiE 'torrent|quic'; then ZM_STL_NOTQ=1; fx="$fx tq"
		elif [ -z "$ZM_STL_NOFO" ] && grep -q '"zm_fo[0-9]' "$new" && printf '%s' "$err" | grep -qE 'zm_fo|group|members|групп'; then ZM_STL_NOFO=1; fx="$fx fo"
		elif [ -z "$again" ]; then again=1; sleep 1; err="$(_stl_check "$new")" && ck=1; continue
		elif [ -z "$ZM_STL_NOTQ" ] && grep -qE '"(torrent|quic)":' "$new"; then ZM_STL_NOTQ=1; fx="$fx tq"
		elif [ -z "$ZM_STL_NOFO" ] && grep -q '"zm_fo[0-9]' "$new"; then ZM_STL_NOFO=1; fx="$fx fo"
		elif [ -z "$ZM_STL_NOCTTL" ] && grep -q '"cache_ttl"' "$new"; then ZM_STL_NOCTTL=1; fx="$fx ct"
		elif [ -z "$ZM_STL_NODNS" ] && grep -q '"zm_tun' "$new"; then ZM_STL_NODNS=1; fx="$fx dns"
		else break; fi
		_stl_spec "$1" > "$new" || break
		err="$(_stl_check "$new")" && ck=1
	done
	if [ "$ck" = 0 ]; then
		rm -f "$new"
		echo "ОШИБКА: ядро steer отвергло настройку"
		printf '%s\n' "$err" | tail -n 5 | _st_outs_text
		return 1
	fi
	case "$fx" in *ct*) _stl_say "Ядро steer не знает настройку «Помнить адреса сервисов» — правила применены без неё. $(_stl_upd_hint)" ;; esac
	case "$fx" in *dns*) _stl_say "Ядро steer не умеет DNS через туннель — правила применены без него. $(_stl_upd_hint)" ;; esac
	case "$fx" in *tq*) _stl_say "Ядро steer не знает настройки «Торренты» и «QUIC» — правила применены без них. $(_stl_upd_hint 2.1.0)" ;; esac
	case "$fx" in *fo*) _stl_say "Ядро steer не приняло запасные пути секций — сервис, выбранный в нескольких секциях, идёт только через первую. $(_stl_upd_hint)" ;; esac
	[ "$(stl_spec_whose)" = none ] && [ -s "$STL_SPEC" ] && [ ! -f "$STL_KEEP" ] && cp -f "$STL_SPEC" "$STL_KEEP"
	rm -f "$prev"; [ -s "$STL_SPEC" ] && cp -f "$STL_SPEC" "$prev"
	mv -f "$new" "$STL_SPEC"
	"$STL_INIT" enable >/dev/null 2>&1
	if stl_running; then
		if ! err="$(_stl_t 300 steer apply 2>&1 >/dev/null)"; then
			if [ -s "$prev" ]; then mv -f "$prev" "$STL_SPEC"; else rm -f "$STL_SPEC"; fi
			echo "ОШИБКА: ядро steer не применило правила — остались прежние"
			printf '%s\n' "$err" | tail -n 5 | _st_outs_text
			return 1
		fi
		rm -f "$prev"
		_stl_say "Правила Steer применены — ядро тронуло только изменившееся"
		return 0
	fi
	rm -f "$prev"
	"$STL_INIT" start >/dev/null 2>&1
	while [ "$w" -lt 10 ] && ! stl_running; do sleep 1; w=$((w + 1)); done
	stl_running || { echo "ОШИБКА: служба steer не запустилась — загляните в системный журнал"; return 1; }
	_stl_say "Правила Steer применены"
}

stl_diag_lines() {
	local f="$STL_TMP/stl-diag.json"
	mkdir -p "$STL_TMP"
	_stl_t 30 steer diag > "$f" 2>/dev/null
	_stl_diag_tsv "$f"
	rm -f "$f"
}

stl_engine_install() {
	local ver="$1" arch m p n f mods="" pkgs files="" old="" back="" legacy="" keep="$STL_TMP/spec.keep" was_on="" rc p21="" plug="" STL_CORE_ARCH=""
	shift
	_stl_ver_ok "$ver" || { echo "ОШИБКА: версия ядра steer $ver — нужна 2.0.0 или новее"; return 1; }
	arch="$(_rb_arch)"
	[ -n "$arch" ] || { echo "ОШИБКА: не удалось определить архитектуру роутера"; return 1; }
	for m in "$@"; do case "$m" in vpn) mods="$mods vless" ;; hy2) mods="$mods hysteria2" ;; proxy) mods="$mods proxy" ;; esac; done
	if stl_present && ! stl_v2; then
		for n in steer steer-extended libsteer libsteer-wolfssl; do _pkg_is_installed "$n" && legacy="$legacy $n"; done
		case " $legacy " in *" steer-extended "*) mods="$mods vless" ;; esac
	fi
	mods="$(for m in $mods $(_stl_mods_present); do echo "$m"; done | awk '!s[$0]++' | tr '\n' ' ')"
	_st_ver_lt "$ver" 2.1.0 || { p21=1; for m in $mods; do [ "$m" = tgws ] || plug="$plug $m"; done; }
	pkgs="steer-core$([ -n "$p21" ] || for m in $mods; do printf ' steer-%s' "$m"; done)"
	[ -z "$p21" ] && stl_v2 && _pkg_is_installed steer-extended && pkgs="$pkgs steer-extended"
	if [ -n "$STL_MODS_ONLY" ] && stl_v2 && [ "$(stl_version)" = "$ver" ] && [ -n "$p21" ]; then
		STL_NEW=""; STL_PKGS=""
		_stl_plug_add $plug
		return
	fi
	if [ -n "$STL_MODS_ONLY" ] && stl_v2 && [ "$(stl_version)" = "$ver" ]; then
		pkgs="$(for p in $pkgs; do _pkg_is_installed "$p" || printf '%s ' "$p"; done)"
		pkgs="$(echo $pkgs)"
		[ -n "$pkgs" ] || { _stl_say "Нужные модули ядра steer уже стоят"; STL_NEW=""; STL_PKGS=""; return 0; }
	fi
	STL_NEW=""; STL_PKGS="$pkgs"
	for p in $pkgs; do _pkg_is_installed "$p" || STL_NEW="$STL_NEW $p"; done
	mkdir -p "$STL_TMP"
	local pa a
	for p in $pkgs; do
		pa=""
		for a in $(_zm_arch_alts "$arch"); do
			f="$STL_TMP/$p-$ver-1_$a.$RAZ"
			_stl_fetch "$ver" "$p-$ver-1_$a.$RAZ" "$f" && { pa="$a"; break; }
		done
		[ -n "$pa" ] || { rm -f $files; echo "ОШИБКА: не скачался пакет $p $ver для $arch"; return 1; }
		if [ "$pa" != "$arch" ]; then
			_stl_say "Сборки $p для $arch нет — берём совместимую $pa"
			_zm_arch_accept "$pa"
		fi
		[ "$p" = steer-core ] && STL_CORE_ARCH="$pa"
		files="$files $f"
	done
	local needk freek
	needk=$(( $(cat $files 2>/dev/null | wc -c) * 3 / 1024 ))
	freek="$(df -k /usr 2>/dev/null | awk 'END { print $(NF-2) }')"
	case "$freek" in ''|*[!0-9]*) freek="" ;; esac
	if [ -n "$freek" ] && [ "$freek" -lt "$needk" ]; then
		rm -f $files
		echo "ОШИБКА: на роутере мало места для ядра steer $ver — нужно около $(( needk / 1024 + 1 )) МБ, свободно $(( freek / 1024 )) МБ. Ядро не трогали: освободите место и повторите"
		return 1
	fi
	stl_enabled && was_on=1
	case " $pkgs " in *" steer-core "*) _stl_say "Ставим ядро steer $ver: $(echo $pkgs | sed 's/ /, /g')" ;; *) _stl_say "Ставим к ядру steer $ver: $(echo $pkgs | sed 's/ /, /g')" ;; esac
	$UPDATE >&2
	[ -s "$STL_SPEC" ] && cp -f "$STL_SPEC" "$keep"
	[ -n "$p21" ] && _stl_arch_fix
	local seedspec=""
	if [ -n "$p21" ] && [ ! -s "$STL_SPEC" ] && [ ! -s "$STL_YAML" ]; then
		mkdir -p "$STL_ETC"
		printf '%s\n' "$STL_SEED_SPEC" > "$STL_SPEC" && seedspec=1
	fi
	if [ -n "$STL_REINSTALL" ] && [ -z "$legacy" ]; then
		"$STL_INIT" stop >/dev/null 2>&1
		if [ "$PKG" = apk ]; then
			n=""; for p in $pkgs; do _pkg_is_installed "$p" && n="$n $p"; done
			[ -n "$n" ] && $DELETE $n >&2
			$INSTALL $files >&2; rc=$?
			[ "$rc" = 0 ] || { $INSTALL $files >&2; rc=$?; }
		else
			$INSTALL --force-reinstall $files >&2; rc=$?
		fi
	elif [ "$PKG" = apk ]; then
		_stl_world_unban
		if [ -n "$p21" ]; then
			# Ядро 2.1+ само «содержит» steer, steer-extended и libsteer: запрет «!имя» запретил бы и его.
			# Прежние пакеты убираем из world — apk снимет их в той же операции, что ставит новое ядро
			cp -f /etc/apk/world "$STL_TMP/world.zm" 2>/dev/null
			[ -n "$legacy" ] && _stl_world_drop $legacy
			old="$(awk -F'><' 'NF > 1 && $1 ~ /^steer-(vless|hysteria2|proxy|xsteer|obfs|warpbox|tgws|extended)$/ { print $1 }' /etc/apk/world 2>/dev/null)"
			$INSTALL $files $old >&2; rc=$?
			[ "$rc" = 0 ] || { [ -s "$STL_TMP/world.zm" ] && cat "$STL_TMP/world.zm" > /etc/apk/world; }
			rm -f "$STL_TMP/world.zm"
		else
			for n in $legacy; do if [ "$n" = steer ]; then apk add steer >/dev/null 2>&1; else old="$old !$n"; fi; done
			$INSTALL $files $old >&2; rc=$?
			[ "$rc" = 0 ] && for n in $legacy; do apk del "$n" >/dev/null 2>&1; done
			_stl_world_unban
		fi
	else
		if [ -n "$legacy" ]; then
			old="$(stl_version)"; back=""
			for n in $legacy; do
				f="$STL_TMP/$n-$old-1_$arch.$RAZ"
				_pkg_is_installed "$n" && case "$n" in steer|steer-extended) _stl_fetch "$old" "$n-$old-1_$arch.$RAZ" "$f" && back="$back $f" ;; esac
			done
			if [ -z "$back" ]; then
				rm -f $files "$keep"
				echo "ОШИБКА: не скачался пакет прежнего ядра steer $old для возврата — прежнее ядро оставлено"
				return 1
			fi
			_stl_say "Снимаем прежнее ядро steer $old — оно мешает новому"
			"$STL_INIT" stop >/dev/null 2>&1
			$DELETE $legacy >&2
		fi
		$INSTALL $files >&2; rc=$?
		if [ "$rc" != 0 ] && [ -n "$legacy" ]; then
			_stl_say "Новое ядро не встало — возвращаем прежнее ядро steer $old"
			$INSTALL $back >&2
		fi
		[ -n "$legacy" ] && rm -f $back
	fi
	rm -f $files
	[ -s "$keep" ] && [ ! -s "$STL_SPEC" ] && { mkdir -p "$STL_ETC"; cp -f "$keep" "$STL_SPEC"; }
	rm -f "$keep"
	[ -n "$seedspec" ] && [ "$(cat "$STL_SPEC" 2>/dev/null)" = "$STL_SEED_SPEC" ] && rm -f "$STL_SPEC"
	[ "$rc" = 0 ] && [ -n "$p21" ] && [ -n "$STL_CORE_ARCH" ] && { mkdir -p "$ST_DIR"; echo "$STL_CORE_ARCH" > "$ST_DIR/core.arch"; }
	if [ "$rc" != 0 ] || ! stl_v2; then
		[ -n "$legacy" ] && ! stl_present && echo "!! Прежнее ядро steer снято, а новое не встало — нажмите установку ещё раз, когда появится интернет"
		[ -n "$was_on" ] && stl_present && stl_restart >/dev/null 2>&1
		echo "ОШИБКА: ядро steer $ver не установилось"
		return 1
	fi
	if [ -n "$p21" ] && [ -z "$seedspec" ] && { [ -s "$STL_SPEC" ] || [ -s "$STL_YAML" ]; }; then
		_stl_say "Ставим плагины ядра steer по правилам"
		_stl_plug_run migrate 2>&1 | _zm_pkg_fmt >&2
	fi
	[ -n "$plug" ] && { _stl_plug_add $plug || rc=1; }
	if [ -n "$was_on" ]; then stl_restart >/dev/null 2>&1; else stl_stop; fi
	[ "$rc" = 0 ] || return 1
	STL_VER_C=""
	_stl_say "Ядро steer $(stl_version) установлено$( [ -n "$mods" ] && printf ', модули: %s' "$(echo $mods | sed 's/ /, /g')")"
	return 0
}

# Убирает из /etc/apk/world запреты «!steer…», которые оставляли прежние установки: с ними новое ядро не ставится

stl_spec_restore() { if [ -s "$STL_KEEP" ]; then mv -f "$STL_KEEP" "$STL_SPEC"; else rm -f "$STL_SPEC"; fi; }

stl_sub_nodes() {
	local m
	{ for m in vless hysteria2 proxy; do
		_stl_mod_x "$m" || continue
		printf '@%s\t' "$m"; _stl_t 30 steer "$m-nodes" "$1" $(_stl_insec_arg "$1") 2>/dev/null | tr '\n\t' '  '; echo
	done; } | LC_ALL=C awk -v MAP="$1.map" -v META="$3" '
function junesc(s,    o, i, n, c, d) {
	o = ""; n = length(s)
	for (i = 1; i <= n; i++) {
		c = substr(s, i, 1)
		if (c == "\\" && i < n) {
			d = substr(s, ++i, 1)
			if (d == "u") { i += 4; o = o " " }
			else if (d == "n" || d == "t" || d == "r" || d == "b" || d == "f") o = o " "
			else o = o d
		} else o = o c
	}
	gsub(/\t/, " ", o)
	return o
}
function sfield(ch, k,    r) {
	if (match(ch, "\"" k "\":\"([^\"\\\\]|\\\\.)*\"")) { r = substr(ch, RSTART + length(k) + 4, RLENGTH - length(k) - 5); return junesc(r) }
	return ""
}
function nfield(ch, k,    r) {
	if (match(ch, "\"" k "\":-?[0-9]+")) { r = substr(ch, RSTART + length(k) + 3, RLENGTH - length(k) - 3); return r + 0 }
	return -1
}
function bfield(ch, k) { return (index(ch, "\"" k "\":true") ? 1 : 0) }
BEGIN {
	FS = "\t"
	if (MAP != "") while ((getline l < MAP) > 0) { split(l, a, "\t"); key = a[2] "|" a[3] "|" a[4]; Q[key] = Q[key] (Q[key] == "" ? "" : " ") a[1] }
	seq = 0; usable = 0; skipped = 0; reasons = ""
}
{
	mod = substr($1, 2); j = $0; sub(/^[^\t]*\t/, "", j)
	if (match(j, /"usable":[0-9]+/)) usable += substr(j, RSTART + 9, RLENGTH - 9)
	if (match(j, /"skipped":[0-9]+/)) skipped += substr(j, RSTART + 10, RLENGTH - 10)
	r = j
	while (match(r, /"reason":"([^"\\]|\\.)*"/)) {
		x = substr(r, RSTART + 10, RLENGTH - 11); r = substr(r, RSTART + RLENGTH)
		if (!(x in RS_)) { RS_[x] = 1; reasons = reasons (reasons == "" ? "" : ",") "{\"reason\":\"" x "\"}" }
	}
	p = index(j, "\"nodes\":["); if (!p) next
	j = substr(j, p + 9)
	q = index(j, "],\"skipped_reasons\""); if (q) j = substr(j, 1, q - 1)
	n = split(j, C, /\{"index":/)
	for (i = 2; i <= n; i++) {
		ch = "{\"index\":" C[i]
		fidx = nfield(ch, "index"); name = sfield(ch, "name"); host = tolower(sfield(ch, "host")); port = nfield(ch, "port")
		ty = sfield(ch, "type"); sec = sfield(ch, "security"); vis = bfield(ch, "vision")
		if (mod == "vless") { proto = "vless"; tr = ty }
		else if (mod == "hysteria2") { proto = "hysteria2"; tr = "quic" }
		else { proto = ty; tr = sfield(ch, "transport") }
		if (proto == "") continue
		pidx = (mod == "proxy") ? PC[proto]++ : fidx
		key = proto "|" host "|" port; pos = ""
		if (Q[key] != "") { pos = Q[key]; sub(/ .*/, "", pos); if (index(Q[key], " ")) sub(/^[^ ]* /, "", Q[key]); else Q[key] = "" }
		if (pos == "") pos = 100000 + seq
		seq++
		if (name == "") name = host ":" port
		printf "%d\t%s\t%d\t%d\t%s\t%s\t%s\t%d\n", pos, proto, pidx, fidx, name, tr, sec, vis
	}
}
END { if (META != "") printf "usable=%d\nskipped=%d\nreasons=[%s]\n", usable, skipped, reasons > META }
' | sort -n -k1,1 | LC_ALL=C awk -F'\t' 'BEGIN { OFS = "\t" }
		{ k = $5; c = ++D[k]; if (c > 1) k = k " (" c ")"; while (k in U) { c++; k = $5 " (" c ")" } U[k] = 1
		  print NR - 1, $2, $3, $4, k, $6, $7, $8, $1 }' > "$2"
}

stl_sub_norm() {
	rm -f "$2" "$2.map"
	LC_ALL=C awk -v OUT="$2" -v MAP="$2.map" '
BEGIN { A = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"; for (i = 1; i <= 64; i++) B64[substr(A, i, 1)] = i - 1 }
function b64d(s,    o, ch, i, n, v, w, x, y, k) {
	gsub(/[ \t\r\n=]/, "", s); gsub(/-/, "+", s); gsub(/_/, "/", s)
	if (s ~ /[^A-Za-z0-9+\/]/) return ""
	o = ""; ch = ""; k = 0; n = length(s)
	for (i = 1; i + 3 <= n; i += 4) {
		v = B64[substr(s, i, 1)] * 262144 + B64[substr(s, i + 1, 1)] * 4096 + B64[substr(s, i + 2, 1)] * 64 + B64[substr(s, i + 3, 1)]
		w = int(v / 65536); x = int(v / 256) % 256; y = v % 256
		ch = ch sprintf("%c%c%c", w, x, y)
		if (++k >= 128) { o = o ch; ch = ""; k = 0 }
	}
	if (n - i == 2) { v = B64[substr(s, i, 1)] * 262144 + B64[substr(s, i + 1, 1)] * 4096 + B64[substr(s, i + 2, 1)] * 64; ch = ch sprintf("%c%c", int(v / 65536), int(v / 256) % 256) }
	else if (n - i == 1) { v = B64[substr(s, i, 1)] * 262144 + B64[substr(s, i + 1, 1)] * 4096; ch = ch sprintf("%c", int(v / 65536)) }
	return o ch
}
function hexv(h) { return index("0123456789abcdef", tolower(h)) - 1 }
function frag(s,    o, i, n, a, b, v) {
	o = ""; n = length(s)
	for (i = 1; i <= n; i++) {
		if (substr(s, i, 1) == "%" && i + 2 <= n) {
			a = hexv(substr(s, i + 1, 1)); b = hexv(substr(s, i + 2, 1))
			if (a >= 8 && b >= 0) { v = a * 16 + b; o = o sprintf("%c", v); i += 2; continue }
		}
		o = o substr(s, i, 1)
	}
	return o
}
function fam(sc) {
	sc = tolower(sc)
	if (sc == "vless") return "vless"
	if (sc == "hysteria2" || sc == "hy2") return "hysteria2"
	if (sc == "trojan") return "trojan"
	if (sc == "ss") return "shadowsocks"
	if (sc ~ /^socks/) return "socks"
	if (sc == "http" || sc == "https") return "http"
	if (sc == "vmess") return "vmess"
	return ""
}
function jfield(j, k,    r) {
	if (match(j, "\"" k "\"[ \t]*:[ \t]*\"[^\"]*\"")) { r = substr(j, RSTART, RLENGTH); sub(/^"[^"]*"[ \t]*:[ \t]*"/, "", r); sub(/"$/, "", r); return r }
	if (match(j, "\"" k "\"[ \t]*:[ \t]*[0-9]+")) { r = substr(j, RSTART, RLENGTH); sub(/^.*:[ \t]*/, "", r); return r }
	return ""
}
function hostport(l, f,    r, j, t) {
	H = ""; P = ""
	r = l; sub(/^[A-Za-z0-9]+:\/\//, "", r)
	if (f == "vmess") { sub(/#.*/, "", r); j = b64d(r); H = jfield(j, "add"); P = jfield(j, "port"); return }
	if (f == "shadowsocks") { t = r; sub(/[?#].*$/, "", t); if (index(t, "@") == 0) { j = b64d(t); if (index(j, "@")) { sub(/^.*@/, "", j); r = j } } }
	sub(/#.*$/, "", r)
	t = index(r, "@"); j = index(t ? substr(r, t + 1) : r, "?")
	if (j) r = substr(r, 1, t + j - 1)
	sub(/^.*@/, "", r)
	sub(/[\/?].*$/, "", r)
	if (r ~ /^\[/) { H = r; sub(/\].*$/, "", H); sub(/^\[/, "", H); P = r; sub(/^.*\]:?/, "", P); return }
	H = r; sub(/:.*$/, "", H); P = r; if (index(P, ":")) sub(/^[^:]*:/, "", P); else P = ""
}
{ buf = buf $0 "\n" }
END {
	gsub(/\r/, "", buf)
	if (substr(buf, 1, 3) == "\357\273\277") buf = substr(buf, 4)
	t = buf; sub(/^[ \t\n]+/, "", t)
	if (t ~ /^[\{\[]/) { printf "%s", buf > OUT; printf "" > MAP; exit 0 }
	if (("\n" buf) ~ /\nproxies:[ \t]*(\[|\n)/) { printf "%s", buf > OUT; printf "" > MAP; exit 0 }
	if (!index(buf, "://")) { d = b64d(buf); if (index(d, "://")) buf = d }
	gsub(/\r/, "", buf)
	n = split(buf, L, "\n"); ln = 0
	for (i = 1; i <= n; i++) {
		l = L[i]; gsub(/^[ \t]+|[ \t]+$/, "", l)
		if (l == "") continue
		if (match(l, /^[A-Za-z0-9]+:\/\//)) {
			sc = substr(l, 1, RLENGTH - 3)
			h = index(l, "#")
			if (h) l = substr(l, 1, h) frag(substr(l, h + 1))
			gsub(/[\t]/, " ", l)
			print l > OUT; ln++
			f = fam(sc)
			if (f != "") { hostport(l, f); printf "%d\t%s\t%s\t%s\n", ln, f, tolower(H), P > MAP }
		} else { print l > OUT; ln++ }
	}
	printf "" > MAP
}
' "$1" 2>/dev/null
	[ -s "$2" ]
}

zm_pages() {
	local a="$1" v="$2" id off="" lk need="" was gone=""
	case "$a" in
		status) _job_running pages || _zpg_enforce; _zpg_status ;;
		set)
			_job_running pages && { echo '{"error":"страницы ещё докачиваются — дождитесь окончания"}'; return 1; }
			for id in $(printf '%s' "$v" | tr ',' ' '); do
				_zpg_known "$id" || { echo '{"error":"неизвестная страница"}'; return 1; }
				if lk="$(_zpg_lock "$id")"; then printf '{"error":"%s"}\n' "$(esc "«$(_zpg_f "$id" 2)» убрать нельзя: $lk")"; return 1; fi
				case " $off " in *" $id "*) ;; *) off="$off $id" ;; esac
			done
			off="${off# }"
			was="$(_zpg_offlist)"
			for id in $off; do case " $was " in *" $id "*) ;; *) _zpg_have "$id" && gone=1 ;; esac; done
			mkdir -p "$ZM_STATE_DIR"
			if [ -n "$off" ]; then printf '%s\n' "$off" > "$ZPG_OFF"; else rm -f "$ZPG_OFF"; fi
			_zpg_enforce
			if [ -n "$gone" ]; then ( zm_cleanup after ) >/dev/null 2>&1 </dev/null & fi
			for id in $ZPG_IDS; do _zpg_is_off "$id" || _zpg_have "$id" || need=1; done
			if [ -n "$need" ]; then
				if id="$(_zm_busy_job)"; then printf '{"error":"%s"}\n' "$(esc "Выбор сохранён, но докачать страницы сейчас нельзя: идёт операция «$id». Нажмите «Применить» ещё раз, когда она закончится")"; return 1; fi
				job_start pages do_zpg_restore >/dev/null
			fi
			_zpg_status ;;
		*) echo '{"error":"неизвестное действие"}'; return 1 ;;
	esac
}
ZM_INSTALLER_EOF

mkdir -p /opt/zapret-manager-luci
cat > /opt/zapret-manager-luci/pages.b64 << 'ZM_INSTALLER_EOF'

ZM_INSTALLER_EOF
chmod 0644 /opt/zapret-manager-luci/pages.b64

mkdir -p /usr/libexec
cat > /usr/libexec/manager-awg-info.uc << 'ZM_INSTALLER_EOF'
let uci = require('uci').cursor();
let fs = require('fs');
let iface = ARGV[0];
if (!iface || !match(iface, /^[A-Za-z0-9_][A-Za-z0-9_.-]{0,14}$/)) exit(1);
function flag(value, fallback) {
    if (value == null) return fallback;
    return index(['1', 'true', 'yes', 'on'], '' + value) >= 0;
}
let result = { automatic: 'unknown', usage: [], forkop_error: false };
if (uci.load('network')) {
    let peers = 0, routes = 0;
    uci.foreach('network', 'amneziawg_' + iface, (peer) => {
        if (flag(peer.disabled, false)) return;
        peers++;
        if (flag(peer.route_allowed_ips, false)) routes++;
    });
    result.automatic = !peers ? 'unconfigured' : !routes ? 'disabled' : routes == peers ? 'enabled' : 'mixed';
}
let device_cache = {};
let bus = null;
try { bus = require('ubus').connect(); } catch (e) {}
function device(name) {
    if (!name || !match(name, /^[A-Za-z0-9_][A-Za-z0-9_.-]{0,14}$/)) return '';
    if (device_cache[name] != null) return device_cache[name];
    let state = bus ? bus.call('network.interface.' + name, 'status', {}) : null;
    return device_cache[name] = state?.l3_device || '';
}
function same(name) {
    return name == iface || (device(iface) != '' && (name == device(iface) || device(name) == device(iface)));
}
if (fs.stat('/usr/bin/forkop')) {
    if (!uci.load('forkop')) result.forkop_error = true;
    else {
        let sections = {};
        uci.foreach('forkop', 'section', (section) => { sections[section['.name']] = section; });
        let used = {};
        uci.foreach('forkop', 'section_interface', (child) => {
            let parent = sections[child.section];
            if (!parent || (parent.action || 'connection') != 'connection' || !same(child.name)) return;
            if (used[parent['.name']]) return;
            used[parent['.name']] = true;
            push(result.usage, { name: parent.label || parent['.name'], enabled: flag(parent.enabled, true), scope: 'section' });
        });
        uci.foreach('forkop', 'settings', (settings) => {
            if (same(settings.output_network_interface))
                push(result.usage, { name: 'Выход ядра', enabled: true, scope: 'output' });
        });
    }
}
printf('%J\n', result);
ZM_INSTALLER_EOF
chmod 0644 /usr/libexec/manager-awg-info.uc

mkdir -p /usr/libexec
cat > /usr/libexec/manager-compat << 'ZM_INSTALLER_EOF'
#!/bin/sh
set -u
umask 077
BASE=/tmp/manager-components
mkdir -m 700 "$BASE" 2>/dev/null || {
 [ -d "$BASE" ] && [ ! -L "$BASE" ] && [ "$(ls -nd "$BASE" | awk '{print $3}')" = 0 ] || exit 1
 chmod 700 "$BASE" || exit 1
}
pkg() {
 apk list --installed "$1" 2>/dev/null | awk -v p="$1-" 'index($1,p)==1 { print substr($1,length(p)+1); exit }'
}
running() {
 ubus call service list "{\"name\":\"$1\"}" 2>/dev/null | jsonfilter -e '@.*.instances.*.running' | grep -qx true && echo true || echo false
}
status() {
 local f c n u job port native enabled busy updates controls cached_phase cached_f cached_c cached_at refreshed core_running variant forkop_running nfq_enabled nfq_updates
 f="$(pkg forkop)"; c="$(pkg sing-box-forkop)"; n="$(pkg nfqws2-keenetic)"; u="$(pkg nfqws2-ui)"
 port="$(jsonfilter -i /etc/nfqws-ui/web.json -e '@.port' 2>/dev/null)"
 case "$port" in ''|*[!0-9]*) port=8090 ;; esac
 [ "$port" -ge 1 ] && [ "$port" -le 65535 ] || port=8090
 native='{}'; controls=false; enabled=false; busy=''
 if [ -x /usr/bin/forkop ] && native="$(/usr/bin/forkop get_ui_state 2>/dev/null)"; then
  controls=true
  [ "$(printf '%s' "$native" | jsonfilter -e '@.service.forkop.enabled')" != 1 ] || enabled=true
  busy="$(printf '%s' "$native" | jsonfilter -e '@.service.forkop.busy')"
  case "$busy" in null|false) busy='' ;; esac
 fi
 core_running=null
 forkop_running=null
 case "$(printf '%s' "$native" | jsonfilter -e '@.service.forkop.running')" in 1|true) forkop_running=true ;; 0|false) forkop_running=false ;; esac
 case "$(printf '%s' "$native" | jsonfilter -e '@.service.sing_box.running')" in 1|true) core_running=true ;; 0|false) core_running=false ;; esac
 variant="$(cat /usr/share/sing-box-forkop/variant 2>/dev/null)"
 case "$variant" in tiny|base|full) ;; *) variant='' ;; esac
 updates="$(shared_updates "$f" "$c")"
 nfq_enabled=false; /etc/init.d/nfqws2-keenetic enabled >/dev/null 2>&1 && nfq_enabled=true
 nfq_updates="$(shared_updates "$n" "$u" nfqws2-keenetic nfqws2-ui)"
 job='{"phase":"idle"}'
 [ ! -f "$BASE/state.json" ] || job="$(cat "$BASE/state.json")"
 if [ -d "$BASE/lock" ] && [ -f "$BASE/pid" ] && ! kill -0 "$(cat "$BASE/pid")" 2>/dev/null; then
  job='{"phase":"interrupted"}'
 fi
 printf '{"forkop":{"version":"%s","core":"%s","running":%s,"enabled":%s,"busy":"%s","core_running":%s,"variant":"%s","controls_available":%s,"updates":%s},"nfqws2":{"version":"%s","ui":"%s","running":%s,"enabled":%s,"updates":%s,"port":%s},"job":%s}\n' "$f" "$c" "$forkop_running" "$enabled" "$busy" "$core_running" "$variant" "$controls" "$updates" "$n" "$u" "$(running nfqws2-keenetic)" "$nfq_enabled" "$nfq_updates" "$port" "$job"
}
state() (
 set +u
 . /usr/share/libubox/jshn.sh
 json_init &&
 json_add_string phase "$1" && json_add_string component "$2" &&
 json_add_string operation "${3:-${CURRENT_OPERATION:-update}}" &&
 json_add_string message "${4:-}" &&
 json_dump > "$BASE/state.new" &&
 mv "$BASE/state.new" "$BASE/state.json"
)
service_snapshot() {
 MAINTENANCE_SERVICE="$1"
 SERVICE_WAS_RUNNING="$(running "$1")"
 SERVICE_WAS_ENABLED=false
 /etc/init.d/"$1" enabled >/dev/null 2>&1 && SERVICE_WAS_ENABLED=true
 if [ "$1" = forkop ]; then
  local snapshot
  snapshot="$(/usr/bin/forkop get_ui_state 2>/dev/null)" || return 1
  case "$(printf '%s' "$snapshot" | jsonfilter -e '@.service.forkop.running')" in
   1|true) SERVICE_WAS_RUNNING=true ;;
   0|false) SERVICE_WAS_RUNNING=false ;;
   *) NATIVE_ERROR='Не удалось определить состояние Forkop'; return 1 ;;
  esac
  CORE_WAS_ENABLED=false
  /etc/init.d/sing-box enabled >/dev/null 2>&1 && CORE_WAS_ENABLED=true
 fi
 SERVICE_RESTORE_PENDING=1
}
service_restore() {
 [ "${SERVICE_RESTORE_PENDING:-0}" = 1 ] || return 0
 local service="$MAINTENANCE_SERVICE" result=0 current operation tries=0
 SERVICE_RESTORE_PENDING=0
 if [ "$SERVICE_WAS_ENABLED" = true ]; then
  /etc/init.d/"$service" enabled >/dev/null 2>&1 || /etc/init.d/"$service" enable || result=1
 else
  if /etc/init.d/"$service" enabled >/dev/null 2>&1; then /etc/init.d/"$service" disable || result=1; fi
 fi
 if [ "$service" = forkop ]; then
  local snapshot busy
  snapshot="$(/usr/bin/forkop get_ui_state 2>/dev/null)" || return 1
  busy="$(printf '%s' "$snapshot" | jsonfilter -e '@.service.forkop.busy')"
  case "$busy" in ''|false|null) ;; *) NATIVE_ERROR='Установщик Forkop ещё занят; проверьте состояние службы'; return 1 ;; esac
  case "$(printf '%s' "$snapshot" | jsonfilter -e '@.service.forkop.running')" in
   1|true) current=true ;; 0|false) current=false ;;
   *) NATIVE_ERROR='Не удалось проверить состояние Forkop после обновления'; return 1 ;;
  esac
  if [ "$current" != "$SERVICE_WAS_RUNNING" ]; then
   operation=stop; [ "$SERVICE_WAS_RUNNING" != true ] || operation=start
   native_service_action "$operation" || result=1
  fi
  if [ "$CORE_WAS_ENABLED" = true ]; then
   /etc/init.d/sing-box enabled >/dev/null 2>&1 || /etc/init.d/sing-box enable || result=1
  else
   if /etc/init.d/sing-box enabled >/dev/null 2>&1; then /etc/init.d/sing-box disable || result=1; fi
  fi
 else
  current="$(running "$service")"
  if [ "$current" != "$SERVICE_WAS_RUNNING" ]; then
   operation=stop; [ "$SERVICE_WAS_RUNNING" != true ] || operation=start
   /etc/init.d/"$service" "$operation" || result=1
  fi
  while [ "$(running "$service")" != "$SERVICE_WAS_RUNNING" ] && [ "$tries" -lt 20 ]; do
   sleep 1; tries=$((tries + 1))
  done
  [ "$(running "$service")" = "$SERVICE_WAS_RUNNING" ] || result=1
 fi
 if [ "$result" != 0 ]; then NATIVE_ERROR='Не удалось восстановить состояние службы после обновления'; fi
 return "$result"
}
worker_cleanup() {
 local result="$?"
 trap - EXIT
 service_restore || result=1
 if [ "$result" != 0 ]; then
  state failed "$WORKER_COMPONENT" "$WORKER_OPERATION" "${NATIVE_ERROR:-Обновление прервано}"
 fi
 rmdir "$BASE/lock" 2>/dev/null || true
 exit "$result"
}
worker() {
 local component="$1" result=1 operation="${2:-update}"
 CURRENT_OPERATION="$operation"
 WORKER_COMPONENT="$component"
 WORKER_OPERATION="$operation"
 trap worker_cleanup EXIT
 trap 'exit 1' HUP INT TERM
 state running "$component" || return 1
 case "$operation" in
  update|update_auto|update_core|variant_tiny|variant_base|variant_full)
   /opt/zapret-manager-luci/backend.sh compat_backup_before "$component" || return 1 ;;
 esac
 if [ "$operation" = recover ]; then
  echo "$$" > "$BASE/pid" || return 1
  if ! /usr/libexec/manager-watch.uc eligible "$component"; then
   state succeeded "$component" "$operation" 'Состояние изменилось, восстановление не требуется'
   return 0
  fi
  case "$component" in
   forkop)
    native_service_action start
    result=$?
    if [ "$result" = 0 ]; then
     local recovered
     recovered="$(/usr/bin/forkop get_ui_state 2>/dev/null)"
     case "$(printf '%s' "$recovered" | jsonfilter -e '@.service.forkop.running')" in
      1|true) ;;
      *) result=1; NATIVE_ERROR='Forkop завершил запуск, но служба не работает' ;;
     esac
    fi
    ;;
   nfqws2)
    if /etc/init.d/nfqws2-keenetic start; then
     local tries=0
     while [ "$(running nfqws2-keenetic)" != true ] && [ "$tries" -lt 10 ]; do
      sleep 1
      tries=$((tries + 1))
     done
     [ "$(running nfqws2-keenetic)" = true ] && result=0
    fi
    ;;
  esac
  if [ "$result" = 0 ]; then
   logger -t zapret-manager "$component восстановлен после сбоя"
   state succeeded "$component" "$operation"
  else
   logger -t zapret-manager "Не удалось восстановить $component после сбоя"
   state failed "$component" "$operation" "${NATIVE_ERROR:-Не удалось восстановить службу после сбоя}"
  fi
  return "$result"
 fi
 if [ "$component" = nfqws2 ]; then
  case "$operation" in
   start|stop|restart|autostart_on|autostart_off)
    case "$operation" in autostart_on) native=enable ;; autostart_off) native=disable ;; *) native="$operation" ;; esac
    if /etc/init.d/nfqws2-keenetic "$native"; then
     if [ "$native" = start ] || [ "$native" = restart ]; then
      local tries=0
      while [ "$(running nfqws2-keenetic)" != true ] && [ "$tries" -lt 10 ]; do sleep 1; tries=$((tries + 1)); done
      [ "$(running nfqws2-keenetic)" = true ] || { state failed "$component" "$operation" 'NFQWS2 не запустился'; return 1; }
     fi
     if [ "$native" = stop ]; then
      local tries=0
      while [ "$(running nfqws2-keenetic)" = true ] && [ "$tries" -lt 10 ]; do sleep 1; tries=$((tries + 1)); done
      [ "$(running nfqws2-keenetic)" = false ] || { state failed "$component" "$operation" 'NFQWS2 не остановился'; return 1; }
     fi
     state succeeded "$component" "$operation"; return 0
    fi
    state failed "$component" "$operation" 'Не удалось выполнить команду NFQWS2'; return 1 ;;
  esac
 fi
 if [ "$component" = forkop ]; then
  case "$operation" in
   autostart_on|autostart_off)
    if [ "$operation" = autostart_on ]; then /etc/init.d/forkop enable; else /etc/init.d/forkop disable; fi
    result=$?; if [ "$result" = 0 ]; then state succeeded "$component" "$operation"; else state failed "$component" "$operation"; fi; return "$result" ;;
   variant_tiny|variant_base|variant_full)
    service_snapshot forkop || { state failed "$component" "$operation" "${NATIVE_ERROR:-Не удалось прочитать состояние службы}"; return 1; }
    if native_installer variant "${operation#variant_}"; then result=0; else result=1; fi
    service_restore || result=1
    if [ "$result" = 0 ]; then state succeeded "$component" "$operation"; else state failed "$component" "$operation" "${NATIVE_ERROR:-Не удалось сменить сборку}"; fi
    return "$result" ;;
   start|stop|restart)
    if native_service_action "$operation"; then state succeeded "$component" "$operation"; return "$?"; fi
    state failed "$component" "$operation" "${NATIVE_ERROR:-Не удалось выполнить команду Forkop}"; return 1 ;;
   update|update_core|update_auto) ;;
   *) state failed "$component" "$operation" 'Неизвестное действие'; return 1 ;;
  esac
 fi
 case "$component" in
  forkop)
   if [ -x /usr/bin/forkop ]; then
    service_snapshot forkop || { state failed "$component" "$operation" "${NATIVE_ERROR:-Не удалось прочитать состояние службы}"; return 1; }
    if native_installer; then result=0; else result=1; fi
   else
   # The reviewed upstream installer resolves compatible backend, LuCI, i18n and core manifests.
   # Use its release file, not an unverified pipe from a moving branch.
   if curl -fsSL --connect-timeout 15 --max-time 90 https://github.com/ushan0v/forkop/releases/download/2.0.0/install.sh -o "$BASE/forkop-install.sh" &&
      echo '43268a5465a80123f81eb517cf567dbceacad77b8de62c37479dc2fd24a69599  /tmp/manager-components/forkop-install.sh' | sha256sum -c -; then
    sh "$BASE/forkop-install.sh" --variant full --quiet --lang ru
    result=$?
   fi
   fi
   ;;
  nfqws2)
   if nfq_auto_update "$operation"; then result=0; else result=1; fi ;;

 esac
 service_restore || result=1
 if [ "$result" = 0 ]; then
  state succeeded "$component" || return 1
  /opt/zapret-manager-luci/backend.sh versions auto >/dev/null 2>&1 || true
 else state failed "$component" "$operation" "${NATIVE_ERROR:-Ошибка установки; подробности в журнале}"; fi
 return "$result"
}
ensure_nfq_repo() {
 curl -fsSL --connect-timeout 15 --max-time 45 https://nfqws.github.io/nfqws2-keenetic/openwrt/nfqws2-keenetic.pem -o "$BASE/nfqws2-keenetic.pem" || return 1
 echo '4af57e5d215f4094388c1d98ca4cd0403d4dff410b7c20f1f8dce03efd9ea149  /tmp/manager-components/nfqws2-keenetic.pem' | sha256sum -c - || return 1
 cp "$BASE/nfqws2-keenetic.pem" /etc/apk/keys/nfqws2-keenetic.pem || return 1
 printf '%s\n' https://nfqws.github.io/nfqws2-keenetic/openwrt/packages.adb > /etc/apk/repositories.d/nfqws2-keenetic.list
}
fetch_nfq_ui() {
 local tag version file digest
 curl -fsSL --connect-timeout 15 --max-time 45 https://api.github.com/repos/zemidala/nfqws2-ui/releases/latest -o "$BASE/nfqws2-ui-release.json" || return 1
 tag="$(jsonfilter -i "$BASE/nfqws2-ui-release.json" -e '@.tag_name')"
 echo "$tag" | grep -Eq '^v[0-9]+\.[0-9]+\.[0-9]+$' || return 1
 version="${tag#v}"; file="nfqws2-ui_${version}-1_all.apk"
 digest="$(jsonfilter -i "$BASE/nfqws2-ui-release.json" -e "@.assets[@.name='$file'].digest")"
 echo "$digest" | grep -Eq '^sha256:[a-f0-9]{64}$' || { echo 'No trusted release checksum for UI'; return 1; }
 curl -fsSL --connect-timeout 15 --max-time 120 "https://github.com/zemidala/nfqws2-ui/releases/download/$tag/$file" -o "$BASE/nfqws2-ui.apk" || return 1
 echo "${digest#sha256:}  $BASE/nfqws2-ui.apk" | sha256sum -c -
}
install_nfq_binary() {
 local arch source
 arch="$(uname -m)"
 case "$arch" in x86_64|aarch64|mips|mipsel|mips64) ;; armv7l) arch=armv7 ;; i?86) arch=x86 ;; *) echo 'Unsupported NFQWS2 binary architecture'; return 1 ;; esac
 source="/tmp/nfqws2_binary/nfqws2-$arch"
 # The universal signed package selects a bundled binary in postinstall. Do that
 # one step explicitly because --no-scripts intentionally prevents auto-start.
 if [ -f "$source" ]; then
  cp "$source" /usr/bin/nfqws2.manager-new && chmod 755 /usr/bin/nfqws2.manager-new && mv /usr/bin/nfqws2.manager-new /usr/bin/nfqws2
 else
  test -x /usr/bin/nfqws2 || return 1
 fi
}
native_service_action() {
 local operation="$1" reply id snapshot active success i=0
 reply="$(/usr/bin/forkop service_action_async "$operation" 2>/dev/null)"
 if [ "$(printf '%s' "$reply" | jsonfilter -e '@.success')" != true ]; then
  NATIVE_ERROR="$(printf '%s' "$reply" | jsonfilter -e '@.message')"
  [ -n "$NATIVE_ERROR" ] || NATIVE_ERROR='Forkop отклонил команду службы'
  return 1
 fi
 id="$(printf '%s' "$reply" | jsonfilter -e '@.job_id')"
 echo "$id" | grep -Eq '^[A-Za-z0-9._-]+$' || { NATIVE_ERROR='Некорректный номер задания Forkop'; return 1; }
 while [ "$i" -lt 120 ]; do
  snapshot="$(/usr/bin/forkop get_ui_state 2>/dev/null)" || { NATIVE_ERROR='Потеряна связь с Forkop'; return 1; }
  active="$(printf '%s' "$snapshot" | jsonfilter -e "@.actions.service[@.job_id='$id'].running")"
  if [ "$active" = false ]; then
   success="$(printf '%s' "$snapshot" | jsonfilter -e "@.actions.service[@.job_id='$id'].success")"
   [ "$success" != true ] || return 0
   NATIVE_ERROR="$(printf '%s' "$snapshot" | jsonfilter -e "@.actions.service[@.job_id='$id'].message")"
   [ -n "$NATIVE_ERROR" ] || NATIVE_ERROR='Команда Forkop завершилась ошибкой'
   return 1
  fi
  i=$((i + 1)); sleep 1
 done
 NATIVE_ERROR='Истекло время ожидания команды Forkop; проверьте состояние службы'
 return 1
}
native_installer() {
 local reply id snapshot active code current i=0 offset=0 next
 reply="$(/usr/bin/forkop installer_start "${1:-update}" "${2:-}" 0 ru 2>/dev/null)" || { NATIVE_ERROR='Forkop не запустил штатный установщик'; return 1; }
 id="$(printf '%s' "$reply" | jsonfilter -e '@.id')"
 echo "$id" | grep -Eq '^[A-Za-z0-9._-]+$' || { NATIVE_ERROR='Штатный установщик не вернул номер задания'; return 1; }
 while [ "$i" -lt 600 ]; do
  snapshot="$(/usr/bin/forkop installer_status "$offset" 2>/dev/null)" || { NATIVE_ERROR='Не удалось получить состояние установщика Forkop'; return 1; }
  current="$(printf '%s' "$snapshot" | jsonfilter -e '@.id')"
  [ "$current" = "$id" ] || { NATIVE_ERROR='Задание установщика Forkop сменилось'; return 1; }
  printf '%s' "$snapshot" | jsonfilter -e '@.data'
  next="$(printf '%s' "$snapshot" | jsonfilter -e '@.next')"
  case "$next" in ''|*[!0-9]*) ;; *) offset="$next" ;; esac
  active="$(printf '%s' "$snapshot" | jsonfilter -e '@.running')"
  if [ "$active" = false ]; then
   code="$(printf '%s' "$snapshot" | jsonfilter -e '@.exit')"
   [ "$code" != 0 ] || return 0
   NATIVE_ERROR="Установщик Forkop завершился с кодом ${code:-неизвестно}; подробности в журнале"
   return 1
  fi
  i=$((i + 1)); sleep 1
 done
 NATIVE_ERROR='Истекло время ожидания установщика; проверьте его состояние в Forkop'
 return 1
}
version_newer() {
 local old="${1#v}" new="${2#v}"
 echo "$old" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+(-r[0-9]+)?$' || return 2
 echo "$new" | grep -Eq '^[0-9]+\.[0-9]+\.[0-9]+(-r[0-9]+)?$' || return 2
 awk -v old="$old" -v new="$new" 'BEGIN {
  split(old,a,/[.-]/);split(new,b,/[.-]/);sub(/^r/,"",a[4]);sub(/^r/,"",b[4]);
  for(i=1;i<=4;i++){if((b[i]+0)>(a[i]+0))exit 0;if((b[i]+0)<(a[i]+0))exit 1}exit 1
 }'
}
updates_json() (
 set +u
 local phase="$1" latest_f="${2:-}" latest_c="${3:-}" error="${4:-}" checked_at="${5-$(date +%s)}" current_f="${6-$(pkg forkop)}" current_c="${7-$(pkg sing-box-forkop)}" f_available=null c_available=null code
 case "$checked_at" in ''|*[!0-9]*) checked_at=0 ;; esac
 if [ "$phase" = ok ]; then
  version_newer "$current_f" "$latest_f"; code=$?
  case "$code" in 0) f_available=true ;; 1) f_available=false ;; esac
  version_newer "$current_c" "$latest_c"; code=$?
  case "$code" in 0) c_available=true ;; 1) c_available=false ;; esac
 fi
 . /usr/share/libubox/jshn.sh
 json_init && json_add_string state "$phase" && json_add_int checked_at "$checked_at" &&
 json_add_boolean coordinated 1 && json_add_string error "$error" &&
 json_add_object forkop && json_add_string latest "$latest_f" || return 1
 if [ "$f_available" = null ]; then json_add_null available || return 1; else [ "$f_available" = true ] && code=1 || code=0; json_add_boolean available "$code" || return 1; fi
 json_close_object && json_add_object core && json_add_string latest "$latest_c" || return 1
 if [ "$c_available" = null ]; then json_add_null available || return 1; else [ "$c_available" = true ] && code=1 || code=0; json_add_boolean available "$code" || return 1; fi
 json_close_object && json_dump
)
shared_updates() {
 local response phase=unchecked latest_f latest_c checked pending name_f="${3:-forkop}" name_c="${4:-sing-box-forkop}"
 if ! response="$(/opt/zapret-manager-luci/backend.sh versions '')"; then
  updates_json error '' '' 'Не удалось получить версии' 0 "$1" "$2"; return
 fi
 checked="$(printf '%s' "$response" | jsonfilter -e '@.at')"
 case "$checked" in ''|*[!0-9]*) checked=0 ;; esac
 pending="$(printf '%s' "$response" | jsonfilter -e '@.pending')"
 latest_f="$(printf '%s' "$response" | jsonfilter -e "@.items[@.name=\"$name_f\"].latest")"
 latest_c="$(printf '%s' "$response" | jsonfilter -e "@.items[@.name=\"$name_c\"].latest")"
 [ "$checked" = 0 ] || phase=ok
 [ "$pending" != true ] || phase=checking
 updates_json "$phase" "$latest_f" "$latest_c" '' "$checked" "$1" "$2"
}
check_updates() {
 local reply
 if ! reply="$(/opt/zapret-manager-luci/backend.sh versions refresh)"; then
  echo '{"error":"Не удалось проверить версии"}'; return 1
 fi
 printf '%s' "$reply" | jsonfilter -e '@.items' >/dev/null 2>&1 || { echo '{"error":"Не удалось проверить версии"}'; return 1; }
 echo '{"ok":true}'
}
nfq_auto_update() {
 local operation="${1:-update_auto}" engine ui tries=0
 engine="$(pkg nfqws2-keenetic)"; ui="$(pkg nfqws2-ui)"
 [ "$operation" != update_auto ] || [ -n "$engine$ui" ] || return 1
 # Finish downloads and repository checks before interrupting traffic.
 if [ "$operation" = update ] || [ -n "$ui" ]; then fetch_nfq_ui || return 1; fi
 if [ "$operation" = update ] || [ -n "$engine" ]; then ensure_nfq_repo && apk update || return 1; fi
 if [ -n "$engine" ]; then
  service_snapshot nfqws2-keenetic || return 1
  if [ "$SERVICE_WAS_RUNNING" = true ]; then
   /etc/init.d/nfqws2-keenetic stop || return 1
   while [ "$(running nfqws2-keenetic)" = true ] && [ "$tries" -lt 20 ]; do
    sleep 1; tries=$((tries + 1))
   done
   [ "$(running nfqws2-keenetic)" = false ] || { NATIVE_ERROR='NFQWS2 не остановился перед обновлением'; return 1; }
  fi
 fi
 if [ "$operation" = update ]; then
  apk add --no-scripts nfqws2-keenetic lighttpd lighttpd-mod-cgi lighttpd-mod-rewrite lighttpd-mod-setenv php8-cgi php8-mod-session php8-mod-curl curl &&
   apk add --no-scripts --allow-untrusted "$BASE/nfqws2-ui.apk" && install_nfq_binary && nfqws-ui-setup apply || return 1
  if [ -z "$engine" ]; then /etc/init.d/nfqws2-keenetic disable || return 1; fi
  /etc/init.d/lighttpd enable || return 1
 else
  if [ -n "$engine" ]; then
   apk add --upgrade --no-scripts nfqws2-keenetic && install_nfq_binary || return 1
  fi
  if [ -n "$ui" ]; then
   apk add --upgrade --no-scripts --allow-untrusted "$BASE/nfqws2-ui.apk" && nfqws-ui-setup apply || return 1
  fi
 fi
}

action() {
 if [ -d /tmp/manager-maintenance.lock ] && [ "${COMPAT_BACKUP:-}" != 1 ]; then
  echo '{"error":"Дождитесь завершения текущей операции"}'
  return 1
 fi
 if [ -d /tmp/manager-backup-restore.lock ] && [ "${COMPAT_BACKUP:-}" != 1 ]; then
  echo '{"error":"Дождитесь завершения восстановления резервной копии"}'
  return 1
 fi
 case "${1:-}" in forkop|nfqws2) ;; *) echo '{"error":"Unknown component"}'; return 1 ;; esac
 local operation="${2:-update}" native busy
 if [ "$operation" = recover ]; then
  [ -x /usr/libexec/manager-watch.uc ] || {
   echo '{"error":"Проверка восстановления недоступна"}'
   return 1
  }
 fi
 case "$1:$operation" in forkop:update_auto) [ -n "$(pkg forkop)" ] || { echo '{"error":"Forkop не установлен"}'; return 1; } ;; nfqws2:start|nfqws2:stop|nfqws2:restart|nfqws2:autostart_on|nfqws2:autostart_off|nfqws2:recover) [ -x /etc/init.d/nfqws2-keenetic ] || { echo '{"error":"NFQWS2 не установлен"}'; return 1; } ;; forkop:autostart_on|forkop:autostart_off|forkop:variant_tiny|forkop:variant_base|forkop:variant_full|nfqws2:update_auto|forkop:update|forkop:update_core|forkop:start|forkop:stop|forkop:restart|forkop:recover|nfqws2:update) ;; *) echo '{"error":"Неизвестное действие"}'; return 1 ;; esac
 if [ "$1" = forkop ] && [ -x /usr/bin/forkop ]; then
  native="$(/usr/bin/forkop get_ui_state 2>/dev/null)" || { echo '{"error":"Не удалось прочитать состояние Forkop"}'; return 1; }
  busy="$(printf '%s' "$native" | jsonfilter -e '@.service.forkop.busy')"
  case "$busy" in null|false) busy='' ;; esac
  [ -z "$busy" ] || { echo '{"error":"В Forkop уже выполняется операция"}'; return 1; }
 fi
 if ! mkdir "$BASE/lock" 2>/dev/null; then echo '{"error":"An operation is already running or needs recovery"}'; return 1; fi
 if [ -d /tmp/manager-maintenance.lock ] && [ "${COMPAT_BACKUP:-}" != 1 ]; then
  rmdir "$BASE/lock" 2>/dev/null || true
  echo '{"error":"Дождитесь завершения текущей операции"}'
  return 1
 fi
 if ! state queued "$1" "$operation"; then
  rmdir "$BASE/lock" 2>/dev/null || true
  echo '{"error":"Не удалось сохранить состояние задания; операция не запускалась"}'
  return 1
 fi
 setsid /bin/sh "$0" worker "$1" "$operation" > "$BASE/job.log" 2>&1 < /dev/null &
 echo "$!" > "$BASE/pid"
 echo '{"ok":true}'
}
case "${1:-}" in
 status) status ;;
 action) action "${2:-}" "${3:-update}" ;;
 check_updates) check_updates ;;
 worker) worker "${2:-}" "${3:-update}" ;;
 *) echo '{"error":"Unknown method"}'; exit 1 ;;
esac
ZM_INSTALLER_EOF
chmod 0755 /usr/libexec/manager-compat

mkdir -p /usr/libexec
cat > /usr/libexec/manager-forkop-remove.uc << 'ZM_INSTALLER_EOF'
#!/usr/bin/ucode
// Keep the native client loaded while the uninstaller removes Forkop's CLI.
import * as fs from 'fs';

let library = '/usr/lib/forkop';
try {
    library = loadfile(library + '/core/bytecode.uc')().refresh();
} catch (error) {}
unshift(REQUIRE_SEARCH_PATH, library + '/*.uc');
let installer = require('service.installer');
let job = installer.start('uninstall', '', true, 'ru');
if (type(job?.id) != 'string') {
    print('Не удалось запустить удаление Forkop\n');
    exit(1);
}
let offset = 0;
for (let attempt = 0; attempt < 600; attempt++) {
    let state = installer.status(offset);
    if (state?.id != job.id) {
        print('Не удалось проверить результат удаления Forkop\n');
        exit(1);
    }
    if (type(state.data) == 'string') print(state.data);
    if (type(state.next) == 'int') offset = state.next;
    if (state.running === false) exit(state.exit == 0 ? 0 : 1);
    let waiter = fs.popen('sleep 1', 'r');
    if (waiter == null) exit(1);
    waiter.close();
}
print('Удаление Forkop не завершилось за отведённое время\n');
exit(1);
ZM_INSTALLER_EOF
chmod 0755 /usr/libexec/manager-forkop-remove.uc

mkdir -p /usr/libexec
cat > /usr/libexec/manager-proton << 'ZM_INSTALLER_EOF'
#!/usr/bin/ucode
import * as fs from 'fs';

const STATE = '/opt/zapret-manager-luci/state/proton';
const RUN = '/tmp/manager-proton';
const API = 'https://www.api-proton.workers.dev';
const PROFILE = STATE + '/Proton.conf';
const MAX_RESPONSE = 1048576;
const META_PREFIX = '# Manager-Proton: ';
const PID = int(split(fs.readfile('/proc/self/stat') || '', ' ')[0]);
let lock_handle = null;
let work = null;

function fail(message) {
    die(message);
}

function quote(value) {
    return "'" + replace(value, /'/g, "'\\''") + "'";
}

function run(command) {
    let process = fs.popen('umask 077; ' + command + ' 2>/dev/null', 'r');
    if (process == null) return { code: 1, output: '' };
    let output = process.read('all') || '';
    return { code: process.close(), output };
}

function private_dir(path) {
    let info = fs.lstat(path);
    if (info == null) {
        if (!fs.mkdir(path, 0700)) fail('Не удалось подготовить папку для Proton VPN.');
        info = fs.lstat(path);
    }
    if (info?.type != 'directory' || info.uid != 0 || (info.mode & 0022))
        fail('Не удалось открыть папку Proton VPN.');
    if (!fs.chmod(path, 0700)) fail('Не удалось защитить настройки Proton VPN.');
}

function write_private(path, content) {
    let handle = fs.open(path, 'wx', 0600);
    if (handle == null) fail('Не удалось сохранить настройки Proton VPN.');
    let written = handle.write(content);
    let closed = handle.close();
    if (written != length(content) || !closed) {
        fs.unlink(path);
        fail('Не удалось сохранить файл. Проверьте свободное место на роутере.');
    }
}

function read_json(path, limit) {
    let info = fs.lstat(path);
    if (info?.type != 'file' || info.uid != 0 || (info.mode & 0077) || info.size > limit)
        return null;
    try { return json(fs.readfile(path)); }
    catch (error) { return null; }
}

function lock() {
    private_dir(RUN);
    let path = RUN + '/lock';
    let info = fs.lstat(path);
    if (info != null && (info.type != 'file' || info.uid != 0 || (info.mode & 0077)))
        fail('Не удалось открыть настройки Proton VPN.');
    lock_handle = fs.open(path, 'ae', 0600);
    if (lock_handle == null || !lock_handle.lock('xn'))
        fail('Дождитесь завершения текущей операции Proton VPN.');
    work = fs.mkdtemp(RUN + '/work.XXXXXX');
    if (work == null) fail('Не удалось подготовить создание конфигурации.');
}

function cleanup() {
    if (work != null) {
        for (let name in fs.lsdir(work) || []) fs.unlink(work + '/' + name);
        fs.rmdir(work);
    }
    if (lock_handle != null) lock_handle.close();
}

function interrupted() {
    fail('Создание конфигурации Proton VPN прервано.');
}

for (let name in ['HUP', 'INT', 'TERM']) signal(name, interrupted);

function api(path, body) {
    let request = work + '/request.json';
    let response = work + '/response.json';
    fs.unlink(request);
    fs.unlink(response);
    write_private(request, sprintf('%J', body));
    let result = run('ulimit -f 2048; curl --silent --show-error --proto =https ' +
        '--connect-timeout 8 --max-time 30 --max-filesize 1048576 ' +
        '--header ' + quote('Content-Type: application/json') + ' --request POST ' +
        '--data-binary ' + quote('@' + request) + ' --output ' + quote(response) +
        ' --write-out ' + quote('%{http_code}') + ' ' + quote(API + path));
    fs.unlink(request);
    let info = fs.stat(response);
    if (trim(result.output) == '401' || trim(result.output) == '403') fs.unlink(RUN + '/session.json');
    if (result.code != 0 || trim(result.output) != '200' || info?.size > MAX_RESPONSE)
        fail('Сервис Proton VPN недоступен. Попробуйте позже или загрузите свой файл.');
    fs.chmod(response, 0600);
    let data = read_json(response, MAX_RESPONSE);
    fs.unlink(response);
    if (data?.ok !== true) {
        fs.unlink(RUN + '/session.json');
        fail('Сервис Proton VPN не выполнил запрос. Обновите список серверов или загрузите свой файл.');
    }
    return data;
}

function ipv4(value) {
    if (type(value) != 'string' || !match(value, /^[0-9]+\.[0-9]+\.[0-9]+\.[0-9]+$/)) return false;
    let octets = split(value, '.');
    for (let octet in octets)
        if (int(octet) > 255 || '' + int(octet) != octet) return false;
    let a = int(octets[0]), b = int(octets[1]);
    return a > 0 && a < 224 && a != 10 && a != 127 &&
        !(a == 100 && b >= 64 && b <= 127) && !(a == 169 && b == 254) &&
        !(a == 172 && b >= 16 && b <= 31) && !(a == 192 && b == 168) &&
        !(a == 192 && b == 0) && !(a == 198 && (b == 18 || b == 19));
}

function key_ok(value) {
    return type(value) == 'string' && length(value) == 44 &&
        length(b64dec(value)) == 32 && b64enc(b64dec(value)) == value;
}

function normalize(server) {
    if (type(server) != 'object') return null;
    let id = server.id;
    let country = server.exitCountry || server.country;
    let ip = server.entryIp || server.entry_ip;
    let key = server.publicKey || server.public_key;
    if (type(id) != 'string' || !length(id) || length(id) > 256 || !match(id, /^[A-Za-z0-9+\/=_.:-]+$/) ||
        type(country) != 'string' || !match(country, /^[A-Z]{2}$/) || !ipv4(ip) || !key_ok(key))
        return null;
    let name = type(server.name) == 'string' ? server.name : country;
    name = substr(trim(replace(name, /[[:cntrl:]]/g, '')), 0, 80);
    return { id, name, country, load: min(100, max(0, int(server.load || 0))), entry_ip: ip, public_key: key };
}

function listing() {
    let cached = read_json(RUN + '/session.json', MAX_RESPONSE);
    if (cached?.expires > time() && cached.expires <= time() + 86400 &&
        type(cached.servers) == 'array' && length(cached.servers)) return cached;
    let session = api('/api/proton/session', {}).session;
    if ((type(session) != 'string' && type(session) != 'object') ||
        !length(sprintf('%J', session)) || length(sprintf('%J', session)) > 8192)
        fail('Сервис Proton VPN не выдал доступ. Попробуйте позже или загрузите свой файл.');
    let response = api('/api/proton/servers', { session });
    if (type(response.servers) != 'array' || length(response.servers) > 5000)
        fail('Не удалось получить список серверов Proton VPN.');
    let servers = [];
    let seen = {};
    for (let server in response.servers) {
        let item = normalize(server);
        if (item != null && !seen[item.id]) { push(servers, item); seen[item.id] = true; }
    }
    if (!length(servers)) fail('Сейчас нет доступных серверов Proton VPN. Попробуйте позже.');
    let state = { session, servers, expires: time() + 23 * 3600 };
    let temporary = work + '/session.json';
    write_private(temporary, sprintf('%J', state));
    if (!fs.rename(temporary, RUN + '/session.json')) fail('Не удалось сохранить список серверов.');
    return state;
}

function public_server(server) {
    return { id: server.id, name: server.name, country: server.country, load: server.load };
}

function profile() {
    let info = fs.lstat(PROFILE);
    if (info?.type != 'file' || info.uid != 0 || (info.mode & 0077) || info.size > 65536) return null;
    let content = fs.readfile(PROFILE);
    if (type(content) != 'string' || !match(content, /\n\[Interface\]\n/)) return null;
    let first = split(content, '\n')[0];
    if (substr(first, 0, length(META_PREFIX)) != META_PREFIX) return null;
    try {
        let meta = json(substr(first, length(META_PREFIX)));
        if (type(meta.name) != 'string' || type(meta.country) != 'string' || !match(meta.country, /^[A-Z]{2}$/)) return null;
        return { content, server: meta };
    }
    catch (error) { return null; }
}

function crypto() {
    let tool = trim(run('command -v awg || command -v wg').output);
    if (!length(tool)) fail('Установите AmneziaWG, чтобы создать конфигурацию Proton VPN.');
    if (run('command -v openssl').code != 0)
        fail('Для создания конфигурации нужен пакет openssl-util. Установите его и повторите попытку.');
    let pem = work + '/ed25519.pem';
    let der = work + '/ed25519.der';
    let seed = work + '/seed';
    let digest = work + '/sha512';
    let pub = work + '/public.pem';
    let pubder = work + '/public.der';
    let commands = [
        'openssl genpkey -algorithm ED25519 -out ' + quote(pem),
        'openssl pkey -in ' + quote(pem) + ' -outform DER -out ' + quote(der),
        'openssl pkey -in ' + quote(pem) + ' -pubout -out ' + quote(pub),
        'openssl pkey -in ' + quote(pem) + ' -pubout -outform DER -out ' + quote(pubder)
    ];
    for (let command in commands)
        if (run(command).code != 0) fail('Не удалось создать ключ Proton VPN. Проверьте пакет openssl-util.');
    let encoded = fs.readfile(der);
    let encoded_public = fs.readfile(pubder);
    if (length(encoded) != 48 || substr(encoded, 0, 16) != b64dec('MC4CAQAwBQYDK2VwBCIEIA==') ||
        length(encoded_public) != 44 || substr(encoded_public, 0, 12) != b64dec('MCowBQYDK2VwAyEA'))
        fail('Не удалось прочитать созданный ключ Proton VPN.');
    write_private(seed, substr(encoded, 16));
    if (run('openssl dgst -sha512 -binary ' + quote(seed) + ' > ' + quote(digest)).code != 0)
        fail('Не удалось подготовить ключ Proton VPN.');
    let hash = fs.readfile(digest);
    if (length(hash) != 64) fail('Не удалось подготовить ключ Proton VPN.');
    let scalar = chr(ord(hash, 0) & 248) + substr(hash, 1, 30) + chr((ord(hash, 31) & 127) | 64);
    let private_key = b64enc(scalar);
    write_private(work + '/wireguard.key', private_key + '\n');
    let check = run(quote(tool) + ' pubkey < ' + quote(work + '/wireguard.key'));
    if (check.code != 0 || !key_ok(trim(check.output))) fail('Не удалось проверить созданный ключ.');
    return { private_key, public_pem: fs.readfile(pub) };
}

function generate(id, mask) {
    if (type(id) != 'string' || !length(id) || length(id) > 256)
        fail('Выберите сервер Proton VPN.');
    mask = mask == null ? '' : mask;
    if (type(mask) != 'string' || (length(mask) &&
        (length(mask) > 8192 || match(mask, /[[:cntrl:]]/) ||
         !match(mask, /^<b 0x[0-9a-fA-F]+>$/) || (length(mask) - 6) % 2)))
        fail('Не удалось применить маскировку Proton VPN. Создайте конфигурацию заново.');
    let state = listing();
    let chosen = null;
    for (let server in state.servers) if (server.id == id) chosen = normalize(server);
    if (chosen == null) fail('Сервер больше недоступен. Обновите список и выберите другой.');
    let pair = crypto();
    api('/api/proton/certificate', { session: state.session, clientPublicKey: pair.public_pem, persistent: true });
    let meta = public_server(chosen);
    let masking = length(mask) ? 'Jc = 3\nJmin = 1\nJmax = 3\n' : 'Jc = 0\nJmin = 0\nJmax = 0\n';
    let content = META_PREFIX + sprintf('%J', meta) + '\n' +
        '[Interface]\nPrivateKey = ' + pair.private_key + '\nAddress = 10.2.0.2/32\nDNS = 10.2.0.1\nMTU = 1280\n' +
        masking + 'S1 = 0\nS2 = 0\nH1 = 1\nH2 = 2\nH3 = 3\nH4 = 4\n' +
        (length(mask) ? 'I1 = ' + mask + '\n' : '') + '\n' +
        '[Peer]\nPublicKey = ' + chosen.public_key + '\nAllowedIPs = 0.0.0.0/0\nEndpoint = ' +
        chosen.entry_ip + ':51820\nPersistentKeepalive = 25\n';
    private_dir(STATE);
    let temporary = STATE + '/Proton.conf.' + PID;
    fs.unlink(temporary);
    write_private(temporary, content);
    if (fs.readfile(temporary) != content || !fs.rename(temporary, PROFILE)) {
        fs.unlink(temporary);
        fail('Не удалось сохранить конфигурацию. Проверьте свободное место на роутере.');
    }
    return { ok: true, ready: true, server: meta };
}

let result;
let failed = false;
try {
    let command = ARGV[0];
    if (command == 'status') {
        let saved = profile();
        result = { ok: true, ready: saved != null, server: saved?.server };
    }
    else if (command == 'config') {
        let saved = profile();
        if (saved == null) fail('Сначала создайте конфигурацию Proton VPN.');
        result = { ok: true, content: saved.content, server: saved.server };
    }
    else if (command == 'servers' || command == 'generate') {
        lock();
        if (command == 'servers') {
            if (ARGV[1] == 'refresh') fs.unlink(RUN + '/session.json');
            result = { ok: true, servers: map(listing().servers, public_server) };
        }
        else result = generate(ARGV[1], ARGV[2]);
    }
    else fail('Не удалось выполнить действие Proton VPN.');
}
catch (error) {
    failed = true;
    result = { error: error.message || 'Не удалось выполнить действие Proton VPN.' };
}
cleanup();
printf('%J\n', result);
exit(failed ? 1 : 0);
ZM_INSTALLER_EOF
chmod 0755 /usr/libexec/manager-proton

mkdir -p /usr/libexec
cat > /usr/libexec/manager-uninstall << 'ZM_INSTALLER_EOF'
#!/bin/sh
set -u
umask 077
mode="$1"
delay="$2"
case "$mode" in keep|wipe) ;; *) exit 1 ;; esac
case "$delay" in 1|8) ;; *) exit 1 ;; esac
lock=/tmp/manager-maintenance.lock
sleep "$delay"
[ "$(cat "$lock/pid" 2>/dev/null)" = "$$" ] || exit 1
finish() {
 if [ "$(cat "$lock/pid" 2>/dev/null)" = "$$" ]; then
  rm -f "$lock/pid"
  rmdir "$lock" 2>/dev/null || true
 fi
 rm -f "$0"
}
trap finish EXIT

# Stop only Manager's event subscriber and scheduled jobs.
if [ -x /etc/init.d/manager-watch-events ]; then
 /etc/init.d/manager-watch-events stop || exit 1
 /etc/init.d/manager-watch-events disable || exit 1
fi
root=/opt/zapret-manager-luci
cron=/etc/crontabs/root
if [ "$mode" = keep ]; then
 mkdir -p "$root/state"
 grep -F '/opt/zapret-manager-luci/backend.sh' "$cron" 2>/dev/null | grep -v '# zm-rpcd-watch$' > "$root/state/cron.saved" || true
fi
if [ -f "$cron" ]; then
 awk 'index($0,"/opt/zapret-manager-luci/backend.sh")==0 && index($0,"/usr/libexec/manager-watch.uc")==0 && index($0,"/usr/libexec/manager-compat")==0' "$cron" > "$cron.zm-remove" || exit 1
 cat "$cron.zm-remove" > "$cron" || exit 1
 rm -f "$cron.zm-remove"
 /etc/init.d/cron restart >/dev/null 2>&1 || true
fi

# Ad blocking is provided by Manager. Preserve its saved settings in keep mode.
dns_changed=""
if [ -s "$root/state/adblock/logfacility.saved" ]; then
 while IFS='|' read -r section value; do
  if [ -n "$section" ] && [ -n "$value" ] && uci -q get "dhcp.$section" >/dev/null &&
     [ -z "$(uci -q get "dhcp.$section.logfacility")" ]; then
   uci -q set "dhcp.$section.logfacility=$value" && dns_changed=1
  fi
 done < "$root/state/adblock/logfacility.saved"
 [ -z "$dns_changed" ] || uci -q commit dhcp
fi
for dir in $(sed -n 's/^conf-dir=\([^,]*\).*/\1/p' /var/etc/dnsmasq.conf.* 2>/dev/null | sort -u) /tmp/dnsmasq.d /tmp/dnsmasq.*.d; do
 for file in "$dir/zm-adblock.conf" "$dir/zm-adblock-stats.conf"; do
  if [ -f "$file" ]; then rm -f "$file"; dns_changed=1; fi
 done
done
nft delete table inet zm_adblock_free >/dev/null 2>&1 || true
nft delete table inet zm_adblock_ip >/dev/null 2>&1 || true
nft delete table inet zm_parental >/dev/null 2>&1 || true
stop_owned() {
 local pid
 pid="$(cat "$1" 2>/dev/null)"
 case "$pid" in ''|*[!0-9]*|0|1) return ;; esac
 if [ -r "/proc/$pid/cmdline" ] && tr '\000' ' ' < "/proc/$pid/cmdline" | grep -qF "$2"; then
  kill "$pid" 2>/dev/null || true
 fi
}
stop_owned /var/run/zm-adblock-free.pid /var/etc/zm-adblock-free.conf
stop_owned /tmp/zapret-manager-luci/htop.pid htop
rm -f /var/run/zm-adblock-free.pid /var/etc/zm-adblock-free.conf /var/etc/zm-adblock-free.conf.macs
[ -z "$dns_changed" ] || /etc/init.d/dnsmasq restart >/dev/null 2>&1

# The manifest contains program files, never component configurations.
manifest="$root/files.list"
[ -f "$manifest" ] || exit 1
while IFS= read -r file; do
 case "$file" in *'/../'*|*/..|*/state/*|*/backups/*) exit 1 ;; esac
 case "$file" in
  /opt/zapret-manager-luci/*|/www/zm/*|/www/zm-webui.html|/www/luci-static/resources/zapret-manager/*|/www/luci-static/resources/view/zapret-manager/*|/usr/libexec/manager-*|/usr/libexec/rpcd/manager-compat|/usr/libexec/rpcd/zapret-manager|/usr/share/luci/menu.d/luci-app-zapret-manager.json|/usr/share/rpcd/acl.d/luci-app-zapret-manager.json|/usr/share/rpcd/acl.d/manager-compat.json|/etc/init.d/manager-watch-events)
   rm -f "$file" || exit 1 ;;
  *) exit 1 ;;
 esac
done < "$manifest"
rm -rf /www/luci-static/resources/view/zapret-manager /www/luci-static/resources/zapret-manager /www/zm
rm -f /www/zm-webui.html /usr/bin/zmw /usr/bin/zms
if [ "$mode" = wipe ]; then
 rm -rf "$root"
 rm -f /lib/upgrade/keep.d/zapret-manager
else
 find "$root" -mindepth 1 -maxdepth 1 ! -name state ! -name backups -exec rm -rf {} \;
fi
uci -q delete uhttpd.zmweb && uci -q commit uhttpd
rm -f /tmp/luci-indexcache* /tmp/luci-modulecache/* 2>/dev/null
/etc/init.d/rpcd restart >/dev/null 2>&1
/etc/init.d/uhttpd restart >/dev/null 2>&1
ZM_INSTALLER_EOF
chmod 0755 /usr/libexec/manager-uninstall

mkdir -p /usr/libexec
cat > /usr/libexec/manager-watch.uc << 'ZM_INSTALLER_EOF'
#!/usr/bin/ucode
let fs = require('fs');
let bus = require('ubus').connect();
let uci = require('uci').cursor();
const DIR = '/tmp/manager-watch';
const COMPONENTS = [ 'forkop', 'nfqws2' ];
const GRACE = 60;
const COOLDOWN = 600;
const WINDOW = 1800;
const LIMIT = 3;

function own_pid() {
    return int(split(fs.readfile('/proc/self/stat') || '0', ' ')[0]);
}

function secure_dir() {
    let info = fs.lstat(DIR);
    if (info == null) {
        if (!fs.mkdir(DIR, 0700)) return false;
        info = fs.lstat(DIR);
    }
    return info?.type == 'directory' && info.uid == 0 && fs.chmod(DIR, 0700);
}

function clock() {
    return int(split(fs.readfile('/proc/uptime') || '0', ' ')[0]);
}

function read_json(path) {
    let info = fs.lstat(path);
    if (info == null || info.type != 'file' || info.size > 32768) return null;
    try { return json(fs.readfile(path)); } catch (error) { return null; }
}

function save(component, value) {
    let path = DIR + '/' + component + '.json';
    let temporary = path + '.' + own_pid();
    if (!fs.writefile(temporary, sprintf('%J\n', value))) return false;
    fs.chmod(temporary, 0600);
    if (fs.rename(temporary, path)) return true;
    fs.unlink(temporary);
    return false;
}

function run(command) {
    let pipe = fs.popen(command, 'r');
    if (pipe == null) return null;
    let output = pipe.read('all');
    let result = pipe.close();
    return result == 0 ? output : null;
}

function service(name) {
    if (bus == null) return null;
    try {
        let result = bus.call('service', 'list', { name });
        return type(result) == 'object' ? result : null;
    } catch (error) { return null; }
}

function process_alive(pid) {
    return type(pid) == 'int' && pid > 1 && fs.stat('/proc/' + pid) != null;
}

function forkop_command(command) {
    if (!uci.load('forkop')) return false;
    let config = uci.get('forkop', 'settings', 'config_path');
    if (!config || type(command) != 'array') return false;
    let option = index(command, '-c');
    return option >= 0 && command[option + 1] == config;
}

function components_busy(component, own_recovery) {
    let lock = fs.lstat('/tmp/manager-components/lock');
    if (lock != null) {
        let job = read_json('/tmp/manager-components/state.json');
        let owner = int(trim(fs.readfile('/tmp/manager-components/pid') || '0'));
        let parent = match(fs.readfile('/proc/self/status') || '', /\nPPid:\s+([0-9]+)/);
        if (!(own_recovery && job?.component == component && job.operation == 'recover' &&
              parent != null && int(parent[1]) == owner)) return true;
    }
    if (fs.lstat('/var/run/forkop/start.lock') != null ||
        fs.lstat('/var/run/forkop.reload.lock') != null ||
        fs.lstat('/var/run/forkop/ui-state/service-actions.lock') != null) return true;
    let native = run('/usr/bin/forkop get_ui_state 2>/dev/null');
    if (fs.stat('/usr/bin/forkop') != null) {
        try {
            let state = json(native);
            if (state?.service?.forkop == null || state.service.forkop.busy) return true;
        } catch (error) { return true; }
    }
    let update = read_json('/etc/nfqws-ui/nfq-update.json');
    if (!update?.job?.done && process_alive(update?.job?.pid)) return true;
    let test = read_json('/tmp/nfqws-ui-test/status.json');
    if (index([ 'starting', 'running' ], test?.state) >= 0 &&
        (process_alive(test?.pid) || (test.state == 'starting' &&
        type(test.started) == 'int' && time() - test.started >= 0 && time() - test.started < 120))) return true;
    let processes = run('ps w 2>/dev/null');
    if (processes == null) return true;
    return match(processes, /nfqws-ui-setup update|NFQWS_UI_CLI=test|apk (add|del|upgrade)|opkg (install|remove|upgrade)/) != null;
}

function native_busy(component, own_recovery) {
    let init = component == 'forkop' ? 'forkop' : 'nfqws2-keenetic';
    if (run('/etc/init.d/' + init + ' enabled 2>/dev/null') == null) return true;
    let backup_pid = int(trim(fs.readfile('/tmp/zapret-manager-luci/backup.pid') || '0'));
    if (process_alive(backup_pid) || fs.lstat('/tmp/manager-maintenance.lock') != null) return true;
    return components_busy(component, own_recovery);
}

function evidence(component) {
    if (fs.stat(component == 'forkop' ? '/usr/bin/forkop' : '/etc/init.d/nfqws2-keenetic') == null)
        return { known: true, stopped: true, failed: false };
    let name = component == 'forkop' ? 'sing-box' : 'nfqws2-keenetic';
    let state = service(name);
    if (state == null) return { known: false };
    let failed = false, running = false;
    for (let id, instance in state?.[name]?.instances ?? {}) {
        if (component == 'forkop' && !forkop_command(instance.command)) continue;
        if (instance?.running === true) running = true;
        if (instance?.running === false && instance.exit_code != null && instance.respawn == null &&
            (component == 'forkop' || instance.command?.[0] == '/usr/bin/nfqws2'))
            failed = true;
    }
    if (running) return { known: true, running: true, failed: false };
    if (component == 'forkop') {
        if (fs.stat('/var/run/forkop/sing-box-watch.planned-stop') != null)
            return { known: true, stopped: true, failed: false };
        failed ||= fs.stat(DIR + '/forkop.failed') != null ||
                   fs.stat('/var/run/forkop/start.retry') != null;
    }
    return { known: true, running: false, failed };
}

function eligible(component, reserve) {
    let observed = evidence(component);
    let record = read_json(DIR + '/' + component + '.json') || {};
    let now = clock();
    if (!observed.known) return false;
    if (observed.running || observed.stopped || !observed.failed) {
        record.since = null;
        save(component, record);
        if (component == 'forkop' && (observed.running || observed.stopped)) fs.unlink(DIR + '/forkop.failed');
        return false;
    }
    if (record.since == null || record.since > now) {
        record.since = now;
        save(component, record);
        return false;
    }
    if (now - record.since < GRACE || native_busy(component, reserve)) return false;
    let attempts = filter(record.attempts || [], value => type(value) == 'int' && value <= now && now - value < WINDOW);
    if (length(attempts) >= LIMIT || (length(attempts) && now - attempts[length(attempts) - 1] < COOLDOWN)) return false;
    if (reserve) {
        push(attempts, now);
        record.attempts = attempts;
        if (!save(component, record)) return false;
    }
    return true;
}

function listen() {
    let uloop = require('uloop');
    if (bus == null) return 1;
    uloop.init();
    uloop.signal('SIGTERM', () => uloop.end());
    let subscriber = bus.subscriber(function(event) {
        if (event?.type != 'instance.fail' || event?.data?.service != 'sing-box') return;
        if (fs.stat('/var/run/forkop/sing-box-watch.planned-stop') != null) return;
        if (fs.stat('/usr/bin/forkop') == null) return;
        if (!forkop_command(event.data.command)) return;
        let temporary = DIR + '/forkop.failed.' + own_pid();
        if (fs.writefile(temporary, '' + clock() + '\n')) {
            fs.chmod(temporary, 0600);
            fs.rename(temporary, DIR + '/forkop.failed');
        }
    }, function() { uloop.end(); });
    if (subscriber == null || !subscriber.subscribe('service')) return 1;
    uloop.run();
    return 1;
}

if (!secure_dir()) exit(1);
let command = ARGV[0];
if (command == 'components-busy') {
    try { exit(components_busy(null, false) ? 0 : 1); }
    catch (error) { exit(2); }
}
if (command == 'listen') exit(listen());
if (command == 'eligible' && index(COMPONENTS, ARGV[1]) >= 0)
    exit(eligible(ARGV[1], true) ? 0 : 1);
if (command == 'status') {
    let result = {};
    for (let component in COMPONENTS) {
        let state = evidence(component);
        result[component] = state.known && !state.stopped && (state.running || state.failed);
    }
    print(sprintf('%J\n', result));
    exit(0);
}
if (command == 'tick') {
    let lock = DIR + '/tick.lock';
    if (!fs.mkdir(lock, 0700)) {
        let owner = int(trim(fs.readfile(lock + '/pid') || '0'));
        let info = fs.lstat(lock);
        if (info?.type != 'directory' || info.uid != 0 ||
            process_alive(owner) || time() - info.mtime < 60) exit(0);
        fs.unlink(lock + '/pid');
        if (!fs.rmdir(lock) || !fs.mkdir(lock, 0700)) exit(0);
    }
    if (!fs.writefile(lock + '/pid', '' + own_pid() + '\n')) exit(1);
    for (let component in COMPONENTS)
        if (eligible(component, false))
            run('/usr/libexec/manager-compat action ' + component + ' recover 2>/dev/null');
    fs.unlink(lock + '/pid');
    fs.rmdir(lock);
    exit(0);
}
exit(1);
ZM_INSTALLER_EOF
chmod 0755 /usr/libexec/manager-watch.uc

mkdir -p /usr/libexec/rpcd
cat > /usr/libexec/rpcd/manager-compat << 'ZM_INSTALLER_EOF'
#!/bin/sh
. /usr/share/libubox/jshn.sh
case "$1" in
 list) echo '{"status":{},"action":{"component":"","operation":""},"check_updates":{}}' ;;
 call)
  read -r input
  case "$2" in
   status) exec /usr/libexec/manager-compat status ;;
   action) json_load "$input" || exit 1; json_get_var component component; json_get_var operation operation; exec /usr/libexec/manager-compat action "$component" "${operation:-update}" ;;
   check_updates) exec /usr/libexec/manager-compat check_updates ;;
   *) echo '{"error":"Unknown method"}'; exit 1 ;;
  esac ;;
esac
