case "$1" in
	list) list_methods ;;
	call)
		t="/tmp/zm-rpc.$$"
		call_method "$2" > "$t"
		sz="$(wc -c 2>/dev/null < "$t" | tr -d ' ')"
		if [ "${sz:-0}" -gt 400000 ]; then
			echo '{"error":"ответ роутера слишком большой — отменено, чтобы не перегрузить службу входа (rpcd)"}'
		else
			cat "$t"
		fi
		rm -f "$t"
		;;
	*) echo '{"error":"usage: zapret-manager {list|call <method>}"}'; exit 1 ;;
esac
ZM_INSTALLER_EOF
chmod 0755 /usr/libexec/rpcd/zapret-manager

mkdir -p /usr/share/rpcd/acl.d
cat > /usr/share/rpcd/acl.d/manager-compat.json << 'ZM_INSTALLER_EOF'
{
  "manager-compat": {
    "description": "Forkop and NFQWS2 components in Manager",
    "read": { "ubus": { "manager-compat": ["status"] } },
    "write": { "ubus": { "manager-compat": ["action", "check_updates"] } }
  }
}
