	if [ "$(_zmi_free /opt/zapret-manager-luci)" -ge "$_zmi_need" ] && cp -R "$_zmi_st/mod" "$_zmi_md.zm" 2>/dev/null && cp "$_zmi_st/backend.sh" "$_zmi_be.zm-new" 2>/dev/null; then
		_zmi_swap "$_zmi_md.zm" "$_zmi_be.zm-new"
