		_zmi_step "На флеше мало места ($(_zmi_free /opt/zapret-manager-luci) КБ) — заменяем основные файлы панели на месте"
		_zm_n=0
		while pgrep -f '/opt/zapret-manager-luci/backend[.]sh' >/dev/null 2>&1 && [ "$_zm_n" -lt 15 ]; do sleep 1; _zm_n=$((_zm_n + 1)); done
		rm -rf "$_zmi_be" "$_zmi_md" "$_zmi_md.old"
		if ! cp -R "$_zmi_st/mod" "$_zmi_md" 2>/dev/null || ! cp "$_zmi_st/backend.sh" "$_zmi_be" 2>/dev/null; then
