import { open } from 'fs';
let a = ARGV;
if (a[0] == 'enc') {
	let f = open(a[1], 'r');
	if (!f) exit(1);
	if (+a[2] > 0) f.seek(+a[2]);
	let d = f.read(+a[3]);
	f.close();
	print(d ? b64enc(d) : '');
} else if (a[0] == 'dec') {
	let f = open(a[1], 'r');
	if (!f) exit(1);
	let s = f.read('all');
	f.close();
	let d = b64dec(replace(s ?? '', /[\r\n ]/g, ''));
	if (d == null) exit(1);
	let o = open(a[2], 'w');
	if (!o) exit(1);
	o.write(d);
	o.close();
} else exit(2);
