		ui_radio_get)            "$BACKEND" ui_radio_get ;;
		ui_radio_set)            json_get_var mode mode;       "$BACKEND" ui_radio_set "$mode" ;;
		ui_radio_now)            json_get_var mode mode;       "$BACKEND" ui_radio_now "$mode" ;;
		*) echo '{"error":"unknown method"}'; return 1 ;;
	esac
}

case "$1" in
	list) list_methods ;;
	call)
		t="/tmp/zm-rpc.$$"
		call_method "$2" > "$t"
		sz="$(wc -c 2>/dev/null < "$t" | tr -d ' ')"
		if [ "${sz:-0}" -gt 400000 ]; then
			echo '{"error":"ответ роутера слишком большой — отменено, чтобы не перегрузить службу входа (rpcd)"}'
		else
			cat "$t"
		fi
		rm -f "$t"
		;;
	*) echo '{"error":"usage: zapret-manager {list|call <method>}"}'; exit 1 ;;
esac
