function toastContainer() {
	var c = document.getElementById('zm-toast-container');
	if (!c) {
		c = document.createElement('div');
		c.id = 'zm-toast-container';
		document.body.appendChild(c);
	}
	return c;
}

function toastFit() {
	var c = document.getElementById('zm-toast-container');
	if (!c) return;
	var vh = window.innerHeight, dt = vh;
	if (_dockEl && _dockEl.classList.contains('zm-dock-on')) {
		var r = _dockEl.getBoundingClientRect();
		if (r.height > 0 && r.top > 0) dt = r.top;
	}
	var room;
	if (document.body.classList.contains('zmw-body')) {
		var bot = dt < vh ? (vh - dt + 14) + 'px' : '';
		if (c.style.bottom !== bot) c.style.bottom = bot;
		room = dt - (dt < vh ? 14 : 28) - 16;
	} else {
		room = dt - 14 - c.getBoundingClientRect().top;
	}
	room = Math.max(90, Math.floor(room));
	c.style.maxHeight = room + 'px';
	while (c.children.length > 1 && c.scrollHeight > room) c.removeChild(c.firstChild);
}
window.zmToastFit = toastFit;

function toast(message, kind, duration) {
	var container = toastContainer();
	var txt = String(message == null ? '' : message);
	Array.prototype.slice.call(container.children).forEach(function(o) { if (o._zmText === txt) container.removeChild(o); });
	var el = E('div', { 'class': 'zm-toast zm-toast-' + (kind || 'info') }, [
		E('span', { 'class': 'zm-toast-icon' }),
		E('span', { 'class': 'zm-toast-text' }, [ String(message == null ? '' : message) ])
	]);
	el._zmText = txt;
	container.appendChild(el);
	toastFit();
	requestAnimationFrame(function() { el.classList.add('zm-toast-show'); });
	var hide = function() {
		el.classList.remove('zm-toast-show');
		setTimeout(function() { el.parentNode && el.parentNode.removeChild(el); }, 250);
	};
	el.addEventListener('click', hide);
	setTimeout(hide, duration || (kind === 'error' ? 14000 : 9000));
}

var _catWatching = false;

function busyToast(message, sub) {
	var container = toastContainer();
	var textEl = E('span', { 'class': 'zm-toast-main' }), subEl = E('span', { 'class': 'zm-toast-sub' });
	var el = E('div', { 'class': 'zm-toast zm-toast-busy', 'role': 'status' }, [
		E('span', { 'class': 'zm-toast-spin', 'aria-hidden': 'true' }),
		E('span', { 'class': 'zm-toast-text' }, [ textEl, subEl ])
	]);
	var closed = false;
	function put(m, s2) {
		textEl.textContent = String(m == null ? '' : m);
		subEl.textContent = s2 ? String(s2) : '';
		subEl.style.display = s2 ? '' : 'none';
	}
	put(message, sub);
	container.appendChild(el);
	toastFit();
	requestAnimationFrame(function() { el.classList.add('zm-toast-show'); });
	return {
		set: function(m, s2) {
			if (closed) return;
			put(m, s2);
			if (!el.parentNode) { toastContainer().appendChild(el); toastFit(); el.classList.add('zm-toast-show'); }
		},
		close: function() {
			if (closed) return;
			closed = true;
			el.classList.remove('zm-toast-show');
			setTimeout(function() { el.parentNode && el.parentNode.removeChild(el); }, 250);
		}
	};
}

function catalogWatch(before, done) {
	if (_catWatching) return;
	_catWatching = true;
	before = before || {};
	var tries = 0;
	function about(c) { return (c.version ? 'версия ' + c.version + ', ' : '') + 'пунктов: ' + (parseInt(c.services, 10) || 0); }
	function finish(c) {
		_catWatching = false;
		if (!c) toast('Роутер не ответил — обновился ли каталог списков, будет видно в его блоке', 'warning');
		else if (c.busy) toast('Каталог списков всё ещё обновляется — результат появится в его блоке', 'warning');
		else if (c.off) toast('Каталог списков выключен — обновлять нечего', 'warning');
		else if (c.error) toast(c.version ? 'Каталог списков не обновился — проверьте доступ к GitHub. Работает прежний: ' + about(c) : 'Каталог списков не скачался — проверьте доступ к GitHub', 'error');
		else if (before.version && String(before.version) === String(c.version) && String(before.services) === String(c.services)) toast('Каталог списков проверен — новой версии нет: ' + about(c), 'info');
		else toast('Каталог списков обновлён: ' + about(c), 'info');
		if (done) done();
