function rebootWait(note) {
	var t0 = Date.now();
	var count = E('span', { 'class': 'zm-reboot-count', 'role': 'timer', 'aria-live': 'off' }, '0:00');
	var state = E('p', { 'class': 'zm-reboot-text' }, 'Страница переподключится сама.');
	var ov = E('div', { 'class': 'zm-reboot-ov', 'role': 'dialog', 'aria-modal': 'true', 'aria-label': 'Роутер перезагружается' }, [
		E('div', { 'class': 'zm-reboot-box' }, [
			E('span', { 'class': 'zm-reboot-spin', 'aria-hidden': 'true' }),
			E('h3', { 'class': 'zm-reboot-title' }, 'Роутер перезагружается'),
			state,
			E('div', { 'class': 'zm-reboot-meta' }, [ E('span', {}, 'прошло'), count ])
		])
	]);
	document.body.appendChild(ov);
	function tick() {
		var sec = Math.round((Date.now() - t0) / 1000);
		count.textContent = Math.floor(sec / 60) + ':' + ('0' + sec % 60).slice(-2);
		if (sec >= 25) state.textContent = sec < 150 ? 'Ждём, когда роутер снова ответит…' : 'Роутер отвечает дольше обычного — подождите ещё немного.';
		if (sec < 25) { setTimeout(tick, 1000); return; }
		var ctl = window.AbortController ? new AbortController() : null;
		var tm = ctl ? setTimeout(function() { ctl.abort(); }, 4000) : 0;
		fetch(location.pathname + location.search, { cache: 'no-store', credentials: 'same-origin', signal: ctl ? ctl.signal : undefined }).then(function(r) {
			clearTimeout(tm);
			if (r.ok) location.reload(); else setTimeout(tick, 3000);
		}, function() { clearTimeout(tm); setTimeout(tick, 3000); });
	}
	tick();
}

function rebootRouter() {
	return ask('Перезагрузить роутер?\n\nИнтернет пропадёт на 1–2 минуты, потом всё поднимется само.').then(function(ok) {
		if (!ok) return Promise.resolve(false);
		return callSystemReboot().then(function(r) {
			if (r && r.error) { toast(r.error, 'error'); return false; }
			rebootWait(E('span', { 'class': 'zm-hint', 'style': 'margin:0' }));
			return true;
		}, function() { toast('Роутер не ответил', 'error'); return false; });
	});
}

function rebootBanner(text) {
	var btn = E('button', { 'class': 'cbi-button cbi-button-positive', 'click': function() {
		btn.disabled = true;
		rebootRouter().then(function(ok) { if (!ok) btn.disabled = false; });
	} }, 'Перезагрузить');
	var el = E('div', { 'class': 'zm-refresh-banner zm-show zm-reboot-banner' }, [ E('span', {}, String(text)), btn ]);
	el.appendChild(E('button', { 'type': 'button', 'class': 'zm-banner-x', 'title': 'Закрыть', 'aria-label': 'Закрыть', 'click': function() {
		el._zmWant = false;
		if (el._zmPh && el._zmPh.parentNode) el._zmPh.parentNode.removeChild(el._zmPh);
		if (el.parentNode) el.parentNode.removeChild(el);
		dockSync();
		callRebootHintClear().catch(function() {});
	} }, '×'));
	return floatBanner(el);
}

function rebootSlot() {
	var el = E('div', { 'class': 'zm-reboot-slot' });
	el.refresh = function() {};
	if (document.body.classList.contains('zmw-body')) return el;
	el.refresh = function() {
		callHealth().then(function(h) {
			el.innerHTML = '';
			clearTimeout(el._t);
			if (h && h.reboot_hint) {
				el.appendChild(rebootBanner(h.reboot_hint));
				el._t = setTimeout(el.refresh, 125000);
			}
		}).catch(function() {});
	};
	el.refresh();
	window.addEventListener('zm:changed', function() { setTimeout(el.refresh, 800); });
	return el;
}

var sysFixBusy = false;
