mkdir -p /www/luci-static/resources/view/zapret-manager
chmod 0755 /www/luci-static/resources/view/zapret-manager
cat > '/www/luci-static/resources/view/zapret-manager/dashboard.js' << 'ZM_INSTALLER_EOF'
'require rpc';
'require poll';
'use strict';
'require view';
'require ui';
'require zapret-manager.common as zm';
// The original view remains the source of its layout and controls.
function managerAdapt(definition, mode) {
 var original=definition.render;
 definition.render=function(){
  var self=this,args=arguments,result=original.apply(self,args);
  function mount(root){
   if(!root||!root.querySelectorAll)return root;
   var removed=/^(Zapret2?|Steer|Forkozz|Mixomo|ByeTube|DNS over HTTPS|DNS-over-HTTPS|DoH)$/i;
   function clean(){
    root.querySelectorAll('.zm-row,tr').forEach(function(row){
     var label=row.querySelector('.zm-label,td,th');
     if(label&&removed.test(label.textContent.trim()))row.remove();
    });
    root.querySelectorAll('.zm-card').forEach(function(card){
     var heading=card.querySelector('h2,h3');var title=heading?heading.textContent.trim():'';
    });
    root.querySelectorAll('a[href]').forEach(function(a){
     if(/(?:#\/|zapret-manager\/)(?:strategy|zapret2|steer|forkozz|mixomo|bytetube|doh)(?:$|[/?#])/.test(a.getAttribute('href')||''))a.remove();
    });
    root.querySelectorAll('a,button').forEach(function(a){
     var text=a.textContent.trim();
    });
    // Old product names in explanatory text are not routing integrations.
    var walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT),node;
    while((node=walker.nextNode())){
     if(node.parentElement&&/^(SCRIPT|STYLE|TEXTAREA|INPUT)$/.test(node.parentElement.tagName))continue;
     var old=node.nodeValue,newText=old.replace(/Forkozz или Steer|Forkozz, Steer/g,'Forkop').replace(/«Мимо Forkozz»/g,'«Напрямую»').replace(/обход Zapret/g,'обход NFQWS2');
     if(old!==newText)node.nodeValue=newText;
    }
   }
   clean();
   var paintComponentRows=null;
   new MutationObserver(function(){clean();if(paintComponentRows)paintComponentRows();}).observe(root,{subtree:true,childList:true});
   if(mode==='dashboard'){
    var componentState=rpc.declare({object:'manager-compat',method:'status',expect:{}});
    var snapshot=null,statusError=false,requestSerial=0;
    paintComponentRows=function(){
     var componentCard=Array.from(root.querySelectorAll('.zm-card')).find(function(card){
      var heading=card.querySelector('h3');return heading&&heading.textContent.trim()==='Компоненты';
     });
     if(!componentCard)return;
     var columns=componentCard.querySelectorAll('.bt-col');
     if(!columns.length){
      var empty=Array.from(componentCard.querySelectorAll('p.zm-hint')).find(function(p){return /^Пока ничего не установлено/.test(p.textContent.trim());});
      if(empty)empty.remove();
      componentCard.appendChild(E('div',{'class':'bt-cols'},[E('div',{'class':'bt-col'}),E('div',{'class':'bt-col'})]));
      columns=componentCard.querySelectorAll('.bt-col');
     }
     ['forkop','nfqws2'].forEach(function(id,index){
      var title=id==='forkop'?'Forkop':'NFQWS2',c=snapshot&&snapshot[id],column=columns[Math.min(index,columns.length-1)];
      var row=componentCard.querySelector('.manager-component-row[data-component="'+id+'"]');
      if(!row){
       row=E('div',{'class':'zm-row manager-component-row','data-component':id},[
       E('span',{'class':'zm-label'},title),E('span',{'class':'manager-component-state','aria-live':'polite'})]);
       column.insertBefore(row,column.firstChild);
      }
      var signature=JSON.stringify([c&&c.version,c&&c.running,statusError,!!snapshot]);
      if(row._managerSignature===signature)return;
      row._managerSignature=signature;
      var value=row.querySelector('.manager-component-state');
      value.style.cssText='display:inline-flex;align-items:center;gap:8px;flex-wrap:wrap';
      if(statusError||(snapshot&&!c)){
       value.replaceChildren(E('span',{'class':'zm-badge zm-warn'},'состояние недоступно'));
      }else if(!snapshot){
       value.replaceChildren(E('span',{'class':'zm-badge zm-off'},'проверяем…'));
      }else if(!c.version){
       value.replaceChildren(zm.stateBadge(0));
      }else{
      value.replaceChildren(
        typeof c.running==='boolean'?zm.badge(c.running,'работает','остановлен'):E('span',{'class':'zm-badge zm-warn'},'состояние недоступно'));
      }
     });
    };
    function refresh(){
     var serial=++requestSerial;
     return componentState().then(function(d){if(serial!==requestSerial)return;snapshot=d;statusError=false;paintComponentRows();})
      .catch(function(){if(serial!==requestSerial)return;statusError=true;paintComponentRows();});
    }
    paintComponentRows();
    refresh();poll.add(refresh,5);
   }
   return root;
  }
  return result&&typeof result.then==='function'?result.then(mount):mount(result);
 };
 return definition;
}

var E = (function(raw) { return function() { var a = Array.prototype.slice.call(arguments), i = a.length - 1; if (i >= 1 && (typeof a[i] === 'string' || typeof a[i] === 'number')) a[i] = [ String(a[i]) ]; return raw.apply(null, a); }; })(window.E);

return view.extend(managerAdapt({
	load: function() {
