        renderProton();
    });
}

function renderProton() {
    protonCard.innerHTML = '';
    protonCard.appendChild(E('h3', {}, 'Proton VPN'));
    protonCard.appendChild(E('p', { 'class': 'zm-hint', 'style': 'margin-top:-6px' },
        'Создаёт профиль Proton VPN для AmneziaWG. Используйте его ниже, чтобы создать интерфейс.'));
    protonCard.appendChild(row('Профиль', proton.ready ? badge('zm-ok', 'готов') : badge('zm-off', 'не создан')));
    if (proton.ready && proton.server) {
        protonCard.appendChild(row('Сервер', E('span', { 'style': 'overflow-wrap:anywhere' },
            [country(proton.server.country), proton.server.name].filter(Boolean).join(' · '))));
        protonCard.appendChild(E('div', { 'class': 'zm-actions' }, [
            E('button', { 'type': 'button', 'class': 'cbi-button cbi-button-positive', 'disabled': protonBusy() ? '' : null, 'click': protonUseProfile }, 'Использовать профиль'),
            E('button', { 'type': 'button', 'class': 'cbi-button', 'disabled': protonBusy() ? '' : null, 'click': protonDownload }, 'Скачать')
        ]));
    }
    if (proton.choosing) {
        var form = E('div', { 'class': 'manager-proton-form' });
        var countries = protonCountries();
        var countrySelect = E('select', { 'class': 'cbi-input-select manager-proton-select', 'aria-label': 'Страна Proton VPN', 'disabled': protonBusy() ? '' : null },
            [E('option', { 'value': '' }, 'Выберите страну')].concat(countries.map(function(value) { return E('option', { 'value': value }, country(value)); })));
        countrySelect.value = proton.country;
        countrySelect.addEventListener('change', function() { proton.country = countrySelect.value; proton.selected = ''; renderProton(); });
        var serverSelect = E('select', { 'class': 'cbi-input-select manager-proton-select', 'aria-label': 'Сервер Proton VPN', 'disabled': protonBusy() || !proton.country ? '' : null },
            [E('option', { 'value': '' }, 'Автоматически')].concat(protonServers().map(function(server) {
                return E('option', { 'value': server.id }, server.name + ' · ' + server.load + '%');
            })));
        serverSelect.value = proton.selected;
        serverSelect.addEventListener('change', function() { proton.selected = serverSelect.value; });
        form.appendChild(row('Страна', countrySelect));
        form.appendChild(row('Сервер', serverSelect));
        form.appendChild(E('div', { 'class': 'zm-actions' }, E('button', {
            'type': 'button', 'class': 'cbi-button cbi-button-positive',
            'disabled': protonBusy() || !protonServers().length ? '' : null, 'click': protonGenerate
        }, 'Создать профиль')));
        protonCard.appendChild(form);
    }
    protonCard.appendChild(E('div', { 'class': 'zm-actions' }, E('button', {
        'type': 'button', 'class': 'cbi-button', 'disabled': protonBusy() ? '' : null, 'click': protonLoadServers
    }, proton.loading ? 'Получаем серверы…' : proton.choosing ? 'Обновить серверы' : proton.ready ? 'Создать заново' : 'Выбрать страну')));
    if (proton.error) {
        protonCard.appendChild(E('p', { 'class': 'zm-hint', 'role': 'alert' }, proton.error));
        protonCard.appendChild(E('div', { 'class': 'zm-actions' }, [
            E('button', { 'type': 'button', 'class': 'cbi-button', 'click': protonUseOwn }, 'Загрузить свой файл'),
            E('a', { 'class': 'cbi-button', 'href': 'https://account.protonvpn.com/downloads', 'target': '_blank', 'rel': 'noopener noreferrer' }, 'Открыть аккаунт Proton ↗')
        ]));
    }
}


		function refresh() {
			return zm.awgStatus().then(function(res) { data = res || {}; return protonRefreshStatus().then(renderAll); }).catch(function() {});
		}

		function follow(job, action, creation) {
			busy = true;
			logEl.classList.add('zm-show');
			renderAll();
			zm.pollJob(job, logEl, function(ok) {
				busy = false;
				var msg = ok ? ({ install: 'AmneziaWG установлен', update: 'AmneziaWG переустановлен', remove: 'AmneziaWG удалён', gen: 'WARP сгенерирован',
					create: 'Интерфейс создан', pick: 'Точка входа подобрана', mihomo: 'WARP добавлен в Mihomo',
					replace: 'Конфиг применён', regen: 'Новый WARP применён', proton_generate: 'Профиль Proton VPN создан', fix: 'Туннель Steer перезапущен на новой точке входа', autofix: 'Автопочинка: туннель снова работает' }[action] || 'Готово')
					: 'Не получилось — подробности в журнале';
				zm.toast(msg, ok ? 'info' : 'error');
				if (ok && (action === 'gen' || (action === 'proton_generate' && mk.src === 'proton'))) mk.loaded = false;
				if (ok && action === 'proton_generate') proton.choosing = false;
                if (ok && action === 'create' && creation && creation.proton) {
                    var createdName = creation.name;
                    zm.awgAction('test', createdName).then(function(result) {
                        testRes[createdName] = result || {};
                        renderIfaces();
                        zm.toast(result && result.ok ? 'Соединение Proton VPN проверено' : 'Интерфейс создан, но соединение проверить не удалось. Нажмите «Проверить» в его карточке.', result && result.ok ? 'info' : 'warning');
                    }).catch(function() { zm.toast('Интерфейс создан. Проверку можно повторить в его карточке.', 'warning'); });
                }
                if (action === 'replace' || action === 'regen') Object.keys(open).forEach(function(k) { if (open[k] === 'conf') open[k] = null; });
				refresh();
			});
		}

		function job(action, mode, toastText) {
			if (busy) { zm.toast('Дождитесь окончания текущей операции', 'warning'); return Promise.resolve(false); }
			var creation = { name: String(mode || '').split('|')[0], proton: mk.src === 'proton' };
            return zm.awgAction(action, mode || '').then(function(res) {
				if (res.error) { zm.toast(res.error, 'error'); return false; }
				if (toastText) zm.toast(toastText, 'warning');
				follow(res.job || 'awg', action, creation);
				return true;
			}).catch(function() { zm.toast('Роутер не ответил', 'error'); return false; });
		}

		function steerFix(f) {
			if (busy) { zm.toast('Дождитесь окончания текущей операции', 'warning'); return; }
			var n = f.name === 'zmwarp' ? '1' : f.name.replace(/^zmwarp/, '');
			zm.steerAction('warp_fix', n).then(function(res) {
				if (res.error) { zm.toast(res.error, 'error'); return; }
				zm.toast('Подбираем точку входа для ' + f.name + ', это до пары минут', 'warning');
				follow('steer', 'fix');
			}).catch(function() { zm.toast('Роутер не ответил', 'error'); });
		}

		function quick(action, mode, okText) {
			return zm.awgAction(action, mode || '').then(function(res) {
				if (res.error) { zm.toast(res.error, 'error'); return res; }
				if (okText) zm.toast(okText, 'info');
				refresh();
				return res;
			}).catch(function() { zm.toast('Роутер не ответил', 'error'); });
		}

		function renderMain() {
			mainCard.innerHTML = '';
			mainCard.appendChild(E('h3', {}, 'AmneziaWG'));
			mainCard.appendChild(E('p', { 'class': 'zm-hint', 'style': 'margin-top:-6px' }, 'WireGuard с маскировкой: провайдеру сложнее заметить и заблокировать туннель.'));
			var inst = !!data.installed;
			mainCard.appendChild(row('Состояние', inst ? badge('zm-ok', 'установлен') : badge('zm-off', 'не установлен')));
			if (data.kmod || data.tools) {
				mainCard.appendChild(row('Пакеты', E('span', { 'style': 'overflow-wrap:anywhere' }, [
					'kmod-amneziawg ' + (data.kmod || '—') + ' · amneziawg-tools ' + (data.tools || '—') + (data.luci ? ' · ' + (data.luci_pkg || 'luci-proto') + ' ' + data.luci : '')
				])));
			}
			if (inst) {
				mainCard.appendChild(row('Модуль ядра', data.module ? badge('zm-ok', 'загружен') : badge('zm-bad', 'не загружен')));
				mainCard.appendChild(row('Поддержка в сети', data.proto ? badge('zm-ok', 'есть') : badge('zm-warn', 'нет — нажмите «Доустановить»')));
			}
			if (busy) {
				mainCard.appendChild(E('p', { 'class': 'zm-hint' }, 'Сейчас: ' + (PHASE_TEXT[data.phase] || 'идёт операция') + '… Можно закрыть страницу — роутер всё доделает сам.'));
				return;
			}
			var acts = [];
			if (!inst) acts.push(E('button', { 'class': 'cbi-button cbi-button-positive', 'click': function() {
				job('install', '', 'Устанавливаем AmneziaWG, сеть может ненадолго пропасть…');
			} }, 'Установить AmneziaWG'));
			else {
				if (!data.module || !data.proto) acts.push(E('button', { 'class': 'cbi-button cbi-button-positive', 'click': function() {
					job('install', '', 'Доустанавливаем AmneziaWG');
				} }, 'Доустановить'));
				acts.push(E('button', { 'class': 'cbi-button', 'click': function() {
					return zm.ask('Переустановить AmneziaWG?\n\nЕсли туннели работают, новый модуль заработает после перезагрузки роутера.').then(function(ok) { if (!ok) return; job('update', '', 'Переустанавливаем AmneziaWG'); });
				} }, 'Переустановить'));
				acts.push(E('button', { 'class': 'cbi-button cbi-button-remove', 'click': function() {
					var list = (data.ifaces || []).filter(function(f) { return f.owner !== 'steer'; });
					var foreign = list.filter(function(f) { return !f.owned; }).map(function(f) { return f.name; });
					var fk = list.filter(function(f) { return f.forkozz; }).map(function(f) { return f.name; });
					var blocks = [ { type: 'list', title: 'Что произойдёт', items: [
						'Пакеты AmneziaWG и модуль ядра удалятся',
						'Сохранённые конфиги туннелей удалятся'
					].concat(list.map(function(f) { return 'Туннель ' + f.name + (f.owned ? '' : ' (создан не панелью)') + ' удалится — с ключами и зоной файрвола'; })) } ];
					var nsBusy = fk.length && data.fk_name === 'NetShift';
					if (nsBusy) blocks.push({ type: 'note', kind: 'warn', text: 'Через ' + fk.join(', ') + ' сейчас работает NetShift. Панель его не трогает — сначала выберите в нём другое подключение или выключите его (Службы → NetShift).' });
					else if (fk.length) blocks.push({ type: 'note', kind: 'warn', text: 'Через ' + fk.join(', ') + ' сейчас работает Forkozz. Он будет выключен, трафик пойдёт напрямую. Его настройки останутся — потом выберите в нём другое подключение.' });
					if (foreign.length) blocks.push({ type: 'switch', id: 'all', value: false,
						label: 'Удалить и туннели, созданные не панелью: ' + foreign.join(', '),
						hint: 'Без AmneziaWG они всё равно не заработают. Не отмечено — удаление не начнётся.' });
					if (list.some(function(f) { return f.route_all && f.up; })) blocks.push({ type: 'note', text: 'Через один из туннелей сейчас идёт весь интернет роутера. После удаления он пойдёт напрямую через провайдера.' });
					zm.dialog({ title: 'Удалить AmneziaWG?', danger: true, okText: 'Удалить AmneziaWG', blocks: blocks,
						canOk: function(v) { return !nsBusy && (!foreign.length || !!v.all); }
					}).then(function(v) { if (v) job('remove', foreign.length ? 'all' : '', 'Удаляем AmneziaWG'); });
				} }, 'Удалить'));
			}
			mainCard.appendChild(E('div', { 'class': 'zm-actions' }, acts));
			if (inst && data.steer) mainCard.appendChild(E('p', { 'class': 'zm-hint' }, 'AmneziaWG нужен Steer — удаляется только вместе со Steer.'));
		}

		function epEditor(f) {
			var box = E('div', { 'style': 'margin-top:10px' });
			var eps = String(data.endpoints || '').split(' ').filter(function(x) { return x; });
			var input = E('input', { 'class': 'cbi-input-text zm-secret-in', 'type': 'text', 'placeholder': 'адрес:порт', 'value': f.endpoint || '', 'style': 'max-width:320px; width:100%' });
			box.appendChild(E('div', { 'class': 'zm-grid' }, eps.map(function(ep) {
				return E('div', { 'class': 'zm-tile' + (f.endpoint === ep ? ' zm-active' : ''), 'click': function() { input.value = ep; } }, [ E('span', { 'class': 'zm-blur' }, String(ep)) ]);
			})));
			box.appendChild(E('div', { 'class': 'zm-actions' }, [
				input,
				E('button', { 'class': 'cbi-button cbi-button-positive', 'click': function() {
					quick('endpoint', f.name + '|' + input.value.trim(), 'Точка входа сменена — туннель перезапущен').then(function(r) { if (r && r.ok) delete open[f.name]; });
				} }, 'Применить'),
				f.warp ? E('button', { 'class': 'cbi-button cbi-button-action', 'click': function() {
					job('pick', f.name, 'Подбираем точку входа, это до пары минут');
				} }, 'Подобрать') : ''
			]));
			box.appendChild(E('p', { 'class': 'zm-hint' }, f.warp ? '«Подобрать» проверит точки WARP изнутри туннеля и возьмёт самую быструю рабочую.' : 'Адрес и порт вашего сервера.'));
			return box;
		}

		function ifBlock(f) {
