			var routing = f.routing || {}, autoLabels = { enabled: 'включены', disabled: 'выключены', mixed: 'частично включены', unconfigured: 'не настроены', unknown: 'не удалось проверить' };
            box.appendChild(row('Автоматические маршруты', E('span', { 'title': 'Добавлять маршруты к адресам из конфигурации туннеля' }, autoLabels[routing.automatic] || autoLabels.unknown)));
            if (routing.forkop_error) box.appendChild(row('Используется в Forkop', E('span', {}, 'не удалось проверить')));
            else if ((routing.usage || []).length) box.appendChild(row('Используется в Forkop', managerAwgUsage(f.name, routing.usage)));
			var t = testRes[f.name];
			if (t) {
				var ti = [];
				if (t.colo) ti.push('сервер ' + t.colo + (t.city ? ' (' + t.city + ')' : ''));
				if (t.seen) ti.push('сайты видят: ' + country(t.seen));
				if (t.loss !== undefined && t.loss !== '') ti.push('потери ' + t.loss + '%' + (t.rtt ? ', ' + t.rtt + ' мс' : ''));
				if (t.warp && t.warp !== 'off') ti.push('warp=' + t.warp);
				box.appendChild(row('Проверка', t.ok
					? badge(t.torn ? 'zm-warn' : 'zm-ok', E('span', {}, [ 'выход ', zm.secret(t.ip || '?'), ti.length ? ' · ' + ti.join(' · ') : '' ]))
					: badge('zm-bad', 'через туннель ничего не открылось')));
				if (t.ok && t.torn) box.appendChild(E('p', { 'class': 'zm-hint' }, 'Связь обрывается через пару секунд — так DPI рвёт туннель. ' +
					(f.warp ? 'Подберите точку входа заново.' : 'Попробуйте другую точку входа или маску I1.')));
			}

			var acts = [
				E('button', { 'class': 'cbi-button cbi-button-action', 'click': function(ev) {
					ev.target.disabled = true;
