		function suggestName() {
			var names = {}; (data.ifaces || []).forEach(function(f) { names[f.name] = true; });
			var base = mk.src === 'warp' ? 'warp' : mk.src === 'proton' ? 'proton' : 'awg', n = 0, nm = base;
			while (names[nm]) { n++; nm = base + n; }
			return nm;
		}

		function renderNew() {
			newCard.innerHTML = '';
			newCard.appendChild(E('h3', {}, 'Создать интерфейс'));
			if (!data.installed) {
				newCard.appendChild(E('p', { 'class': 'zm-hint' }, 'Сначала установите AmneziaWG.'));
				return;
			}
			newCard.appendChild(E('p', { 'class': 'zm-hint', 'style': 'margin-top:-6px' }, 'Из готового профиля или своего файла AmneziaWG / WireGuard. Появится в «Сеть → Интерфейсы».'));
			var srcs = [ { id: 'warp', name: 'WARP.conf' }, { id: 'own', name: 'Свой .conf' } ];
			if (!data.warp_conf) srcs.shift();
            if (proton.ready) srcs.splice(srcs.length - 1, 0, { id: 'proton', name: 'Proton.conf' });
            if (!proton.ready && mk.src === 'proton') mk.src = 'own';
			if (!data.warp_conf && mk.src === 'warp') mk.src = 'own';
			var sourceRow = row('Конфиг', seg(srcs, mk.src, function(id) { mk.src = id; mk.request = (mk.request || 0) + 1; mk.loaded = false; mk.name = ''; mk.text = ''; mk.showConfig = false; mk.error = ''; renderNew(); })); sourceRow.classList.add('manager-awg-config-source'); newCard.appendChild(sourceRow);

            var generated = mk.src === 'warp' || mk.src === 'proton';
            if (generated && !mk.loaded) {
                mk.loaded = true;
                mk.loading = true;
                mk.text = '';
                mk.error = '';
                var loadingSource = mk.src;
                mk.request = (mk.request || 0) + 1;
                var request = mk.request;
                zm.awgAction(mk.src === 'proton' ? 'proton_config' : 'conf_get', '').then(function(result) {
                    if (mk.src !== loadingSource || mk.request !== request) return;
                    if (!result || result.error || !result.content) {
                        mk.error = (result && result.error) || 'Не удалось открыть профиль. Попробуйте ещё раз.';
                    } else mk.text = result.content;
                    mk.loading = false;
                    renderNew();
                }).catch(function() {
                    if (mk.src !== loadingSource || mk.request !== request) return;
                    mk.loading = false;
