                    renderNew();
                });
            }
            if (mk.src === 'own' && !mk.loaded) { mk.loaded = true; mk.loading = false; mk.text = ''; }
            if (mk.loading) newCard.appendChild(E('p', { 'class': 'zm-hint', 'role': 'status' }, 'Открываем профиль…'));
            if (mk.error) newCard.appendChild(E('p', { 'class': 'zm-hint', 'role': 'alert' }, mk.error));
            if (mk.error && generated) newCard.appendChild(E('button', {
                'class': 'cbi-button', 'type': 'button', 'click': function() { mk.loaded = false; renderNew(); }
            }, 'Повторить'));
            if (generated && !mk.loading && !mk.error) {
                newCard.appendChild(E('p', { 'class': 'zm-hint' }, mk.src === 'proton' && proton.server
                    ? [country(proton.server.country), proton.server.name].filter(Boolean).join(' · ')
                    : 'Профиль WARP готов.'));
                newCard.appendChild(E('button', {
                    'class': 'cbi-button', 'type': 'button', 'aria-expanded': mk.showConfig ? 'true' : 'false',
                    'click': function() { mk.showConfig = !mk.showConfig; renderNew(); }
                }, mk.showConfig ? 'Скрыть конфиг' : 'Посмотреть конфиг'));
            }
            if (mk.src === 'own') {
                var fileInput = E('input', { 'type': 'file', 'accept': '.conf,text/plain', 'style': 'display:none' });
                fileInput.addEventListener('change', function() {
                    var file = fileInput.files && fileInput.files[0];
                    if (!file) return;
                    if (file.size > 65536) { zm.toast('Файл слишком большой. Выберите конфигурацию одного подключения.', 'warning'); return; }
                    var reader = new FileReader();
                    mk.request = (mk.request || 0) + 1;
                    var uploadRequest = mk.request;
                    reader.onload = function() {
                        if (mk.src !== 'own' || mk.request !== uploadRequest) return;
                        mk.text = String(reader.result || '').replace(/\r/g, '');
