                    };
                    reader.onerror = function() {
                        if (mk.src === 'own' && mk.request === uploadRequest) zm.toast('Не удалось прочитать файл. Попробуйте ещё раз.', 'error');
                    };
                    reader.readAsText(file);
                });
                newCard.appendChild(fileInput);
                newCard.appendChild(E('button', { 'class': 'cbi-button', 'type': 'button', 'click': function() { fileInput.click(); } }, 'Загрузить файл'));
