@media (max-width: 640px) { .zm-sp-pay { flex: 1 1 100%; padding: 12px 16px 12px 12px; gap: 14px; } .zm-sp-qr svg { width: 104px; height: 104px; } .zm-sp-pay-t b { font-size: 18px; } }
.zm-th-group { margin-top: 16px; }
