.zm-zp-stat { margin-top: 12px; font-size: 13px; font-weight: 500; }
.zm-zp-stat:empty { display: none; }
.zm-zp-stat-ok { color: #1a7f37; }
.zm-zp-stat-info { color: #1a6fb8; }
.zm-zp-stat-muted { opacity: .65; }
html.zm-theme-dark .zm-zp-stat-ok { color: #3fb950; }
html.zm-theme-dark .zm-zp-stat-info { color: #79b8ff; }
@media (max-width: 600px) { .zm-zp-head .zm-zp-badge { order: 3; } }
html.zm-theme-dark .zm-zp-badge-sync, html.zm-theme-dark .zm-zp-s, html.zm-theme-dark .zm-zp-info { color: #79b8ff; }
html.zm-theme-dark .zm-zp-badge-sync, html.zm-theme-dark .zm-zp-s { background: rgba(88,166,255,.15); }
html.zm-theme-dark .zm-zp-info { background: rgba(88,166,255,.08); border-color: rgba(88,166,255,.26); }
html.zm-theme-dark .zm-zp-badge-man, html.zm-theme-dark .zm-zp-warn { color: #e3b341; }
html.zm-theme-dark .zm-zp-badge-man { background: rgba(210,153,34,.16); }
html.zm-theme-dark .zm-zp-warn { background: rgba(210,153,34,.09); border-color: rgba(210,153,34,.3); }
html.zm-theme-dark .zm-zp-ok { color: #3fb950; background: rgba(63,185,80,.08); border-color: rgba(63,185,80,.26); }
html.zm-theme-dark .zm-zp-lg-s::before { background: rgba(88,166,255,.4); }
html.zm-theme-dark .zm-zp-err { color: #ff7b72; }
@media (max-width: 640px) {
	.zm-zp-proto { padding: 9px 10px 11px; }
	.zm-zp-man { grid-template-columns: 1fr; gap: 4px; }
	.zm-zp-man .zm-zp-tag { justify-self: start; margin-top: 6px; }
	.zm-zp-add input.cbi-input-text { width: 112px; }
	.zm-zp-note .cbi-button { flex: 1 1 auto; }
}
.zm-ev-head { display: flex; align-items: baseline; gap: 10px; flex-wrap: wrap; margin-bottom: 10px; }
.zm-ev-head h3 { margin: 0; }
.zm-ev-list { display: flex; flex-direction: column; }
.zm-ev { display: grid; grid-template-columns: 10px 116px 1fr; align-items: baseline; gap: 4px 12px; padding: 7px 2px; font-size: 13px; line-height: 1.45; border-top: 1px solid rgba(127,127,127,.14); }
.zm-ev:first-child { border-top: 0; }
.zm-ev-dot { width: 8px; height: 8px; border-radius: 50%; background: #57606a; align-self: center; }
.zm-ev-ok .zm-ev-dot { background: #1a7f37; }
.zm-ev-warn .zm-ev-dot { background: #bf8700; }
.zm-ev-time { font-size: 12px; opacity: .6; white-space: nowrap; font-variant-numeric: tabular-nums; }
.zm-ev-msg { min-width: 0; overflow-wrap: anywhere; }
.zm-ev-warn .zm-ev-msg { font-weight: 600; }
.zm-ev-n { display: inline-block; margin-left: 8px; padding: 0 7px; border-radius: 999px; font-size: 11px; font-weight: 700; background: rgba(127,127,127,.16); vertical-align: 1px; }
html.zm-theme-dark .zm-ev-ok .zm-ev-dot { background: #3fb950; }
html.zm-theme-dark .zm-ev-warn .zm-ev-dot { background: #d29922; }
html.zm-theme-dark .zm-ev-dot { background: #8b949e; }
.zm-oom-banner a.cbi-button { text-decoration: none; display: inline-flex; align-items: center; }
@media (max-width: 560px) {
	.zm-ev { grid-template-columns: 10px 1fr; }
	.zm-ev-time { grid-column: 2; }
	.zm-ev-msg { grid-column: 2; }
}
html { --zm-l-sel: #1a7f37; --zm-l-ink: #ffffff; --zm-l-bg: #ffffff; }
html.zm-theme-dark { --zm-l-sel: #2ea043; --zm-l-bg: #1e1e1e; }
body:not(.zmw-body) :is(.zm-node.zm-active, .zm-tile.zm-active, .zm-node.zm-node-live) { position: relative; }
body:not(.zmw-body) :is(.zm-node.zm-active:not(.zm-sec-add), .zm-tile.zm-active)::after {
	content: ''; position: absolute; z-index: 2; top: -8px; right: -8px; width: 20px; height: 20px; border-radius: 50%; box-sizing: border-box;
	background: var(--zm-l-sel); box-shadow: 0 0 0 3px var(--zm-l-bg); pointer-events: none;
}
body:not(.zmw-body) :is(.zm-node.zm-active:not(.zm-sec-add), .zm-tile.zm-active)::before {
	content: '' !important; display: block !important; position: absolute; z-index: 3; top: -3px; right: -1px; width: 4px; height: 8px; margin: 0; padding: 0; background: none;
	border: solid var(--zm-l-ink); border-width: 0 2.2px 2.2px 0; transform: rotate(45deg); pointer-events: none;
}
html.zm-theme-dark body:not(.zmw-body) :is(.zm-node.zm-active, .zm-tile.zm-active, .zm-tt-tile.zm-tt-active) {
	border-color: var(--zm-l-sel) !important;
	background: rgba(46,160,67,.18) !important;
	box-shadow: inset 0 0 0 1px var(--zm-l-sel), 0 0 0 4px rgba(46,160,67,.22) !important;
}
html.zm-theme-dark body:not(.zmw-body) .zm-svc.zm-svc-on { border-color: rgba(26,163,255,.75); background: rgba(26,163,255,.13); }
body:not(.zmw-body) .zm-node.zm-node-live:not(.zm-active) { border: 1px dashed var(--zm-l-sel); background: rgba(46,160,67,.07); }
body:not(.zmw-body) .zm-node.zm-node-live:not(.zm-active)::after {
	content: 'сейчас'; position: absolute; z-index: 2; top: -9px; right: 10px; padding: 0 8px; border-radius: 999px; pointer-events: none;
	font-size: 10.5px; font-weight: 700; line-height: 17px; background: var(--zm-l-sel); color: var(--zm-l-ink); box-shadow: 0 0 0 3px var(--zm-l-bg);
}

/* Keep time and date together; actions occupy a deliberate second row. */
#tabmenu:has(a[href*="zapret-manager"]) { max-width:1100px !important; width:100%; box-sizing:border-box; }
.cbi-tabmenu:has(a[href*="zapret-manager"]) { max-width:1100px; box-sizing:border-box; display:flex; flex-wrap:wrap; align-items:center; gap:4px; padding:8px; }
.cbi-tabmenu:has(a[href*="zapret-manager"]) > li { margin:0 !important; padding:0; }
.cbi-tabmenu:has(a[href*="zapret-manager"]) > li > a { margin:0 !important; }
.zm-ow-jump { display:flex; flex-wrap:wrap; align-items:center; gap:8px; margin:0; padding:0; }
.zm-ow-jump .zm-ow-chip { margin:0 !important; box-sizing:border-box; }
.manager-awg-interface > .zm-row { display:grid; grid-template-columns:168px minmax(0,1fr); gap:6px 14px; align-items:start; line-height:1.45; }
.manager-awg-interface > .zm-row > .zm-label { min-width:0 !important; width:auto !important; white-space:normal; }
.manager-awg-interface > .zm-row > :last-child { min-width:0; overflow-wrap:anywhere; }
.manager-awg-usage, .manager-awg-sections { display:flex; flex-wrap:wrap; align-items:baseline; gap:4px 10px; min-width:0; }
.manager-awg-sections { display:contents; }
.manager-awg-section { max-width:100%; white-space:normal; overflow-wrap:anywhere; }
.manager-awg-section-off { opacity:.65; }
.manager-awg-config-source { display:flex; align-items:center; gap:12px; }
.manager-awg-config-source > .zm-label { min-width:0 !important; width:auto !important; flex:0 0 auto; }
.manager-awg-config-source > .zm-seg { margin:0; }
.manager-awg-config-source .zm-seg-item { margin:0 !important; }
.manager-awg-usage .manager-awg-more { appearance:none; border:0; border-radius:0; background:transparent; color:var(--primary-color,#1aa3ff); font:inherit; font-size:12px; line-height:inherit; min-height:0; height:auto; width:auto; padding:0; margin:0 !important; box-shadow:none; cursor:pointer; text-decoration:underline; text-underline-offset:2px; }
@media (max-width:480px) { .manager-awg-interface > .zm-row { grid-template-columns:minmax(0,42%) minmax(0,1fr); gap:6px 10px; } }
html:has(link[href*="/proton2025/"]) .zm-ow-check input[type="checkbox"] { width:44px; height:24px; flex-shrink:0; }
@media (max-width: 900px) {
 .zm-ow-clock { display:grid; grid-template-columns:auto minmax(0,1fr); gap:12px 16px; }
 .zm-ow-clock .zm-ow-clock-btns { grid-column:1 / -1; margin:0; width:100%; display:flex; justify-content:flex-start; gap:8px; }
 .zm-ow-clock .zm-ow-clock-btns .cbi-button { flex:0 1 auto; min-width:0; white-space:normal; height:auto; }
}

.manager-proton-select { width:100%; min-width:0; max-width:100%; box-sizing:border-box; }
.manager-proton-form > .zm-row { display:grid; grid-template-columns:90px minmax(0,1fr); gap:10px; align-items:center; }
.manager-proton-form > .zm-row > .zm-label { width:auto; min-width:0; }
.manager-proton-form .zm-actions { margin-top:12px; }
