#zmw-view .zm-lk-prev .zm-swrow { margin-top: 12px; }
#zmw-view .zm-lk-log { margin: 14px 0 0; display: block; white-space: pre-wrap; font-size: 12px; min-height: 0; max-height: none; height: auto; }
#zmw-view .zm-lk-cur { display: flex; align-items: center; gap: 12px 16px; flex-wrap: wrap; padding: 14px 16px !important; }
#zmw-view .zm-lk-main > .zm-lk-cur + .zm-card { margin-top: 14px; }
#zmw-view .zm-lk-cur-pv { position: relative; display: block; width: 64px; height: 44px; flex-shrink: 0; border-radius: 10px; overflow: hidden; box-shadow: 0 0 0 1px color-mix(in srgb, var(--text) 14%, transparent); }
#zmw-view .zm-lk-cur-pv i { position: absolute; left: 0; top: 0; bottom: 0; width: 16px; border-right: 1px solid rgba(127,127,127,.2); }
#zmw-view .zm-lk-cur-pv b { position: absolute; left: 24px; top: 10px; width: 22px; height: 7px; border-radius: 4px; }
#zmw-view .zm-lk-cur-pv u { position: absolute; left: 24px; top: 23px; width: 32px; height: 5px; border-radius: 3px; opacity: .3; text-decoration: none; }
#zmw-view .zm-lk-cur-t { flex: 1 1 220px; min-width: 0; display: flex; flex-direction: column; gap: 3px; }
#zmw-view .zm-lk-cur-t b { font-size: 15px; font-weight: 650; line-height: 1.25; }
#zmw-view .zm-lk-cur-t small { font-size: 12.5px; line-height: 1.4; color: var(--muted); }
#zmw-view .zm-lk-cur-chg .zm-lk-cur-t small { color: var(--text-2); }
#zmw-view .zm-lk-cur-chg { box-shadow: inset 3px 0 0 var(--a1); }
#zmw-view .zm-lk-cur-act { display: flex; align-items: center; gap: 8px; flex-wrap: wrap; }
#zmw-view .zm-lk-base { display: inline-flex; align-items: center; gap: 8px; margin: 0; font-size: 13px; color: var(--muted); }
#zmw-view .zm-lk-base select { min-width: 150px; }
#zmw-view .zm-lk-pv { position: relative; }
#zmw-view .zm-lk-pv-my { position: absolute; right: 6px; bottom: 6px; display: grid; place-items: center; width: 22px; height: 22px; border-radius: 50%; background: var(--a1); color: var(--zm-on, #fff); text-decoration: none; box-shadow: 0 2px 6px rgba(0,0,0,.25); }
#zmw-view .zm-lk-pv-my svg { width: 13px; height: 13px; }
#zmw-view .zm-lk-th-new:not(.zm-active) { border-style: dashed; }
#zmw-view .zm-lk-th-new .zm-lk-pv { opacity: .55; }
#zmw-view .zm-lk-pvtiles { display: grid; grid-template-columns: 1fr 1fr; gap: 8px; margin-top: 12px; }
#zmw-view .zm-lk-pvtiles .zm-tile { min-height: 0; padding: 8px 10px; font-size: 13px; cursor: default; }
@media (max-width: 700px) { #zmw-view .zm-lk-tabs.zmw-tabs > :last-child:nth-child(odd) { grid-column: 1 / -1; } #zmw-view .zm-lk-cur-act { width: 100%; } #zmw-view .zm-lk-cur-act > * { flex: 1 1 auto; } #zmw-view .zm-lk-base select { min-width: 0; flex: 1; } }
html[data-theme] { --zm-sel: var(--a1, #2d5bff); --zm-sel-ink: #ffffff; --zm-sel-ring: var(--bg, #ffffff); }
html[data-theme="retro"] { --zm-sel-ring: #d4d0c8; }
html[data-theme="oled"], html[data-theme="matrix"], html[data-theme="neon"], html[data-theme="noir"], html[data-theme="graphite"], html[data-theme="depth"], html[data-theme="contrast"], html[data-theme="ink"] { --zm-sel-ink: #06080d; }
html[data-theme] #zmw-view :is(.zm-node.zm-active, .zm-tile.zm-active, .zm-node.zm-node-live) { position: relative; }
html[data-theme] #zmw-view :is(.zm-node.zm-active:not(.zm-sec-add), .zm-tile.zm-active)::after {
	content: ''; position: absolute; z-index: 2; top: -8px; right: -8px; width: 20px; height: 20px; border-radius: 50%; box-sizing: border-box;
	background: var(--zm-sel); box-shadow: 0 0 0 3px var(--zm-sel-ring), 0 3px 8px -2px color-mix(in srgb, var(--zm-sel) 70%, transparent); pointer-events: none;
}
html[data-theme] #zmw-view :is(.zm-node.zm-active:not(.zm-sec-add), .zm-tile.zm-active)::before {
	content: '' !important; display: block !important; position: absolute; z-index: 3; top: -3px; right: -1px; width: 4px; height: 8px; margin: 0; padding: 0; background: none;
	border: solid var(--zm-sel-ink); border-width: 0 2.2px 2.2px 0; transform: rotate(45deg); pointer-events: none;
}
html.zm-theme-dark[data-theme] #zmw-view :is(.zm-node.zm-active, .zm-tile.zm-active, .zm-tt-tile.zm-tt-active) {
	border-color: var(--zm-sel) !important;
	background: color-mix(in srgb, var(--zm-sel) 17%, transparent) !important;
	color: var(--text) !important;
	box-shadow: inset 0 0 0 1px var(--zm-sel), 0 0 0 4px color-mix(in srgb, var(--zm-sel) 20%, transparent), 0 12px 26px -16px color-mix(in srgb, var(--zm-sel) 75%, transparent) !important;
}
html.zm-theme-dark[data-theme] #zmw-view :is(.zm-node.zm-active, .zm-tile.zm-active) :is(.zm-node-name, b, strong) { color: var(--text) !important; }
html.zm-theme-dark[data-theme] #zmw-view .zm-svc.zm-svc-on { border-color: color-mix(in srgb, var(--zm-sel) 70%, transparent) !important; background: color-mix(in srgb, var(--zm-sel) 11%, transparent) !important; }
html.zm-theme-dark[data-theme] #zmw-view .zm-route-chip.zm-route-chip-on { background: var(--zm-sel) !important; border-color: var(--zm-sel) !important; color: var(--zm-sel-ink) !important; }
html.zm-theme-dark[data-theme] #zmw-view .zm-node.zm-node-live:not(.zm-active) {
	border: 1px dashed var(--zm-sel) !important;
	background: color-mix(in srgb, var(--zm-sel) 8%, transparent) !important;
}
html[data-theme] #zmw-view .zm-node.zm-node-live:not(.zm-active) { border-style: dashed; border-color: var(--zm-sel); }
html[data-theme] #zmw-view .zm-node.zm-node-grp:not(.zm-active) { box-shadow: inset 3px 0 0 var(--zm-sel); }
html[data-theme] #zmw-view .zm-node.zm-node-live:not(.zm-active)::after {
	content: 'сейчас'; position: absolute; z-index: 2; top: -9px; right: 10px; padding: 0 8px; border-radius: 999px; pointer-events: none;
	font-size: 10.5px; font-weight: 700; line-height: 17px; letter-spacing: .02em; text-transform: none;
	background: var(--zm-sel); color: var(--zm-sel-ink); box-shadow: 0 0 0 3px var(--zm-sel-ring);
}
html[data-theme] #zmw-view .zm-tt-tile.zm-tt-active { border-color: var(--zm-sel); box-shadow: inset 0 0 0 1px var(--zm-sel); }
html[data-zm-motion="0"] #zmw-view .zm-node.zm-active, html[data-zm-motion="0"] #zmw-view .zm-tile.zm-active { transition: none; }
ZM_INSTALLER_EOF
cat > '/www/zm-webui.html' << 'ZM_INSTALLER_EOF'
<!doctype html>
<html lang="ru" data-theme="micro">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width, initial-scale=1, viewport-fit=cover">
<meta name="theme-color" content="#f3f5fa">
<meta name="robots" content="noindex, nofollow">
<title>Zapret Manager</title>
<link rel="icon" href="data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%201250%201250%27%3E%3Cdefs%3E%3ClinearGradient%20id=%27z%27%20x1=%270%27%20y1=%270%27%20x2=%270%27%20y2=%271%27%3E%3Cstop%20offset=%270%27%20stop-color=%27%2300b6ff%27/%3E%3Cstop%20offset=%271%27%20stop-color=%27%230090ff%27/%3E%3C/linearGradient%3E%3C/defs%3E%3Cg%20fill=%27url%28%23z%29%27%20stroke=%27%230a0a0a%27%20stroke-width=%2722%27%20stroke-linejoin=%27miter%27%3E%3Cpolygon%20points=%27455,170%201072,118%201215,25%20688,615%2025,1235%20735,338%20262,383%27/%3E%3Cpolygon%20points=%271025,462%20722,860%201215,800%201005,1022%20315,1095%27/%3E%3C/g%3E%3C/svg%3E">
<link rel="apple-touch-icon" href="data:image/svg+xml,%3Csvg%20xmlns=%27http://www.w3.org/2000/svg%27%20viewBox=%270%200%201250%201250%27%3E%3Cdefs%3E%3ClinearGradient%20id=%27z%27%20x1=%270%27%20y1=%270%27%20x2=%270%27%20y2=%271%27%3E%3Cstop%20offset=%270%27%20stop-color=%27%2300b6ff%27/%3E%3Cstop%20offset=%271%27%20stop-color=%27%230090ff%27/%3E%3C/linearGradient%3E%3C/defs%3E%3Cg%20fill=%27url%28%23z%29%27%20stroke=%27%230a0a0a%27%20stroke-width=%2722%27%20stroke-linejoin=%27miter%27%3E%3Cpolygon%20points=%27455,170%201072,118%201215,25%20688,615%2025,1235%20735,338%20262,383%27/%3E%3Cpolygon%20points=%271025,462%20722,860%201215,800%201005,1022%20315,1095%27/%3E%3C/g%3E%3C/svg%3E">
<link rel="stylesheet" href="/zm/app.css?v=3206694013734318">
<script>
(function(){try{var h=document.documentElement,t=null,b=null,re=/^(micro|light|dark|ink|bento|retro|depth|graphite|oled|matrix|neon|synth|noir|contrast|metro|custom)$/,bre=/^(micro|light|dark|ink|bento|retro|depth|graphite|oled|matrix|neon|synth|noir|contrast|metro)$/;function fix(v){v=String(v||'').trim();return v==='blocks'?'contrast':v==='minimal'?'micro':v;}function get(u){try{var x=new XMLHttpRequest();x.open('GET',u+'?t='+Date.now(),false);x.send(null);return x.status===200?String(x.responseText||''):'';}catch(e){return '';}}var v=fix(get('/zm/theme.txt'));if(re.test(v)){t=v;try{localStorage.setItem('zmw.theme',v);}catch(e){}}if(!t){try{t=fix(localStorage.getItem('zmw.theme')||sessionStorage.getItem('zmw.theme'));}catch(e){}}if(!re.test(t||''))t='micro';if(t==='custom'){var j=null;try{j=JSON.parse(get('/zm/look.json')||'null');}catch(e){}if(!j||!j.my){try{j=JSON.parse(localStorage.getItem('zmw.look')||'null');}catch(e){}}b=j&&j.my&&bre.test(j.my.b||'')?j.my.b:'micro';}else b=t;h.setAttribute('data-theme',b);if(/^(dark|depth|graphite|oled|matrix|neon|synth|noir|contrast)$/.test(b))h.classList.add('zm-theme-dark');}catch(e){}})();
</script>
</head>
<body class="zmw-body">
<div id="zmw-root"></div>
<noscript><p style="padding:24px;font-family:sans-serif">Для работы панели Zapret Manager нужен JavaScript.</p></noscript>
<script src="/zm/app.js?v=3206694013734318"></script>
</body>
</html>
ZM_INSTALLER_EOF
ZMW_BUILD="$(date +%s)"
sed -i "s/__ZMW_BUILD__/$ZMW_BUILD/g" /www/zm/app.js /www/zm/app.css /www/zm-webui.html
chmod 0644 /www/zm/app.js /www/zm/app.css /www/zm-webui.html
mkdir -p /etc/crontabs 2>/dev/null || true
[ -f /etc/crontabs/root ] || : > /etc/crontabs/root 2>/dev/null || true
sed -i '/# zm-rpcd-watch$/d' /etc/crontabs/root 2>/dev/null || true
if [ -s /opt/zapret-manager-luci/state/cron.saved ]; then
	while IFS= read -r _zm_l; do
		[ -n "$_zm_l" ] || continue
		case "$_zm_l" in
            *'/opt/zapret-manager-luci/backend.sh '*) ;;
            *) continue ;;
        esac
        _zm_cmd="${_zm_l#*/opt/zapret-manager-luci/backend.sh }"
        case "${_zm_cmd%% *}" in
            zm_watch|versions_cron|autoupd_run|zm_cleanup|adblock_cron|adblock_stats_tick|tg_auto_tick|awg_action|tsc_watch|tsc_lan_ip|owrt_reboot_run|pc_tick) ;;
            *) continue ;;
        esac
		grep -qxF "$_zm_l" /etc/crontabs/root 2>/dev/null || echo "$_zm_l" >> /etc/crontabs/root
	done < /opt/zapret-manager-luci/state/cron.saved
	rm -f /opt/zapret-manager-luci/state/cron.saved
	_zmi_ok "Расписание панели восстановлено из сохранённых настроек"
fi
if [ -f /opt/zapret-manager-luci/state/watch.off ]; then
	_zmi_ok "Фоновые проверки выключены в «Системе» — сторож панели не включаем"
else
	_zm_wl="$(/opt/zapret-manager-luci/backend.sh watch_cron_line 2>/dev/null | head -n 1)"
	case "$_zm_wl" in *' # zm-rpcd-watch') ;; *) _zm_wl='*/2 * * * * /opt/zapret-manager-luci/backend.sh zm_watch >/dev/null 2>&1 # zm-rpcd-watch' ;; esac
	echo "$_zm_wl" >> /etc/crontabs/root 2>/dev/null || true
fi
ZM_NO_CRON_RESTART=1 /opt/zapret-manager-luci/backend.sh versions_cron_sync >/dev/null 2>&1 || true
case "$(uci -q get system.@system[0].cronloglevel)" in
	''|5|8)
	uci -q set system.@system[0].cronloglevel='9' && uci -q commit system ;;
esac
if [ -x /etc/init.d/cron ]; then
	/etc/init.d/cron enable >/dev/null 2>&1 || true
	/etc/init.d/cron restart >/dev/null 2>&1 || true
fi
if [ -s /opt/zapret-manager-luci/state/ui.theme ]; then
	case "$(cat /opt/zapret-manager-luci/state/ui.theme 2>/dev/null)" in minimal) echo micro > /opt/zapret-manager-luci/state/ui.theme ;; blocks) echo contrast > /opt/zapret-manager-luci/state/ui.theme ;; esac
	cp -f /opt/zapret-manager-luci/state/ui.theme /www/zm/theme.txt 2>/dev/null || true
	chmod 0644 /www/zm/theme.txt 2>/dev/null || true
fi
if [ -s /opt/zapret-manager-luci/state/ui.look ]; then
	cp -f /opt/zapret-manager-luci/state/ui.look /www/zm/look.json 2>/dev/null || true
	chmod 0644 /www/zm/look.json 2>/dev/null || true
fi

_zmi_ok "Файлы Web UI записаны"
ZMW_OK=1
ZMW_P=7788
if [ -s /opt/zapret-manager-luci/state/webui ]; then
	_zm_p="$(sed -n 's/^port=\([0-9][0-9]*\)$/\1/p' /opt/zapret-manager-luci/state/webui | head -n 1)"
	[ -n "$_zm_p" ] && [ "${#_zm_p}" -le 5 ] && [ "$_zm_p" -ge 1 ] 2>/dev/null && [ "$_zm_p" -le 65535 ] && ZMW_P="$_zm_p"
	grep -qx 'on=0' /opt/zapret-manager-luci/state/webui && ZMW_OK=2
fi
if [ "$ZMW_OK" = 2 ]; then
	_zmi_say "Web UI выключен в «Система» — оставляем выключенным"
	mv -f /www/zm-webui.html /opt/zapret-manager-luci/state/webui.html 2>/dev/null || true
	if uci -q get uhttpd.zmweb >/dev/null; then uci -q delete uhttpd.zmweb; uci commit uhttpd; fi
else
	_zmi_say "Включаем Web UI"
	rm -f /opt/zapret-manager-luci/state/webui.html
fi
if [ "$ZMW_OK" = 2 ]; then
	:
elif [ ! -f /etc/config/uhttpd ]; then
	ZMW_OK=0
elif [ ! -e /usr/lib/uhttpd_ubus.so ]; then
	_zmi_pkg uhttpd-mod-ubus "Web UI без него не откроется, панель в LuCI работает." || true
	[ -e /usr/lib/uhttpd_ubus.so ] || ZMW_OK=0
fi
if [ "$ZMW_OK" != 1 ]; then
	:
elif ! uci -q get uhttpd.zmweb >/dev/null; then
	uci set uhttpd.zmweb=uhttpd
	uci add_list uhttpd.zmweb.listen_http="0.0.0.0:$ZMW_P"
	uci add_list uhttpd.zmweb.listen_http="[::]:$ZMW_P"
	uci set uhttpd.zmweb.home='/www'
	uci set uhttpd.zmweb.index_page='zm-webui.html'
	uci set uhttpd.zmweb.ubus_prefix='/ubus'
	uci set uhttpd.zmweb.no_dirlists='1'
	uci set uhttpd.zmweb.rfc1918_filter='1'
	uci set uhttpd.zmweb.max_requests='12'
	uci set uhttpd.zmweb.max_connections='100'
	uci set uhttpd.zmweb.script_timeout='120'
	uci set uhttpd.zmweb.network_timeout='30'
	uci set uhttpd.zmweb.http_keepalive='20'
	uci set uhttpd.zmweb.tcp_keepalive='1'
	uci commit uhttpd
fi
if [ "$ZMW_OK" = 1 ] && uci -q get uhttpd.zmweb.listen_https | grep -q ':7789'; then
	uci -q delete uhttpd.zmweb.listen_https
	uci -q delete uhttpd.zmweb.cert
	uci -q delete uhttpd.zmweb.key
	uci -q delete uhttpd.zmweb.redirect_https
	uci commit uhttpd
fi
rm -f /www/zm/https.txt


case "$(/opt/zapret-manager-luci/backend.sh mem_heal 2>/dev/null || true)" in
	*'"patched":true,"low":true'*) _zmi_ok "TG WS Proxy: включён мягкий лимит памяти — роутеру с малым ОЗУ проще, сработает при их следующем запуске" ;;
esac

if [ -n "$_zm_old_ver" ] && [ "$_zm_old_ver" != "$ZM_NEW_VER" ]; then
	mkdir -p /opt/zapret-manager-luci/state
	echo "$_zm_old_ver" > /opt/zapret-manager-luci/state/cl.pending 2>/dev/null || true
fi
case "$(/opt/zapret-manager-luci/backend.sh zm_changelog_sync 2>/dev/null || true)" in
	*'"ok":true'*) _zmi_ok "Список изменений версии $ZM_NEW_VER загружен — панель покажет его при входе" ;;
esac
( sleep 30; /opt/zapret-manager-luci/backend.sh zm_watch; /opt/zapret-manager-luci/backend.sh adblock_dns_sync ) >/dev/null 2>&1 </dev/null &
_zmi_say "Убираем временные файлы и остатки прошлых версий"
_zm_cl="$(/opt/zapret-manager-luci/backend.sh zm_cleanup install 2>/dev/null || true)"
/opt/zapret-manager-luci/backend.sh zm_autoclean sync >/dev/null 2>&1 || true
if [ -f /opt/zapret-manager-luci/state/autoclean.upd ]; then
	_zmi_ok "После обновления панель сама почистит мусор — как кнопка «Очистить»"
	( sleep 20; /opt/zapret-manager-luci/backend.sh zm_cleanup postupd ) >/dev/null 2>&1 </dev/null &
fi
_zm_cl_f="$(printf '%s' "$_zm_cl" | sed -n 's/.*"freed_flash_kb":\([0-9]*\).*/\1/p')"
_zm_cl_t="$(printf '%s' "$_zm_cl" | sed -n 's/.*"freed_tmp_kb":\([0-9]*\).*/\1/p')"
_zm_cl_s="$(printf '%s' "$_zm_cl" | sed -n 's/.*"flash_kb":\([0-9]*\).*/\1/p')"
if [ -n "$_zm_cl_s" ]; then _zmi_ok "Освобождено: флеш ${_zm_cl_f:-0} КБ, /tmp ${_zm_cl_t:-0} КБ. Панель занимает на флеше ${_zm_cl_s} КБ"
else _zmi_ok "Готово"; fi

ZMW_PORT="$(uci -q get uhttpd.zmweb.listen_http | tr ' ' '\n' | head -n1 | sed 's/.*://')"
ZMW_IP="$(/opt/zapret-manager-luci/backend.sh lan_ip 2>/dev/null || true)"
[ -n "$ZMW_IP" ] || ZMW_IP="192.168.1.1"

for _zm_c in zms zmw; do
    cat > "/usr/bin/$_zm_c" <<'ZM_LAUNCHER_EOF'
#!/bin/sh
set -e
umask 077
installer="$(mktemp /tmp/zm-install.XXXXXX)"
trap 'rm -f "$installer"' EXIT HUP INT TERM
url="https://raw.githubusercontent.com/Ra1nek/Zapret-Manager/main/ZapretManager_LuCI.sh"
if [ -x /opt/zapret-manager-luci/backend.sh ]; then
    /opt/zapret-manager-luci/backend.sh gh_get "$url" "$installer" 180
elif command -v curl >/dev/null 2>&1; then
    curl -fL --connect-timeout 15 --max-time 180 "$url" -o "$installer"
else
    wget -O "$installer" "$url"
fi
grep -qF 'for Forkop/NFQWS2.' "$installer"
sh -n "$installer"
sh "$installer" "$@"
ZM_LAUNCHER_EOF
    chmod 0755 "/usr/bin/$_zm_c"
done
( /opt/zapret-manager-luci/backend.sh zm_stats_hit ) >/dev/null 2>&1 </dev/null &
_zm_login_restart() {
	if [ -x /etc/init.d/rpcd ]; then
		/etc/init.d/rpcd restart >/dev/null 2>&1 || true
		sleep 2
		pidof rpcd >/dev/null 2>&1 || { /etc/init.d/rpcd start >/dev/null 2>&1 || true; sleep 2; }
		_zm_i=0
		while command -v ubus >/dev/null 2>&1 && [ "$_zm_i" -lt 15 ] && ! ubus -t 3 list zapret-manager >/dev/null 2>&1; do sleep 1; _zm_i=$((_zm_i + 1)); done
	fi
	if [ -x /etc/init.d/uhttpd ]; then
		/etc/init.d/uhttpd restart >/dev/null 2>&1 || true
		sleep 2
		pidof uhttpd >/dev/null 2>&1 || { /etc/init.d/uhttpd start >/dev/null 2>&1 || true; sleep 2; }
	fi
}
_zm_login_ok() {
	local q t rc=0 r=""
	q='{"ubus_rpc_session":"00000000000000000000000000000000","scope":"ubus","object":"session","function":"access"}'
	[ -x /etc/init.d/rpcd ] && { pidof rpcd >/dev/null 2>&1 || return 1; }
	[ -x /etc/init.d/uhttpd ] && { pidof uhttpd >/dev/null 2>&1 || return 1; }
	if command -v ubus >/dev/null 2>&1; then
		t="$(date +%s)"
		ubus -t 5 call session access "$q" >/dev/null 2>&1 || rc=$?
		[ "$rc" = 7 ] && return 1
		[ $(( $(date +%s) - t )) -le 3 ] || return 1
	fi
	if [ "$ZMW_OK" = 1 ] && command -v curl >/dev/null 2>&1; then
		t="$(date +%s)"
		r="$(curl -s -m 8 -H 'Content-Type: application/json' -d "{\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"call\",\"params\":[\"00000000000000000000000000000000\",\"session\",\"access\",$q]}" "http://127.0.0.1:${ZMW_PORT:-7788}/ubus" 2>/dev/null || true)"
		case "$r" in *'"jsonrpc"'*) ;; *) return 1 ;; esac
		[ $(( $(date +%s) - t )) -le 4 ] || return 1
	fi
	return 0
}
if [ -x /etc/init.d/rpcd ] || [ -x /etc/init.d/uhttpd ]; then
	_zmi_say "Перезапускаем службы входа rpcd и uhttpd, чтобы LuCI и Web UI сразу открыли новую версию"
	_zm_login_restart
	if _zm_login_ok; then _zmi_ok "rpcd и uhttpd перезапущены, вход в панель отвечает быстро"
	else
		_zmi_step "Вход в панель отвечает медленно — перезапускаем rpcd и uhttpd ещё раз"
		sleep 3
		_zm_login_restart
		if _zm_login_ok; then _zmi_ok "rpcd и uhttpd перезапущены, вход в панель отвечает быстро"
		else _zmi_warn "Вход в панель всё ещё отвечает медленно — выполните: /etc/init.d/rpcd restart; sleep 3; /etc/init.d/uhttpd restart"; fi
	fi
fi
if [ "$ZMW_OK" = 1 ]; then _zmi_ok "Web UI включён на порту ${ZMW_PORT:-7788}"
elif [ "$ZMW_OK" = 2 ]; then _zmi_ok "Web UI выключен — включить его и сменить порт можно в LuCI: Zapret Manager → Система → Web UI"
else _zmi_warn "Web UI не включён: на роутере нет веб-сервера uhttpd или не установился uhttpd-mod-ubus"; fi
echo -e "\n${GREEN}Готово: Zapret Manager для LuCI и Web $ZM_NEW_VER установлен${NC}\n"
echo -e "${CYAN}LuCI:   ${NC}Службы → Zapret Manager"
[ "$ZMW_OK" = 1 ] && echo -e "${CYAN}Web UI: ${NC}http://${ZMW_IP}:${ZMW_PORT:-7788}"
echo
